export interface AttachedClient {
  clientId: string;
  connection: JsonRpcConnection;
  clientInfo?: { name: string; version?: string };
  // When true, the daemon refuses any state-changing JSON-RPC method
  // from this connection (session/prompt, session/cancel, etc.).
  // Set during session/attach from SessionAttachParams.readonly.
  readonly?: boolean;
}

export type CachedNotification = HistoryEntry;

export interface SpawnReplacementAgentParams {
  agentId: string;
  cwd: string;
  agentArgs?: string[];
  // Env to forward into the freshly spawned agent on respawn (/hydra
  // restart, forceCancel). Carried from Session.forwardedEnv so the
  // replacement process matches the persisted spawn-env.
  forwardedEnv?: Record<string, string>;
  // MCP server descriptors passed to session/new on the fresh agent.
  // Used by swapUpstream to bootstrap a new upstream session with the
  // same tooling context as the current one.
  mcpServers?: unknown[];
}

export interface SpawnReplacementAgentResult {
  agent: AgentInstance;
  upstreamSessionId: string;
  agentMeta?: Record<string, unknown>;
  agentCapabilities?: AgentCapabilities;
  // The new agent's advertised model/mode lists and current selections,
  // as reported in its session/new response. Carried through so an agent
  // switch / restart can re-advertise the full set to clients rather than
  // leaving the dropdowns empty — agents that advertise via the session/new
  // response (e.g. opencode's configOptions) never emit a follow-up
  // current_model_update notification to repopulate them.
  initialModel?: string;
  initialModels?: AdvertisedModel[];
  initialMode?: string;
  initialModes?: AdvertisedMode[];
  // Which verb this agent takes for model changes, inferred from the
  // shape of its session/new response (see core/model-verb.ts).
  // Undefined when the response advertised no models at all.
  modelVerb?: ModelVerb;
}

export type SpawnReplacementAgent = (
  params: SpawnReplacementAgentParams,
) => Promise<SpawnReplacementAgentResult>;

// Callback type for rollback: spawns a fresh agent process and resumes
// the given upstream session via session/load (not session/new). Provided
// by SessionManager; absent in tests that don't need rollback.
export type LoadExistingAgentSession = (
  upstreamSessionId: string,
  params: SpawnReplacementAgentParams,
) => Promise<SpawnReplacementAgentResult>;

// Snapshot of the most recent usage_update notification: tokens used,
// context size, and cost. Fields are individually optional so a fresh
// event can update only what it carries while preserving prior values
// for everything else.
export interface UsageSnapshot {
  used?: number;
  size?: number;
  costAmount?: number;
  costCurrency?: string;
  // Accumulated cost from prior agent lives within this hydra session.
  // The displayed total is cumulativeCost + costAmount.
  cumulativeCost?: number;
}

/**
 * Verbs accepted by `/hydra workspace`.
 *
 * One list, exported, because it is duplicated three ways otherwise: the
 * hook signature here, the runtime guard in runWorkspaceCommand, and
 * SessionManager's dispatch. A verb added to two of the three is a verb
 * that either type-checks and is rejected at runtime, or is accepted and
 * dispatches nowhere.
 */
export const WORKSPACE_VERBS = [
  "start",
  "merge",
  "sync",
  "stop",
  "detach",
  "discard",
  "clean",
  "status",
] as const;
export type WorkspaceVerb = (typeof WORKSPACE_VERBS)[number];

export interface SessionInit {
  cwd: string;
  agentId: string;
  agent: AgentInstance;
  upstreamSessionId: string;
  title?: string;
  sessionId?: string;
  agentMeta?: Record<string, unknown>;
  // Capabilities the agent advertised in its initialize response.
  // Captured by SessionManager.bootstrapAgent and doResurrect so we
  // don't have to re-probe the agent later. Used by cat --stream to
  // pick between MCP and file surfaces.
  agentCapabilities?: AgentCapabilities;
  // Verb this agent takes for model changes, inferred by SessionManager
  // from the session/new / session/load response shape. Only the lead
  // verb — forwardModelChange still probes if the agent disagrees.
  modelVerb?: ModelVerb;
  agentArgs?: string[];
  idleTimeoutMs?: number;
  // Pino-style logger for close + idle paths. Optional so tests/consumers
  // that construct Session directly aren't forced to provide one.
  logger?: { info: (msg: string) => void; warn: (msg: string) => void };
  // Optional callback used by /hydra agent to spawn a fresh agent
  // process and run initialize + session/new on it. Provided by
  // SessionManager so Session doesn't have to depend on the registry.
  spawnReplacementAgent?: SpawnReplacementAgent;
  // Optional callback to mint a fresh per-session mcpServers config
  // for a NEW agent process spawned mid-life (currently just the
  // compaction swap path). Re-minting forces the MCP-server build
  // cache (keyed by token) to miss, so tools that gate on session
  // state — e.g. recall_* registering only when summarizedThroughEntry
  // > 0 — get re-evaluated against the current state. Without re-mint
  // the cached pre-compaction MCP server (no recall tools) is reused
  // forever. The callback receives the live Session so it can bind
  // disposer for the new tokens (cleanup on session close). When
  // undefined, swap falls back to the original mcpServersConfig
  // captured at session construction.
  mintMcpServersForSwap?: (session: Session) => Promise<unknown[]>;
  // Every recordAndBroadcast entry is persisted here. attach()/getHistorySnapshot()
  // load from this store on demand — Session keeps no in-memory copy.
  historyStore?: HistoryStore;
  // Cap on entries retained in the on-disk history.jsonl. The compaction
  // trigger is derived as 20% of this value (min 1), so larger caps also
  // compact less often. Defaults to 1000 if omitted.
  historyMaxEntries?: number;
  // Snapshot state restored from meta.json on cold resurrect, so the
  // first attach response can deliver the right model/mode/commands
  // via _meta before the agent re-emits.
  currentModel?: string;
  currentMode?: string;
  currentUsage?: UsageSnapshot;
  // True when the agent this session is being wired to reloads the SAME
  // upstream session that produced currentUsage.cumulativeCost (cold
  // resurrect via session/load). Arms the cost-ledger probe so a
  // session-scoped agent that re-reports its whole history doesn't
  // double-count. Must stay false/absent when the agent gets a fresh
  // upstream session (import reseed), where the banked total is real
  // prior spend that the new agent knows nothing about.
  reloadsUpstreamLedger?: boolean;
  agentCommands?: AdvertisedCommand[];
  agentModes?: AdvertisedMode[];
  agentModels?: AdvertisedModel[];
  // Suppress the first-prompt title heuristic. Set by SessionManager
  // when resurrecting a session whose title is already meaningful (from
  // a prior life's prompt seed, /hydra title, or background synopsis) —
  // without this, the next prompt would clobber the persisted title.
  firstPromptSeeded?: boolean;
  // Fire-and-forget callback used by `/hydra title` (no arg) to ask the
  // SessionManager to schedule an out-of-band synopsis for this session.
  // Returns immediately; the synopsis lands later via persistSynopsis.
  scheduleSynopsis?: () => void;
  // Fire-and-forget callback letting SessionManager snapshot an isolated
  // session's workspace at a turn boundary. Session deliberately knows
  // nothing about providers or git; it only knows when a turn ended.
  // MUST return immediately: snapshotting a large tree can take a while
  // and must never sit on the turn-completion path.
  scheduleWorkspaceSnapshot?: () => void;
  // Fire-and-forget callback used by `/hydra compact` and `/hydra agent`
  // to schedule a compaction-style job on the SessionManager. Returns
  // immediately; the artifact lands later via persistSynopsis +
  // onSynthesisArtifact. When targetAgentId is set, the swap rotates
  // to that agent (the /hydra agent path).
  scheduleCompaction?: (opts?: { targetAgentId?: string }) => void;
  // Canonicalize an agent id typed by the user (e.g. "claude" ->
  // "claude-acp") via the same resolution ladder Registry.getAgent uses.
  // Returns undefined for unknown ids. Used by `/hydra agent` so the
  // slash command accepts the same fuzzy shorthands the `--agent` flag
  // does. When absent, `/hydra agent` uses the raw string as-is.
  resolveAgentId?: (id: string) => Promise<string | undefined>;
  getCompactionState?: () => Promise<CompactionState | undefined>;
  // Reads the persisted pendingAgentSwap field (the target agentId of an
  // in-flight /hydra agent swap, or undefined if none pending).
  getPendingAgentSwap?: () => Promise<string | undefined>;
  createdAt?: number;
  transformChain?: TransformerRef[];
  // How long after the last recordable broadcast before session.idle fires to
  // the transformer chain. 0 disables. Defaults to 30 seconds.
  idleEventTimeoutMs?: number;
  parentSessionId?: string;
  // Local-fork breadcrumbs set when this session was created by
  // hydra-acp/session/fork. Read-only on the live Session; persisted on
  // meta.json so list views can show "branched from <id>".
  forkedFromSessionId?: string;
  forkedFromMessageId?: string;
  // Synthesis-fork state set by two-phase fork. "running" while synopsis
  // generation is in progress, "failed" when it errors. Absent when not a
  // synthesis fork or when synopsis is already present and clean.
  forkSynthesisState?: "running" | "failed";
  // clientInfo from the process that issued session/new. Carried for
  // log attribution and as the legacy hint inside effectiveInteractive.
  originatingClient?: { name: string; version?: string };
  // Tristate marker controlling whether the session shows in default
  // list views. SessionManager sets this from the persisted record on
  // resurrect; the first-prompt path flips undefined → true.
  interactive?: boolean;
  // User-set sort weight. 0 / absent → normal; positive → pinned to top
  // of the picker. Loaded from the persisted record on resurrect.
  priority?: number;
  // Caller-supplied env to forward into the agent process on spawn.
  // Used by SessionManager on the initial bootstrap; reapplied on
  // respawnAgent via the spawnReplacementAgent callback. Updates from
  // a fresh session/attach with _meta["hydra-acp"].env replace this
  // wholesale (including an explicit empty map to clear).
  forwardedEnv?: Record<string, string>;
  // Isolated-workspace binding, when the session has one. `cwd` above
  // must already be workspace.path; SessionManager resolves that before
  // constructing the Session.
  workspace?: PersistedWorkspace;
  /** Reason isolation was requested but fell back; see Session.workspaceError. */
  workspaceError?: string;
  /** Backs `/hydra workspace`; see Session.workspaceHook. */
  workspaceHook?: (
    action: WorkspaceVerb,
    name?: string,
    opts?: { clean?: boolean; deep?: boolean },
  ) => Promise<string>;
  // Optional callback used by /sessions to enumerate all daemon sessions.
  // Provided by SessionManager; omitted in tests that construct Session
  // directly, in which case /sessions emits a not-available notice.
  listSessions?: () => Promise<{ sessionId: string; title?: string; cwd: string; agentId?: string; currentModel?: string }[]>;
  // Registry of commands that running extensions/transformers have
  // registered via hydra-acp/commands/register. Read by
  // handleSlashCommand (to dispatch "/hydra <name> <verb>") and by
  // mergedAvailableCommands (to advertise the entries to clients).
  extensionCommands?: ExtensionCommandRegistry;
  // Synchronous snapshot of the agent catalog a client could swap to,
  // used to populate the `agent` config option's value list. Provided by
  // SessionManager (cached); omitted in tests, in which case the agent
  // option lists only the current agent.
  availableAgents?: () => Array<{
    id: string;
    name?: string;
    description?: string;
  }>;
  // Entry index up to which history has been compacted. Set from the
  // persisted record on cold resurrect so the MCP server can gate
  // recall_* tools accordingly.
  summarizedThroughEntry?: number;
  // Persisted compaction state restored from meta.json on resurrect.
  // Seeded into _liveCompactionPhase so buildStateSnapshotReplay can
  // deliver the current compaction status to freshly-attaching clients
  // before any live broadcast fires.
  compactionState?: CompactionState;
  // Attention flags restored from meta.json on cold resurrect so the
  // session starts with the correct attention state.
  attentionFlags?: AttentionFlag[];
  // MCP server configs to forward to spawnReplacementAgent on swap.
  // Stored verbatim; never re-minted — the per-session MCP tokens are
  // keyed by hydraSessionId (unchanged across swap), so the same config
  // is correct for the replacement agent.
  mcpServers?: unknown[];
  // Spawns a fresh agent process and resumes a previous upstream session
  // via session/load. Used exclusively by rollbackToUpstream to restore
  // the pre-compaction agent context. Provided by SessionManager.
  loadExistingAgentSession?: LoadExistingAgentSession;
  // Called when a real (non-slash, non-ancillary) user turn is dispatched
  // to the agent. SessionManager uses this to clear the rollback breadcrumb
  // so the window closes as soon as conversation continues.
  clearRollbackBreadcrumbHook?: () => void;
  // Called right after a compaction swap completes, with the breadcrumb
  // data needed for rollback. SessionManager uses this to persist the
  // breadcrumb to meta.json.
  onCompactionSwapHook?: (breadcrumb: RollbackBreadcrumb) => void;
  // Called whenever a swap moves the summarizedThroughEntry watermark, so
  // SessionManager can persist it. The watermark is what arms recall, and
  // both gates that read it (the descriptor gate in resurrectFromDisk, the
  // call-time gate in the recall server) read it off the RECORD. A swap
  // that moves it in memory only therefore works until the first cold
  // wake and then loses recall with no error anywhere. That is what the
  // workspace swaps did before this hook existed, since they skip the
  // synopsis generation that used to be the field's only persister.
  persistWatermarkHook?: (summarizedThroughEntry: number) => void;
  // Called when /hydra uncompact is invoked. Provided by SessionManager;
  // performs all guards and the actual rollback. Returns a rejected
  // promise with a descriptive Error on guard failure.
  uncompactHook?: () => Promise<void>;
  // Called when /hydra fork is invoked. Provided by SessionManager;
  // wraps SessionManager.forkSession(sourceSessionId, opts) and returns
  // the new session id plus fork breadcrumb.
  forkHook?: (opts?: {
    mode?: "verbatim" | "synthesis";
    forkAt?: string;
  }) => Promise<{ sessionId: string; forkedFromSessionId: string; forkedAt: string }>;
}

export interface CloseOptions {
  deleteRecord?: boolean;
}

const DEFAULT_HISTORY_MAX_ENTRIES = 1000;

// How long the daemon waits for a transformer that returned "processing" to
// discharge its claim before synthesizing a stop response.
const TRANSFORMER_CLAIM_TIMEOUT_MS = 5 * 60 * 1000; // 5 minutes

interface TransformerClaim {
  resolve: (result: unknown) => void;
  timer: NodeJS.Timeout;
  transformerName: string;
  method: string;
  // Enough state to resume the chain fail-open if the transformer abandons.
  envelope: unknown;
  chainIdx: number;           // index of the transformer that claimed processing
  originatedBy: Set<string>;  // snapshot so resume routing is correct
  // Three chain kinds park claims here:
  //   request       — client→agent request chain (forwardRequest).
  //   response      — agent→client notification chain (runResponseChain).
  //   agent-request — agent→client request chain (runAgentRequestChain),
  //                   currently only session/request_permission.
  side: "request" | "response" | "agent-request";
  // For request-side claims, whether the chain's tail dispatches as an
  // agent request or as an agent notification. Used by the keep-alive
  // fail-open path to resume the chain with the correct tail. Unused
  // for response-side claims.
  tailKind?: "request" | "notification";
}

// Cap on the recently-terminal messageId LRU. Bounds memory growth on
// a long-running session; older entries fall out and resolve to
// target_not_found, which is the correct behavior for an amend that
// targets a turn from minutes ago.
const RECENTLY_TERMINAL_LIMIT = 64;

// How long the agent may go silent inside an unsolicited turn before we
// declare it over. See noteAgentActivity for what an unsolicited turn is.
//
// There is no correct value: the agent gives us no end signal, and a tool
// can legitimately run for half an hour without emitting anything. Measured
// inter-event gaps inside real turns are p50 0.7s / p95 11s / p99 30s (the
// p99 is claude-acp's heartbeat for long-running tools) with a 28-minute
// outlier. 90s clears the heartbeat and the p99 comfortably; the outliers
// just close the turn early, and later activity opens a fresh one. Guessing
// short is deliberate — a spurious extra turn boundary costs one separator
// in the transcript, while guessing long leaves the session pinned BUSY.
const UNSOLICITED_TURN_IDLE_MS = 90_000;

// Cap on the agent-authored label naming what woke an unsolicited turn.
// Renders as a single header line, so anything longer is already unreadable.
const BACKGROUND_TASK_LABEL_MAX = 120;

// Cap on the per-tool-call label cache. Only needs to span the gap between
// a tool call's descriptive update and the later sparse one that carries
// its background-task arming, which is milliseconds in practice; the cap
// just stops a long session accumulating one entry per tool call forever.
const TOOL_LABEL_LIMIT = 128;

// How long an armed background task counts toward the "this session may
// wake itself up" badge when the agent gave no timeout of its own (a
// backgrounded Bash reports none; a Monitor reports timeoutMs).
//
// Any value here is a hint, not a guarantee. Delivery waits for a turn
// boundary, so a task can fire long after its nominal timeout: the trace
// has one armed with timeoutMs=3600000 that was delivered 3h51m later,
// batched with three others. Erring short is the safer direction: a badge
// that clears early degrades to today's behaviour, whereas one that sticks
// claims a wakeup is coming when none is.
const ARMED_TASK_DEFAULT_TTL_MS = 30 * 60 * 1000;

// Hard ceiling on that window for a ONE-SHOT arming (a backgrounded Bash),
// applied even when the agent named a longer timeout of its own.
//
// The agent's timeoutMs answers "how long might this watch run", which is
// not the question. We need "how long should we keep claiming a wakeup is
// coming", and a job can die without a word: killed by a bare `pkill` from
// another Bash, which produces no TaskStop and no notification, so nothing
// ever clears the entry. That happened with a 1-hour Monitor and left the
// session reading BUSY for the rest of the hour.
//
// 15 minutes because measured delays between a turn being released and the
// agent actually resuming were 0s, 72s, 74s, 147s, 309s and 1157s: five of
// the six land inside it. The sixth is the cost, along with any genuinely
// long job (a 30-minute device run clears early), and that cost is a false
// negative, which merely degrades to the behaviour before any of this
// existed. A stale entry instead asserts something untrue.
//
// Safe to keep short precisely because a one-shot has other exits: it fires
// once, on exit, and a resumption discharges it (see openUnsolicitedTurn).
// The ceiling is the backstop for the killed-without-a-word case only.
const ARMED_TASK_MAX_TTL_MS = 15 * 60 * 1000;

// The same ceiling for a REPEATING arming (a Monitor), which needs a much
// longer one because it has fewer exits: it fires once per occurrence and
// stays live afterwards, so a resumption cannot discharge it and the TTL is
// its only exit besides TaskStop. Under the one-shot ceiling a legitimate
// 45-minute device-perf watch went dark 15 minutes in while still reporting
// normally, which is the same false-idle symptom from the other direction.
//
// This is a LIFETIME bound, not a silence budget: nothing renews it. A
// Monitor's whole tool call finishes within seconds of arming — the trace
// shows seven updates in ~2s ending in status "completed", which is the tool
// RETURNING, not the watch ending — and the watch's later events arrive as
// plain agent activity, never as another tool_call_update for that
// toolCallId. So the entry is armed exactly once and expiresAt never moves.
//
// An hour because it is Monitor's own maximum timeout_ms. A non-persistent
// watch cannot outlive the timeout it named, so honouring that timeout is
// the tightest bound available. The cost is a watch whose command exits
// early: nothing reports that, so the entry stays counted until the timeout
// lapses. A persistent watch names no timeout at all and falls back to the
// default above, which is the only thing keeping it mortal.
const ARMED_TASK_REPEATING_MAX_TTL_MS = 60 * 60 * 1000;

// Queue hold (see holdForUnsolicitedTurn). While the agent is mid-way
// through a turn it started by itself, promoting the next user prompt
// drops it onto a running agent, which is what produces interleaved
// answers and a prompt that never appears to finish.
//
// Two bounds, because we cannot see when the agent is done.
//
// QUIET is the optimistic "probably finished" call, deliberately shorter
// than the 90s the turn itself needs to lapse, because 90s is far too long
// to sit on a prompt the user just typed.
//
// It must nonetheless clear a *thinking* pause. claude-acp forwards no
// thought chunks, so a model that stops to reason looks identical to one
// that has finished. Measured inter-event gaps inside real unsolicited
// turns run p95 12.7s / p99 38.8s, and the trace that motivated this work
// has a 25s thinking gap right where the user's prompt landed, and a 20s
// window would have released 5s early and reproduced the very collision
// this exists to prevent. 45s clears the p99.
//
// CAP is a safety net against our own turn tracking wedging open, not a
// "the agent is taking too long" timeout: an agent still streaming at the
// cap genuinely is busy, and dispatching into it is the bad outcome we're
// avoiding. Generous, and the entry stays cancellable throughout.
const UNSOLICITED_HOLD_QUIET_MS = 45_000;
const UNSOLICITED_HOLD_CAP_MS = 180_000;

// Longest the hold sleeps before re-examining its exit conditions. The
// deadlines above are computed exactly, so this only bounds how long we
// stay parked after something *else* changes: a cancel, an amend, or the
// turn closing. Without it the drain loop would sit on a 45s timer holding
// the queue shut for an entry that was cancelled a moment after it started
// waiting.
const UNSOLICITED_HOLD_POLL_MS = 1_000;

// Two flavors of queue entry share the same FIFO. User-prompt entries
// are wire-visible (every transition fires a hydra-acp/prompt_queue_*
// broadcast); internal entries (title regen, agent switch, import seed)
// serialize through the same gate but are invisible to clients — they
// look like a brief moment of busyness from outside.
interface UserPromptQueueEntry {
  kind: "user";
  messageId: string;
  originator: PromptOriginator;
  // clientId is the original sender's id (== originator.clientId), kept
  // separately so broadcastTurnComplete keeps its "exclude originator"
  // semantics even after the entry has been spliced out of the queue.
  clientId: string;
  // The session/prompt prompt array, kept mutable so updateQueuedPrompt
  // can swap it before drainQueue picks the entry up.
  prompt: unknown[];
  enqueuedAt: number;
  cancelled: boolean;
  // True when this entry was created via hydra-acp/prompt/amend rather
  // than session/prompt. The originator has no awaiting session/prompt
  // promise to receive a stopReason on; broadcastTurnComplete therefore
  // includes the originator in the wire turn_complete (no exclusion) so
  // their TUI can clear currentHeadMessageId and adjust pendingTurns.
  wasAmend?: boolean;
  // Set when this entry was synthesized via `route: "queue"` on
  // hydra-acp/message/emit by an in-chain transformer (e.g. the
  // planner originating a worker's turn). forwardRequest must start
  // at chainStartIdx (== emitterIdx + 1) so the emitting transformer's
  // own request:session/prompt intercept is skipped — same skip
  // semantics as emitToChain, but routed through the queue so the
  // full turn lifecycle (broadcastPromptReceived, prompt_queue_*,
  // turnStartedAt, broadcastTurnComplete) fires normally.
  emitterName?: string;
  chainStartIdx?: number;
  resolve: (value: unknown) => void;
  reject: (err: Error) => void;
}

interface InternalQueueEntry {
  kind: "internal";
  messageId: string;
  enqueuedAt: number;
  cancelled: boolean;
  task: () => Promise<unknown>;
  resolve: (value: unknown) => void;
  reject: (err: Error) => void;
}

type QueueEntry = UserPromptQueueEntry | InternalQueueEntry;

export class Session {
  readonly sessionId: string;
  // The session's REAL working directory, and what every spawn path uses.
  // For an isolated session this is the workspace path, not the directory
  // the caller named at session/new; see `workspace` below.
  //
  // Mutable, but ONLY via swapUpstream({ newCwd }). A running process's
  // cwd cannot change, so assigning this without replacing the agent
  // would leave the field describing a directory the agent is not in —
  // and every later respawn would then silently relocate it. The pairing
  // with `workspace` matters too: whenever a binding exists, cwd equals
  // workspace.path, and both are written to the record together.
  cwd: string;
  // agent / agentId / upstreamSessionId are mutable so /hydra agent can
  // replace the underlying agent process while keeping the same Session
  // record. agentMeta is the metadata returned by the agent at session/new
  // time; it gets refreshed on switch too.
  agentId: string;
  agent: AgentInstance;
  upstreamSessionId: string;
  agentMeta: Record<string, unknown> | undefined;
  agentCapabilities: AgentCapabilities | undefined;
  // Which wire verb this agent generation accepts for model changes.
  // Seeded per agent generation from the session/new response shape
  // (see model-verb.ts), refined by agent notifications, and finally
  // pinned by whichever verb an actual call accepted.
  private modelVerb: ModelVerb = MODEL_VERB_SET_MODEL;
  // True once a model change actually succeeded on this agent
  // generation — an accepted call outranks any inference, so hints stop
  // moving `modelVerb` after that.
  private modelVerbConfirmed = false;
  readonly agentArgs: string[] | undefined;
  readonly parentSessionId: string | undefined;
  readonly forkedFromSessionId: string | undefined;
  readonly forkedFromMessageId: string | undefined;
  forkSynthesisState: "running" | "failed" | undefined;
  readonly originatingClient: { name: string; version?: string } | undefined;
  // Tristate. Mutates from undefined → true on first prompt (or directly
  // false if init.interactive === false). Persisted via interactiveHandlers.
  private _interactive: boolean | undefined;
  get interactive(): boolean | undefined {
    return this._interactive;
  }
  // User-set sort weight; see SessionInit.priority. Mutated via
  // setPriority(), which fires onPriorityChange so SessionManager can
  // persist the change to meta.json.
  private _priority: number | undefined;
  get priority(): number | undefined {
    return this._priority;
  }
  title: string | undefined;
  // Entry index up to which history has been compacted. Undefined or 0
  // means no compaction has occurred. Used by the MCP server factory to
  // gate recall_* tools on sessions that have actually been compacted.
  private _summarizedThroughEntry: number | undefined;
  get summarizedThroughEntry(): number | undefined {
    return this._summarizedThroughEntry;
  }
  set summarizedThroughEntry(value: number | undefined) {
    this._summarizedThroughEntry = value;
  }
  // Snapshot state delivered to attaching clients via the attach
  // response _meta rather than via history replay (which would be
  // stale-prone for snapshot-shaped events).
  currentModel: string | undefined;
  currentMode: string | undefined;
  // Persisted compaction state (mirrors SessionInit.compactionState).
  // Surfaces through session-manager.list() so /v1/sessions can report
  // it without resurrecting the session. Settable by tests and the
  // compaction lifecycle code.
  compactionState: CompactionState | undefined;
  // Raw per-agent-life usage. Never read directly outside this class —
  // always access via the currentUsage getter which adds cumulativeCost.
  private _currentUsage: UsageSnapshot | undefined;
  updatedAt: number;
  readonly createdAt: number;

  private clients = new Map<string, AttachedClient>();
  private historyStore: HistoryStore | undefined;
  private promptQueue: QueueEntry[] = [];
  // The entry that drainQueue is currently awaiting. Distinct from
  // promptQueue[0] (which is the *next* one to dequeue): once shifted
  // off, the entry lives here for the duration of its task() so
  // cancelQueuedPrompt can distinguish "still in line" from "running"
  // and return already_running for the latter.
  private currentEntry: QueueEntry | undefined;
  private promptInFlight = false;
  // True only while the agent itself is being driven. Narrower than
  // promptInFlight, which is held for the whole drain loop including
  // entries the daemon answers by itself. Daemon-side slash commands
  // never reach the agent, so during one the agent is genuinely idle —
  // and a command like `/hydra workspace` whose whole job is to swap the
  // agent has to be able to observe that. Keying the swap gate on
  // promptInFlight instead makes such a command refuse itself: it is the
  // in-flight work it is waiting on.
  private agentTurnInFlight = false;
  // Guards against two swaps interleaving. isQuiescedForSwap is a
  // precondition, not a lock: it can be true for two callers at once
  // (a slash command and a REST-driven uncompact, say), and the second
  // swap would then rotate the upstream out from under the first.
  private swapInFlight = false;
  // True while applyModeChange / applyModelChange is executing. Guards
  // isQuiescedForSwap so a mode/model change that arrives mid-prompt
  // (from the agent's current_mode_update / current_model_update) does
  // not make the session appear quiesced during the brief window between
  // the update arriving and the drain loop picking up the next entry.
  private modeChangeInFlight = false;
  private modelChangeInFlight = false;
  // Serialize disk writes to the persisted queue file. Without this
  // chain, fire-and-forget appends/rewrites can interleave (e.g.
  // drainQueue's rewrite-to-empty races a sibling's append-on-
  // enqueue) and leave the file out of sync with in-memory state.
  private queueWriteChain: Promise<unknown> = Promise.resolve();
  private closed = false;
  // Set true at the start of close() / markClosed before any await yields.
  // drainQueue checks this between iterations and bails out, so a queued
  // entry can't be promoted to currentEntry (with its prompt_received and
  // synthesized turn_complete(interrupted)) while the session is tearing
  // down. markClosed sweeps the remaining queue with the normal abandoned
  // / cancelled handling.
  private closing = false;
  // Shared close() promise. Set on first close() entry, cleared after
  // markClosed runs. Subsequent close() calls return this same promise
  // so kill paths can race without double-firing the regen and agent.kill.
  private closeInFlight: Promise<void> | undefined;
  // Sticky intent for deleteRecord: set when close({deleteRecord:true}) is
  // called, consumed by markClosed. Without this, a race where agent.onExit
  // fires markClosed({deleteRecord:false}) during doClose's `await agent.kill()`
  // would drop the delete intent on the floor, leaving the on-disk record
  // after a DELETE /v1/sessions/:id on a warm session.
  private deleteRecordIntent = false;
  private closeHandlers: Array<(opts: { deleteRecord: boolean }) => void> = [];
  private titleHandlers: Array<(title: string) => void> = [];
  // Fire-and-forget hook installed by SessionInit so the slash-command
  // path (`/hydra title` no arg) can ask the manager to schedule an
  // out-of-band synopsis without taking a direct dependency on
  // SessionManager.
  private scheduleSynopsisHook?: () => void;
  private scheduleWorkspaceSnapshotHook?: () => void;
  // Fire-and-forget hook for `/hydra compact` and `/hydra agent` —
  // calls back to the manager's compaction scheduler so the slash
  // commands don't need a direct dependency on SynopsisCoordinator.
  // For /hydra agent, opts.targetAgentId names the agent to swap to.
  private scheduleCompactionHook?: (opts?: { targetAgentId?: string }) => void;
  private resolveAgentIdHook?: (id: string) => Promise<string | undefined>;
  private getCompactionStateHook?: () => Promise<CompactionState | undefined>;
  private getPendingAgentSwapHook?: () => Promise<string | undefined>;
  // In-memory mirror of the last hydra_compaction phase broadcast.
  // Kept so buildStateSnapshotReplay can deliver the current phase to
  // freshly-attaching clients without an async disk read.
  // Cleared when phase is "swapped" or "failed".
  private _liveCompactionPhase: Record<string, unknown> | undefined;
  // Subscribers notified after every entry that's actually persisted to
  // history (skipping snapshot-shaped events filtered by
  // recordAndBroadcast). The HTTP /v1/sessions/:id/history?follow=1
  // endpoint uses this to tail a live session's conversation stream
  // without participating in turns or prompts.
  private broadcastHandlers: Array<(entry: CachedNotification) => void> = [];
  // Epoch ms of the most recent session/cancel we sent to the agent.
  // Used to attribute an id-less error frame from the agent to a cancel
  // (see wireAgent's orphan-error observer). Window kept short so an
  // unrelated later error isn't mislabeled.
  private lastCancelAt = 0;
  private static readonly CANCEL_ERROR_WINDOW_MS = 2000;
  // Set by forceCancel() so the in-flight turn's agent-kill rejection is
  // reported to the originator as a clean "cancelled" stopReason instead of
  // a raw "connection closed" error.
  private forceCancelling = false;
  // True once we've observed our first session/prompt; gates the
  // first-prompt-seeded title so subsequent prompts don't churn it.
  // Also read by SessionManager's onClose hook to decide whether to
  // schedule a background synopsis (sessions that never received a
  // prompt have nothing to summarize).
  private _firstPromptSeeded = false;
  get firstPromptSeeded(): boolean {
    return this._firstPromptSeeded;
  }
  // Wall-clock when the active prompt started, undefined when idle.
  // Bumped by broadcastPromptReceived, cleared by broadcastTurnComplete.
  // Also bumped/cleared by open/closeUnsolicitedTurn, so a session the
  // agent restarted by itself reads BUSY rather than idle.
  // Drives the mid-turn elapsed counter delivered to fresh attachers.
  private promptStartedAt: number | undefined;
  // Set while the agent is taking a turn nobody asked for. See
  // noteAgentActivity. `timer` is the silence deadline; `cause` is the
  // background task we believe woke it, for client labelling.
  private unsolicitedTurn:
    | {
      messageId: string;
      startedAt: number;
      timer: ReturnType<typeof setTimeout> | undefined;
      cause: { toolCallId: string; label: string } | undefined;
    }
    | undefined;
  // Most recent background task the agent armed, harvested from the tool
  // call that armed it. Only used to label an unsolicited turn with what
  // woke it up; nothing depends on it being accurate or present.
  private lastBackgroundTask: { toolCallId: string; label: string } | undefined;
  // Best label seen per tool call, so a sparse arming update can borrow the
  // description that arrived on an earlier update for the same call. See
  // rememberToolLabel. FIFO-trimmed at TOOL_LABEL_LIMIT.
  private toolLabels = new Map<
    string,
    { label: string; fromDescription: boolean }
  >();
  // Background tasks the agent has armed and that we have not yet seen it
  // wake up for, keyed by toolCallId. Drives the "may wake itself up"
  // signal on the session list. Best-effort by nature; see
  // ARMED_TASK_DEFAULT_TTL_MS.
  private armedTasks = new Map<
    string,
    {
      label: string;
      taskId?: string;
      // A repeating watch (Monitor) rather than a one-shot (backgrounded
      // Bash). Governs both which TTL ceiling applies and whether a
      // resumption discharges the entry. See isRepeatingArming.
      repeating: boolean;
      armedAt: number;
      expiresAt: number;
    }
  >();
  private armedExpiryTimer: ReturnType<typeof setTimeout> | undefined;
  // Last {count, since} pushed to clients, so a mutation that doesn't move
  // the rendered state (re-arming a task already counted) stays silent.
  private lastArmedBroadcast: { count: number; since: number | undefined } |
    undefined;
  // Whether a turn has ever ended on this session in this process. Gates
  // unsolicited-turn detection: the failure mode is an agent *resuming*
  // after a turn ended, so before the first turn_complete there is nothing
  // to resume from and stray agent chatter is something else (a chatty
  // agent, a seed replay). Resets across a daemon restart, which only
  // costs detection until the session's next turn ends.
  private sawTurnComplete = false;
  // Wall-clock of the last turn-content update the agent sent, whether or
  // not a prompt was in flight. Drives the queue hold's quiet check, which
  // needs "is the agent still talking" independent of whose turn it is.
  private lastAgentActivityAt = 0;
  // Counts appends since the last compaction. When it hits compactEvery
  // we ask the history store to trim the file to the most recent
  // historyMaxEntries. Keeps file growth bounded without per-append
  // file-size checks.
  private appendCount = 0;
  private historyMaxEntries: number;
  private compactEvery: number;
  // In-memory callbacks for permission requests raised as attention flags.
  // Keyed by the requestId suffix of the corresponding flag reason
  // ("permission:<requestId>"). Does NOT persist — rebuilt as new
  // permission requests arrive after a restart.
  private permissionCallbacks = new Map<string, (client: AttachedClient) => void>();
  // Per-session attention flags keyed by `${source}::${reason}`.
  // Used by clients to surface "attention" state without scanning history.
  private attentionFlags = new Map<string, AttentionFlag>();
  // True when any daemon-raised permission flag is still pending.
  private get hasPermissionFlag(): boolean {
    for (const flag of this.attentionFlags.values()) {
      if (flag.source === "daemon" && flag.reason.startsWith("permission:")) {
        return true;
      }
    }
    return false;
  }
  private attentionFlagsChangeHandlers: Array<(flags: AttentionFlag[]) => void> = [];
  // While set, agent-emitted session/update notifications are
  // captured into `chunks` and NOT broadcast to clients. Used by
  // /hydra slash-command sub-prompts (e.g. title regeneration) so
  // the conversation log doesn't get polluted with the meta-prompt
  // and its reply.
  private internalPromptCapture:
    | {
        chunks: string[];
        toolCalls: number;
        thinkingChars: number;
        messageChars: number;
        lastUsed?: number;
        lastSize?: number;
      }
    | undefined;
  private idleTimeoutMs: number;
  private idleTimer: NodeJS.Timeout | undefined;
  // Separate timer that fires session.idle to the transformer chain after
  // a quiet period. Distinct from idleTimer, which drives session close.
  private idleEventTimeoutMs: number;
  // Handlers registered via onIdle/onceIdle. Fire on quiesce edges
  // (isQuiescedForSwap flipping false→true). debounceMs=0 fires
  // immediately; >0 schedules a delayed fire that is cancelled if the
  // session becomes non-quiesced before the timer expires.
  private idleHandlers: Array<{
    fn: (s: Session) => void;
    once: boolean;
    debounceMs: number;
    timer?: NodeJS.Timeout;
  }> = [];
  // Time of the last recordable broadcast (or session creation, if
  // none yet). Drives the inactivity-based idle close; deliberately
  // does NOT include snapshot state pings (model/mode/title/commands)
  // or attach/detach, which would otherwise let passive observers
  // and noisy state churn keep a quiet session alive forever.
  private lastRecordedAt: number;
  private spawnReplacementAgent: SpawnReplacementAgent | undefined;
  private mintMcpServersForSwap: ((session: Session) => Promise<unknown[]>) | undefined;
  private loadExistingAgentSession: LoadExistingAgentSession | undefined;
  private clearRollbackBreadcrumbHook: (() => void) | undefined;
  private onCompactionSwapHook: ((breadcrumb: RollbackBreadcrumb) => void) | undefined;
  private persistWatermarkHook: ((summarizedThroughEntry: number) => void) | undefined;
  private uncompactHook: (() => Promise<void>) | undefined;
  private forkHook:
    | ((opts?: {
        mode?: "verbatim" | "synthesis";
        forkAt?: string;
      }) => Promise<{ sessionId: string; forkedFromSessionId: string; forkedAt: string }>)
    | undefined;
  private readonly mcpServersConfig: unknown[] | undefined;
  // See SessionInit.forwardedEnv. Mutable so a fresh session/attach can
  // overwrite it; read by respawnAgent to thread into the replacement
  // spawn, and by SessionManager.mergeForPersistence to round-trip
  // through meta.json.
  forwardedEnv: Record<string, string> | undefined;
  // Set when this session runs in an isolated workspace. Metadata only:
  // deliberately NOT threaded into any spawn path, because `cwd` above is
  // already the workspace path, so respawn, cold resurrect, and
  // replacement spawns all land in the right place with no extra
  // plumbing. Anyone tempted to pass this to the spawner should check
  // that invariant first rather than adding a second source of truth.
  //
  // Read by SessionManager for the session-list cwd filter (a session
  // must be findable by the tree it derives from, not only by where it
  // physically runs) and for the `_meta["hydra-acp"].workspace`
  // projection.
  // Mutable only through swapIntoWorkspace / clearWorkspaceBinding, which
  // keep it in lockstep with `cwd`. Assigning it directly would let the
  // record claim an isolation that the agent's actual working directory
  // contradicts.
  workspace: PersistedWorkspace | undefined;
  // Why isolation was asked for and did not happen. Set only on the
  // fail-open path, so `workspace === undefined && workspaceError !== undefined`
  // is the "you asked and did not get it" case a client needs to surface.
  //
  // Live-only, deliberately not persisted: it describes THIS creation
  // attempt, and a later resurrect may well succeed (or fail differently)
  // once the tree it complained about has changed.
  readonly workspaceError: string | undefined;
  // Provider-supplied caveats about this workspace (empty submodules,
  // `.git` being a file, and so on). Populated by SessionManager after
  // the workspace exists; folded into the orientation preamble so an
  // agent does not try to "repair" an artifact of isolation.
  workspaceNotes: readonly string[] = [];
  // Backs `/hydra workspace <verb>`. Wired by SessionManager, which owns
  // the provider registry and the record store. Returns the message to
  // show the user.
  private workspaceHook:
    | ((
        action: WorkspaceVerb,
        name?: string,
        opts?: { clean?: boolean; deep?: boolean },
      ) => Promise<string>)
    | undefined;
  // Whether the orientation preamble has ridden a prompt yet. Drives
  // introduce-once, then re-assert only when a prompt names the source
  // tree.
  private workspacePreambleSent = false;
  // The workspace this session most recently LEFT, kept after the binding
  // is cleared.
  //
  // Needed because leaving does not erase the agent's memory: its context
  // is full of paths under a directory that is no longer where its work
  // belongs. This drives a one-time departure note and an ongoing rewrite
  // of stale workspace paths, which is the mirror of what the entry
  // preamble and inbound rewriting do.
  //
  // Retained indefinitely rather than cleared after one turn: a stale
  // reference can surface many turns later, when the agent revisits
  // something it did before the swap.
  private formerWorkspace:
    | { path: string; sourceCwd: string; removed: boolean }
    | undefined;
  private departureNoteSent = false;
  private listSessions: SessionInit["listSessions"];
  private logger: SessionInit["logger"];
  private transformChain: TransformerRef[];
  private extensionCommands: ExtensionCommandRegistry | undefined;
  private extensionCommandsUnsub: (() => void) | undefined;
  // Outstanding "processing" claims: token → claim waiting for respondsTo discharge.
  private pendingClaims = new Map<string, TransformerClaim>();
  // Edge-trigger state for synthesized lifecycle events. Both maps live
  // for the lifetime of the session and are cleared in markClosed.
  //   toolCompletionSeen: toolCallId → terminal status that was already
  //     emitted as lifecycle:tool.completed. Prevents duplicate emits
  //     when the agent re-sends a tool_call_update with the same
  //     completed/failed status, or transitions failed→completed across
  //     a retry. We key on toolCallId, so the first terminal status
  //     wins per call.
  //   toolCallKind: toolCallId → tool kind ("edit", "execute", …) from
  //     the originating tool_call. Used to gate file.edited emission to
  //     edit-kind tools only (avoiding over-fire on grep/read). The
  //     remember-the-first-kind rule is shared with the other consumers of
  //     this wire shape — see core/tool-edit.ts.
  //   filesEditedSeen: paths already emitted as lifecycle:file.edited.
  //     Dedups across multiple tool_call_update events that re-emit the
  //     same path, and across multiple edit-kind tool calls touching
  //     the same file.
  private toolCompletionSeen = new Map<string, string>();
  private toolCallKind = new ToolKindTracker();
  private filesEditedSeen = new Set<string>();
  private agentChangeHandlers: Array<
    (info: {
      agentId: string;
      upstreamSessionId: string;
      // Spend on the upstream we just rotated OFF, captured by
      // accumulateAndResetCost before costAmount is reset. Recorded onto
      // the retiring generation entry so the figure survives the history
      // ring evicting that generation's usage_update rows.
      retiredCost?: number;
    }) => void
  > = [];
  // Set by accumulateAndResetCost, consumed by the next agentChange
  // notification. Not persisted directly — it only has to live long
  // enough to reach the generation entry.
  private retiringGenerationCost: number | undefined;
  // Last available_commands_update we observed from the agent. Stored
  // so we can re-broadcast a merged (hydra ∪ agent) list whenever
  // either half changes, and persisted to meta.json so a fresh attach
  // can deliver the merged list via _meta without depending on history
  // replay.
  private agentAdvertisedCommands: AdvertisedCommand[] = [];
  // Last available_modes_update we observed from the agent. Same
  // pattern as commands: cache, persist, broadcast on change.
  private agentAdvertisedModes: AdvertisedMode[] = [];
  // Last availableModels payload we observed (from current_model_update,
  // a session/new / session/load response, or — for opencode — a
  // config_option_update where configOptions[i].id === "model").
  // Cached so a mid-session attach can synthesize a model picker
  // snapshot, and so session/set_model can validate the requested id
  // against what the agent claims to support.
  private agentAdvertisedModels: AdvertisedModel[] = [];
  // Extra, non-standard config options advertised by the agent (e.g.
  // "effort", "thought_level"). Stored so buildConfigOptions can surface
  // them alongside model/mode/agent — agents like opencode carry these
  // only in config_option_update, never via a dedicated notification.
  private agentAdvertisedConfigOptions: ConfigOption[] = [];
  // Persist hooks for snapshot-shaped state. SessionManager hooks these
  // to mirror changes into meta.json so cold-resurrect attaches can
  // surface the latest snapshot via the attach response _meta.
  private agentCommandsHandlers: Array<
    (commands: AdvertisedCommand[]) => void
  > = [];
  private agentModesHandlers: Array<(modes: AdvertisedMode[]) => void> = [];
  private agentModelsHandlers: Array<(models: AdvertisedModel[]) => void> = [];
  private availableAgentsFn?: () => Array<{
    id: string;
    name?: string;
    description?: string;
  }>;
  private modelHandlers: Array<(model: string) => void> = [];
  private modeHandlers: Array<(mode: string) => void> = [];
  private interactiveHandlers: Array<(interactive: boolean) => void> = [];
  private priorityHandlers: Array<(priority: number | undefined) => void> = [];
  private usageHandlers: Array<(usage: UsageSnapshot) => void> = [];
  private cumulativeCost: number = 0;
  // Cost carried over from a RELOADED upstream session — the previous life's
  // raw costAmount for the same upstream session id, retained across a cold
  // resurrect or rollback rather than banked into cumulativeCost.
  //
  // Agents disagree about what cost.amount accumulates over. OpenCode scopes
  // it to the upstream session (acp/usage.ts sends totalSessionCost(messages),
  // a re-sum of every assistant message), so on reload it re-reports the whole
  // history; replacement then yields the right number and banking would double
  // it. Other agents restart at $0 on reload, in which case the retained
  // amount is the only record of that life's spend and must be banked.
  //
  // We can't know which a priori, so we defer: retain the amount, and let the
  // first cost report of the new life adjudicate. See reconcileCostLedger.
  private costLedgerProbe: number | undefined;

  // The split, for persistence: costAmount is the CURRENT life's raw amount
  // and cumulativeCost is spend from retired upstream sessions. Keeping the
  // two apart on disk is what lets a later resurrect arm the ledger probe
  // against the right quantity — collapsing them (as `currentUsage` does)
  // loses the information permanently.
  //
  // Readers of meta.json must sum the two fields. Daemons predating the split
  // wrote the total into costAmount and omitted cumulativeCost, so summing is
  // correct against either layout.
  get persistableUsage(): UsageSnapshot | undefined {
    if (!this._currentUsage && !this.cumulativeCost) {
      return undefined;
    }
    return {
      ...(this._currentUsage ?? {}),
      ...(this.cumulativeCost
        ? { cumulativeCost: this.cumulativeCost }
        : { cumulativeCost: undefined }),
    };
  }

  // Total cost across all agent lives. costAmount in the returned snapshot
  // is cumulativeCost + the current agent's raw amount so every consumer
  // gets the right figure without knowing about the internal split.
  // cumulativeCost is stripped from the return value so it never leaks
  // into live-consumer paths (REST currentUsage, history.jsonl usage_update)
  // that have always seen a single collapsed total.
  get currentUsage(): UsageSnapshot | undefined {
    if (!this._currentUsage && !this.cumulativeCost) {
      return undefined;
    }
    const base = this._currentUsage ?? {};
    const total = this.cumulativeCost + (base.costAmount ?? 0);
    return {
      ...base,
      costAmount: total || undefined,
      cumulativeCost: undefined,
    };
  }
  // Set by amendPrompt at the start of a cancel-and-resubmit dance.
  // broadcastTurnComplete reads it to attach the _meta.amended marker
  // to the cancelled turn's turn_complete notification, and to fire the
  // dedicated prompt_amended notification. Cleared when the cancelled
  // turn's task completes (runQueueEntry) OR if the amendment is
  // cancelled mid-window via cancel_prompt(M2) before drainQueue picks
  // it up.
  private amendInProgress:
    | { cancelledMessageId: string; newMessageId: string }
    | undefined;

  // Per-messageId record of an in-flight extension `commands/invoke`
  // dispatch. Populated when runExtensionCommandInline starts the
  // request to the extension's connection, cleared on settle.
  // amendOnHead / Session.cancel / markClosed consult this to send
  // `hydra-acp/commands/cancel` directly to the owning extension's
  // connection when the entry is being cancelled — extensions live
  // outside the client broadcast fanout, so they need a dedicated
  // notification channel.
  //
  // `cancel(reason)` triggers the extension's cancel notification
  // (best-effort) and resolves the in-flight race in
  // runExtensionCommandInline with a synthesized cancelled
  // response — so drainQueue advances even if the extension is slow
  // to release its commands/invoke.
  private inFlightExtensionDispatches = new Map<
    string,
    {
      extensionName: string;
      connection: JsonRpcConnection;
      cancel: (reason: "amended" | "cancelled" | "abandoned") => void;
    }
  >();
  // LRU of recently-terminal messageIds → stopReason. Used by
  // amendPrompt to resolve targets that completed/cancelled before
  // the amend arrived. Capped at RECENTLY_TERMINAL_LIMIT entries;
  // older entries fall out and resolve to target_not_found, which is
  // the correct behavior.
  private recentlyTerminal = new Map<
    string,
    { stopReason: string; terminatedAt: number }
  >();
  // Optional ring buffer for piped stdin, populated by openStream() when
  // a cat --stream session attaches. Lifecycle follows the session — the
  // markClosed path closes the buffer and unlinks any file projection.
  private streamBuffer: SessionStreamBuffer | undefined;
  private streamFilePath: string | undefined;

  constructor(init: SessionInit) {
    this.sessionId =
      init.sessionId ?? `${HYDRA_SESSION_PREFIX}${generateHydraId()}`;
    this.cwd = init.cwd;
    this.workspace = init.workspace;
    this.workspaceError = init.workspaceError;
    this.workspaceHook = init.workspaceHook;
    this.agentId = init.agentId;
    this.agent = init.agent;
    this.upstreamSessionId = init.upstreamSessionId;
    this.agentMeta = init.agentMeta;
    this.agentCapabilities = init.agentCapabilities;
    this.agentArgs = init.agentArgs;
    this.parentSessionId = init.parentSessionId;
    this.forkedFromSessionId = init.forkedFromSessionId;
    this.forkedFromMessageId = init.forkedFromMessageId;
    this.forkSynthesisState = init.forkSynthesisState;
    this.originatingClient = init.originatingClient;
    this.title = init.title;
    this.scheduleSynopsisHook = init.scheduleSynopsis;
    this.scheduleWorkspaceSnapshotHook = init.scheduleWorkspaceSnapshot;
    this.scheduleCompactionHook = init.scheduleCompaction;
    this.resolveAgentIdHook = init.resolveAgentId;
    this.getCompactionStateHook = init.getCompactionState;
    this.getPendingAgentSwapHook = init.getPendingAgentSwap;
    this.currentModel = init.currentModel;
    this.currentMode = init.currentMode;
    this._currentUsage = init.currentUsage;
    this.cumulativeCost = init.currentUsage?.cumulativeCost ?? 0;
    // Only cold resurrect reloads the upstream session that produced the
    // banked total. Import reseeds mint a fresh upstream session via
    // session/new, so the incoming agent's ledger is unrelated to the
    // imported cost and must never cancel it out.
    if (init.reloadsUpstreamLedger) {
      this.armCostLedgerProbe();
    }
    if (init.agentCommands && init.agentCommands.length > 0) {
      this.agentAdvertisedCommands = [...init.agentCommands];
    }
    if (init.agentModes && init.agentModes.length > 0) {
      this.agentAdvertisedModes = [...init.agentModes];
    }
    if (init.agentModels && init.agentModels.length > 0) {
      this.agentAdvertisedModels = [...init.agentModels];
    }
    this.idleTimeoutMs = init.idleTimeoutMs ?? 0;
    this.idleEventTimeoutMs = init.idleEventTimeoutMs ?? 30_000;
    // Wire the transformer-chain `session.idle` lifecycle event onto the
    // unified idle primitive: fire after `idleEventTimeoutMs` of
    // continuous quiet. notifyChain is a no-op when no transformer in
    // the chain has subscribed to `lifecycle:session.idle`, so this is
    // cheap to leave registered for life.
    if (this.idleEventTimeoutMs > 0) {
      this.onIdle((s) => s.notifyChain("session.idle", {}), {
        debounceMs: this.idleEventTimeoutMs,
      });
    }
    this.spawnReplacementAgent = init.spawnReplacementAgent;
    this.mintMcpServersForSwap = init.mintMcpServersForSwap;
    this.loadExistingAgentSession = init.loadExistingAgentSession;
    this.clearRollbackBreadcrumbHook = init.clearRollbackBreadcrumbHook;
    this.onCompactionSwapHook = init.onCompactionSwapHook;
    this.persistWatermarkHook = init.persistWatermarkHook;
    this.uncompactHook = init.uncompactHook;
    this.forkHook = init.forkHook;
    this.mcpServersConfig = init.mcpServers;
    this.forwardedEnv = init.forwardedEnv;
    this.availableAgentsFn = init.availableAgents;
    this.listSessions = init.listSessions;
    this.logger = init.logger;
    this.transformChain = init.transformChain ?? [];
    this.extensionCommands = init.extensionCommands;
    if (this.extensionCommands) {
      this.extensionCommandsUnsub = this.extensionCommands.onChange(() => {
        if (!this.closed) {
          this.broadcastMergedCommands();
        }
      });
    }
    if (init.firstPromptSeeded) {
      this._firstPromptSeeded = true;
    }
    this._interactive = init.interactive;
    this._priority = init.priority;
    this._summarizedThroughEntry = init.summarizedThroughEntry;
    this.compactionState = init.compactionState;
    if (init.compactionState) {
      const cs = init.compactionState;
      if (
        cs.status === "requested" ||
        cs.status === "running" ||
        cs.status === "swap_pending" ||
        cs.status === "swap_deferred"
      ) {
        if (cs.status === "swap_deferred") {
          this._liveCompactionPhase = {
            phase: "deferred",
            attempts: cs.attempts,
          };
        } else {
          this._liveCompactionPhase = {
            phase: cs.status === "requested" ? "started" : "iteration",
            iter: cs.iter,
          };
        }
      }
    }
    if (init.attentionFlags && init.attentionFlags.length > 0) {
      for (const flag of init.attentionFlags) {
        this.attentionFlags.set(`${flag.source}::${flag.reason}`, flag);
      }
    }
    this.historyStore = init.historyStore;
    this.historyMaxEntries = init.historyMaxEntries ?? DEFAULT_HISTORY_MAX_ENTRIES;
    this.compactEvery = Math.max(1, Math.floor(this.historyMaxEntries * 0.2));
    this.updatedAt = Date.now();
    this.createdAt = init.createdAt ?? this.updatedAt;
    // Resurrection itself is the activity that gets a fresh idle
    // window — even if the disk history is hours old, the user
    // attaching now is current activity.
    this.lastRecordedAt = this.updatedAt;

    this.resetModelVerb(init.modelVerb);
    this.wireAgent(this.agent);
    this.scheduleIdleCheck();
    this.notifyChain("session.opened", {});
  }

  private broadcastMergedCommands(): void {
    this.recordAndBroadcast("session/update", {
      sessionId: this.upstreamSessionId,
      update: {
        sessionUpdate: "available_commands_update",
        availableCommands: this.mergedAvailableCommands(),
      },
    });
  }

  private broadcastAvailableModes(): void {
    this.recordAndBroadcast("session/update", {
      sessionId: this.upstreamSessionId,
      update: {
        sessionUpdate: "available_modes_update",
        availableModes: this.agentAdvertisedModes,
      },
    });
  }

  // Re-broadcast our cached availableModels via current_model_update.
  // Spec shape: { currentModel, availableModels } — we only include the
  // currentModel field when we know it, so this broadcast can also fire
  // model-list updates standalone before any current model is set.
  private broadcastAvailableModels(): void {
    const update: Record<string, unknown> = {
      sessionUpdate: "current_model_update",
      availableModels: [...this.agentAdvertisedModels],
    };
    if (this.currentModel !== undefined && this.currentModel.length > 0) {
      update.currentModel = this.currentModel;
    }
    this.recordAndBroadcast("session/update", {
      sessionId: this.upstreamSessionId,
      update,
    });
  }

  // Register session/update, session/request_permission, and onExit
  // handlers on an agent connection. Re-run on every /hydra agent so
  // the new agent is plumbed identically. The exit handler's identity
  // check is what makes switching safe: when the *old* agent exits as
  // part of a swap, this.agent has already been replaced, so we no-op
  // and don't tear the session down.
  private wireAgent(agent: AgentInstance): void {
    agent.connection.onNotification("session/update", (params) => {
      // /hydra slash-command sub-prompts (e.g. title regeneration)
      // run "behind the scenes" — the agent's chunks for those are
      // captured into a private buffer instead of being broadcast.
      if (this.internalPromptCapture) {
        captureInternalChunk(this.internalPromptCapture, params);
        return;
      }
      // Synthesize edge events (tool.completed, file.edited) before the
      // chain. Edges fire based on what the agent emitted, independent
      // of whether response transformers later drop the update.
      this.maybeEmitToolEdges(params);
      // Chain runs first — no state mutation before this resolves.
      void this.runResponseChain(params);
    });
    agent.connection.onRequest("session/request_permission", async (params) => {
      // Run the agent→client request chain first. A transformer can rewrite
      // the envelope (e.g. narrow options, redact tool args) and pass it
      // through, or short-circuit with a synthesized outcome (auto-approve,
      // auto-deny). After the handler resolves (whether by short-circuit
      // or by user/policy reply), emit lifecycle:permission.replied for
      // audit / observation hooks.
      const chained = await this.runAgentRequestChain(
        "session/request_permission",
        params,
      );
      const toolCallId = extractToolCallId(
        chained.shortCircuit ? params : chained.envelope,
      );
      if (chained.shortCircuit) {
        this.notifyChain("permission.replied", {
          toolCallId: toolCallId ?? null,
          outcome: chained.payload,
          sourceWasTransformer: true,
        });
        return chained.payload;
      }
      const outcome = await this.handlePermissionRequest(chained.envelope);
      this.notifyChain("permission.replied", {
        toolCallId: toolCallId ?? null,
        outcome,
        sourceWasTransformer: false,
      });
      return outcome;
    });
    // Guard: some test doubles / alternate transports don't implement
    // the orphan-error hook. Real JsonRpcConnection always does.
    if (typeof agent.connection.onOrphanError === "function") {
      agent.connection.onOrphanError((error) => {
        this.handleOrphanError(error);
      });
    }
    agent.onExit(() => {
      if (this.agent !== agent) {
        return;
      }
      this.markClosed({ deleteRecord: false });
    });
  }

  // An error frame arrived from the agent that couldn't be matched to a
  // pending request. The canonical case is a reply to our id-less
  // session/cancel notification: agents that don't support cancellation
  // (current opencode) answer with MethodNotFound (-32601) or an
  // UnsupportedOperation error. If one lands within the cancel window,
  // surface it to attached clients so the TUI can tell the user the
  // cancel didn't take rather than silently dropping it.
  private handleOrphanError(error: {
    code?: number;
    message: string;
    data?: unknown;
  }): void {
    const sinceCancel = Date.now() - this.lastCancelAt;
    if (this.lastCancelAt === 0 || sinceCancel > Session.CANCEL_ERROR_WINDOW_MS) {
      this.logger?.warn(
        `agent ${this.agentId} sent uncorrelated error frame code=${error.code} message=${error.message}`,
      );
      return;
    }
    this.lastCancelAt = 0;
    this.logger?.warn(
      `agent ${this.agentId} rejected session/cancel code=${error.code} message=${error.message}`,
    );
    this.broadcastQueueNotification("hydra-acp/cancel_failed", {
      sessionId: this.sessionId,
      code: error.code,
      message: error.message,
    });
  }

  // Runs the response-side transformer chain, then the snapshot interceptors,
  // then recordAndBroadcast. All state mutation happens after the chain exits.
  // See forwardRequest for originatedBy / startIdx semantics.
  //
  // `method` defaults to "session/update" — the only response-side method
  // wired today. The parameter exists so the chain-walk predicate dispatches
  // generically on `response:${method}`, leaving room for future agent→client
  // notifications/requests (fs/*, terminal/*) to share the same plumbing.
  // The post-chain snapshot-extraction and broadcast logic remains
  // session/update-specific and is gated below.
  private async runResponseChain(
    params: unknown,
    originatedBy = new Set<string>(),
    startIdx = 0,
    method = "session/update",
  ): Promise<void> {
    // Transformers and clients see the injected total; maybeApplyAgentUsage
    // must see the raw params so it stores the agent's raw costAmount in
    // _currentUsage, not the already-totalled value (which would double-count
    // on the next injection pass).
    const rawParams = params;
    let envelope = method === "session/update"
      ? this.injectCumulativeCost(params)
      : params;
    const interceptName = `response:${method}`;
    for (let i = startIdx; i < this.transformChain.length; i++) {
      const t = this.transformChain[i]!;
      if (originatedBy.has(t.name)) {
        continue;
      }
      if (!t.intercepts.has(interceptName)) {
        continue;
      }
      const token = `t_${generateChainToken()}`;
      let result: { action: string; payload?: unknown } | undefined;
      try {
        result = await t.connection.request("hydra-acp/transformer/message", {
          token,
          phase: "response",
          method,
          direction: "agent→client",
          sessionId: this.sessionId,
          envelope,
        }) as { action: string; payload?: unknown } | undefined;
      } catch (err) {
        this.logger?.warn(
          `transformer ${t.name} error on ${interceptName}: ${(err as Error).message}`,
        );
        continue;
      }
      const action = result?.action ?? "continue";
      if (action === "stop") {
        return; // daemon never sees this update — no state mutation, no broadcast
      }
      if (action === "processing") {
        const claimIdx = i;
        const claimEnvelope = envelope;
        const claimOriginatedBy = new Set(originatedBy);
        const claimMethod = method;
        await new Promise<void>((resolve) => {
          const timer = setTimeout(() => {
            if (this.pendingClaims.delete(token)) {
              this.broadcastQueueNotification(
                "hydra-acp/transformer/abandoned_request",
                { sessionId: this.sessionId, token, transformerName: t.name },
              );
              // Fail-open: resume from the next transformer rather than dropping.
              void this.runResponseChain(
                claimEnvelope,
                new Set([...claimOriginatedBy, t.name]),
                claimIdx + 1,
                claimMethod,
              )
                .then(() => resolve())
                .catch(() => resolve());
            }
          }, TRANSFORMER_CLAIM_TIMEOUT_MS);
          if (typeof timer.unref === "function") {
            timer.unref();
          }
          this.pendingClaims.set(token, {
            resolve: () => resolve(),
            timer,
            transformerName: t.name,
            method: claimMethod,
            envelope: claimEnvelope,
            chainIdx: claimIdx,
            originatedBy: claimOriginatedBy,
            side: "response",
          });
        });
        return;
      }
      if (result?.payload && typeof result.payload === "object") {
        envelope = result.payload;
      }
      originatedBy.add(t.name);
    }
    // Post-chain processing below is session/update-specific (snapshot
    // extraction, cumulative-cost capture, broadcast). Skip for other
    // methods — those should be added explicitly when wired.
    if (method !== "session/update") {
      return;
    }
    // Before anything is broadcast: decide whether this update belongs to a
    // turn hydra asked for. If not, open a synthetic turn so the session
    // stops reporting itself idle while the agent works. Runs ahead of the
    // broadcast so clients receive turn_started before its first content.
    this.noteAgentActivity(envelope);
    // Snapshot interceptors and broadcast run on the post-chain envelope.
    const agentCmds = extractAdvertisedCommands(envelope);
    if (agentCmds !== null) {
      this.setAgentAdvertisedCommands(agentCmds);
      return;
    }
    const agentModes = extractAdvertisedModes(envelope);
    if (agentModes !== null) {
      this.setAgentAdvertisedModes(agentModes);
      return;
    }
    // Model advertisement shape tells us which verb this agent takes:
    // current_model_update ⇒ session/set_model, config_option_update with
    // a "model" entry ⇒ session/set_config_option (model-verb.ts).
    this.noteModelVerbHint(
      inferModelVerbFromUpdate((envelope as { update?: unknown }).update),
      "session/update",
    );
    if (this.maybeApplyAgentModel(envelope)) {
      this.recordAndBroadcast("session/update", envelope);
      return;
    }
    if (this.maybeApplyAgentMode(envelope)) {
      this.recordAndBroadcast("session/update", envelope);
      return;
    }
    if (this.maybeApplyAgentConfigOption(envelope)) {
      // The agent's own config_option_update carries only the dimensions
      // it owns (mode/model/effort/…) — never the hydra-native `agent`
      // selector. Append it before broadcasting so config-options-aware
      // clients (Zed) see the agent option in the same snapshot rather
      // than having the load-response's merged list clobbered by the
      // agent's partial one.
      this.recordAndBroadcast(
        "session/update",
        this.mergeAgentOptionIntoEnvelope(envelope),
      );
      return;
    }
    if (this.maybeApplyAgentUsage(rawParams)) {
      this.recordAndBroadcast("session/update", envelope);
      return;
    }
    this.maybeApplyAgentSessionInfo(envelope);
    this.recordAndBroadcast("session/update", envelope);
  }

  onAgentChange(
    handler: (info: {
      agentId: string;
      upstreamSessionId: string;
      retiredCost?: number;
    }) => void,
  ): void {
    this.agentChangeHandlers.push(handler);
  }

  get attachedCount(): number {
    return this.clients.size;
  }

  // Roster of currently-attached clients, optionally excluding one
  // clientId. Used by the daemon to populate connectedClients on the
  // session/attach response (per RFD #533) — the freshly-attaching
  // client wants to see who else is on the session but not itself in
  // the list.
  connectedClients(
    excludeClientId?: string,
  ): Array<{ clientId: string; name?: string; version?: string }> {
    const out: Array<{ clientId: string; name?: string; version?: string }> = [];
    for (const client of this.clients.values()) {
      if (excludeClientId && client.clientId === excludeClientId) {
        continue;
      }
      const entry: { clientId: string; name?: string; version?: string } = {
        clientId: client.clientId,
      };
      if (client.clientInfo?.name) {
        entry.name = client.clientInfo.name;
      }
      if (client.clientInfo?.version) {
        entry.version = client.clientInfo.version;
      }
      out.push(entry);
    }
    return out;
  }

  // Wall-clock when the in-flight agent turn began, or undefined when
  // idle. Tracked in-memory by broadcastPromptReceived/broadcastTurnComplete
  // so the daemon can hand a fresh attacher mid-turn the right elapsed
  // time without scanning history. Also covers unsolicited turns, so a
  // session the agent restarted by itself reads BUSY and not WARM.
  get turnStartedAt(): number | undefined {
    return this.promptStartedAt;
  }

  // True while the agent is taking a turn hydra never requested. See
  // noteAgentActivity.
  get inUnsolicitedTurn(): boolean {
    return this.unsolicitedTurn !== undefined;
  }

  // OS pid of the live agent child, for diagnostics only (a local client
  // sampling the agent's resource usage — it has no other way to find the
  // process, since the daemon owns it). Follows an agent swap, because it
  // reads through the current `agent` reference rather than caching.
  get agentPid(): number | undefined {
    return this.agent.pid;
  }

  // True when the agent is blocked on the user: an outstanding
  // session/request_permission (which also carries agent-posed
  // questions — there's no separate "ask the user" request in ACP).
  // Lets pickers show a "waiting on you" glyph distinct from the
  // "actively working" one without having to attach.
  get awaitingInput(): boolean {
    return this.attentionFlags.size > 0;
  }

  // True when the session is safe to swap upstream out from under.
  // Used by T10 to decide whether it is safe to swap the upstream
  // session without losing in-flight work. Returns true only when:
  // - the agent isn't being driven (no prompt in flight to it). Note
  //   this is agentTurnInFlight, not promptInFlight: a daemon-side
  //   slash command occupies the queue without touching the agent, and
  //   the swap-driving commands are themselves such entries.
  // - no tool-call chain is open (every tool_call has a corresponding
  //   tool_call_update with status="completed"|"failed")
  // - no mode_change or model_change transition is in progress.
  // - the agent isn't mid-way through a turn it started by itself.
  async isQuiescedForSwap(): Promise<boolean> {
    if (this.agentTurnInFlight || this.unsolicitedTurn !== undefined) {
      return false;
    }
    // Seeds and other internal prompts drive the agent without going
    // through the queue at all, so they need their own term here.
    if (this.internalPromptCapture !== undefined) {
      return false;
    }
    if (this.modeChangeInFlight || this.modelChangeInFlight) {
      return false;
    }
    const hasOpen = await this._hasOpenToolCall();
    if (hasOpen) {
      return false;
    }
    return true;
  }

  // Synchronous idle check for the onIdle dispatch path, so debounced
  // timers (transformer session.idle) can be scheduled immediately at
  // activity edges without an async hop.
  //
  // Deliberately broader than isQuiescedForSwap in two ways: it skips
  // the history-store scan for open tool calls, and it keys on
  // promptInFlight rather than agentTurnInFlight. "Idle" here means the
  // session is doing nothing at all, which a daemon-side slash command
  // still counts as doing. Consumers needing the swap-strength
  // guarantee re-verify via isQuiescedForSwap before acting.
  isQuiescedSync(): boolean {
    if (this.promptInFlight || this.unsolicitedTurn !== undefined) {
      return false;
    }
    if (this.modeChangeInFlight || this.modelChangeInFlight) {
      return false;
    }
    return true;
  }

  // Swap the upstream session for a fresh one seeded with a compaction
  // artifact (synopsis + verbatim tail turns). The Hydra session identity
  // (sessionId, history.jsonl handle, hydraSessionId) stays intact — only
  // the upstream agent session rotates. Intended to be called after
  // synopsis-based compaction produces a compacted context that fits
  // within the model's context window.
  //
  // Mirrors doResurrectFromImport + seedFromImport in session-manager.ts:
  // spawn fresh agent → initialize → session/new → restore model/mode →
  // seed with compaction transcript → swap references → kill old agent.
  /**
   * Move a live session into an isolated workspace, or back out of one.
   *
   * The agent process cannot change directory, so this replaces it.
   * Everything that makes that safe already lives in swapUpstream, and
   * routing through it is the point rather than an implementation
   * detail: it banks cost into `cumulativeCost` (a bare respawn would
   * silently reset lifetime spend to zero), re-mints `mcpServers` so the
   * recall server rebuilds against current state, waits for quiescence,
   * and re-seeds the new agent with a transcript.
   *
   * `summarizedThroughEntry` is stamped to the current history length,
   * which is the trick fork uses: it arms recall immediately, so the
   * replacement agent can `search` the whole prior conversation, without
   * paying to generate a synopsis first. That matters here because the
   * natural moment to isolate is right after planning, when the
   * conversation is at its most valuable and least worth waiting on.
   *
   * `cwd` and `workspace` move together and are persisted by the caller
   * in one record write. Passing `workspace: undefined` is the exit
   * path: the binding is dropped rather than left pointing at a
   * directory the session has left, which would otherwise make
   * `hydra workspace list` report it as a rebuildable "missing".
   */
  async swapIntoWorkspace(opts: {
    cwd: string;
    workspace: PersistedWorkspace | undefined;
    historyLength: number;
    artifact: SessionSynopsis;
    title?: string;
    /**
     * Set when leaving, so the session can tell the replacement agent
     * that the workspace paths in its context are no longer live. Whether
     * the directory was removed changes the advice: a removed one fails
     * loudly, a retained one silently absorbs work that can never land.
     */
    left?: { path: string; removed: boolean };
  }): Promise<void> {
    await this.swapUpstream({
      artifact: opts.artifact,
      ...(opts.title !== undefined ? { title: opts.title } : {}),
      tailK: 8,
      // A small verbatim floor: the user is mid-thought when they switch,
      // so the last few turns should survive literally rather than only
      // as summary, even though recall can reach the rest.
      tailFloor: 4,
      summarizedThroughEntry: opts.historyLength,
      newCwd: opts.cwd,
      // Direction stated, not inferred. Reading it off this.workspace
      // would depend on the fact that the field is assigned only after
      // the swap returns, which is exactly the kind of ordering nobody
      // should have to know to change this code safely.
      reason: opts.workspace !== undefined ? "workspace-enter" : "workspace-leave",
    });
    this.workspace = opts.workspace;
    if (opts.left !== undefined) {
      this.formerWorkspace = {
        path: opts.left.path,
        sourceCwd: opts.cwd,
        removed: opts.left.removed,
      };
      // Arm the departure note. The replacement agent has not seen it, so
      // this is not a re-assertion.
      this.departureNoteSent = false;
    } else {
      // Entering: any prior departure is irrelevant, and leaving it set
      // would rewrite paths belonging to a workspace two moves ago.
      this.formerWorkspace = undefined;
    }
  }

  async swapUpstream(opts: {
    artifact: SessionSynopsis;
    title?: string;
    tailK: number;
    // Minimum closed turns to include verbatim even when the synopsis
    // covers everything. Compaction passes 0 (lean); /hydra agent
    // passes a small floor for continuity. Defaults to 0.
    tailFloor?: number;
    summarizedThroughEntry?: number;
    // When set, swap to a different agent (the /hydra agent path). When
    // unset (or equal to this.agentId), this is a same-agent compaction
    // rotation. Cross-agent swaps skip model/mode restore (the persisted
    // values belong to the old agent's idiom) and use the new agent's
    // defaults as reported by session/new; agentAdvertisedCommands /
    // models / modes are reset from the fresh response.
    newAgentId?: string;
    // Respawn the agent in a DIFFERENT directory (the `/hydra workspace`
    // path). A process's cwd is fixed at exec, so moving a live session
    // into or out of an isolated workspace can only happen by replacing
    // the agent — which is exactly what this function already does.
    //
    // Routing through here rather than a bespoke respawn is what keeps
    // three easily-missed invariants intact: cost is banked into
    // cumulativeCost (a bare respawn silently resets lifetime spend),
    // mcpServers are re-minted so the recall server re-evaluates its
    // gate, and the swap waits for quiescence first.
    newCwd?: string;
    /**
     * Why this swap is happening, so user-facing messaging can describe
     * the cause rather than the machinery it borrowed. Defaults to
     * "compaction", which is what every pre-existing caller means.
     */
    reason?: "compaction" | "workspace-enter" | "workspace-leave";
  }): Promise<void> {
    const quiesced = await this.isQuiescedForSwap();
    if (!quiesced) {
      throw new Error(
        "session is not quiesced for swap — wait for in-flight work to complete",
      );
    }
    if (this.swapInFlight) {
      throw new Error("a swap is already in progress for this session");
    }
    this.swapInFlight = true;
    try {
      await this.doSwapUpstream(opts);
    } finally {
      this.swapInFlight = false;
    }
  }

  private async doSwapUpstream(opts: {
    artifact: SessionSynopsis;
    title?: string;
    tailK: number;
    tailFloor?: number;
    summarizedThroughEntry?: number;
    newAgentId?: string;
    newCwd?: string;
    /**
     * Why this swap is happening, so user-facing messaging can describe
     * the cause rather than the machinery it borrowed. Defaults to
     * "compaction", which is what every pre-existing caller means.
     */
    reason?: "compaction" | "workspace-enter" | "workspace-leave";
  }): Promise<void> {
    // Pre-swap observation hook. Fires before the agent is replaced so
    // subscribers (notifier, archiver, audit) can stamp the old upstream
    // identity. Notification-only; not cancellable in this stage.
    this.notifyChain("agent.swap", {
      phase: "pre",
      previousUpstreamSessionId: this.upstreamSessionId,
      agentId: this.agentId,
    });

    // Capture current context so we can spawn with matching config.
    const oldAgentId = this.agentId;
    const targetAgentId = opts.newAgentId ?? this.agentId;
    const crossAgent = targetAgentId !== this.agentId;
    // Target directory for the replacement agent. Defaults to where we
    // already are; set by the workspace path to move the session.
    const cwd = opts.newCwd ?? this.cwd;
    const agentArgs = this.agentArgs;
    const forwardedEnv = this.forwardedEnv;
    const persistedModel = this.currentModel;
    const persistedMode = this.currentMode;

    const spawnAgent = this.spawnReplacementAgent;
    if (!spawnAgent) {
      throw new Error("agent spawning not configured for this session");
    }

    // Re-mint mcpServers (fresh tokens for the new agent process) when
    // the daemon wires the callback. The build-time gate on recall_*
    // tools in the stdin MCP route evaluates this session's
    // summarizedThroughEntry on the FIRST request to the stdin URL;
    // that result is then cached forever for that token. Reusing the
    // pre-compaction token would freeze the recall tools in their
    // not-yet-registered state. Fresh tokens force a fresh build,
    // which sees summarizedThroughEntry > 0 and registers the tools.
    // Falls back to the original config when no callback wired (tests,
    // non-WS code paths) — those paths simply skip the rebuild.
    const mcpServers = this.mintMcpServersForSwap
      ? await this.mintMcpServersForSwap(this)
      : (this.mcpServersConfig ?? []);

    // Spawn a fresh agent — bootstrapAgent calls initialize + session/new
    // internally, giving us a new upstreamSessionId. For cross-agent
    // swaps this spawns the TARGET agent's process.
    const fresh = await spawnAgent({
      agentId: targetAgentId,
      cwd,
      agentArgs,
      ...(forwardedEnv ? { forwardedEnv } : {}),
      mcpServers,
    });

    this.accumulateAndResetCost();
    // Commit the new working directory only now that the replacement
    // agent actually exists. Doing it earlier would leave the field
    // lying about where the process is if the spawn failed, and every
    // subsequent respawn reads this value.
    this.cwd = cwd;
    this.wireAgent(fresh.agent);

    // Restore model and mode only for same-agent swaps. Cross-agent
    // swaps inherit the target agent's defaults from session/new — the
    // persisted model/mode were the OLD agent's identifiers and are
    // unlikely to be valid on the new agent.
    if (!crossAgent) {
      await restoreCurrentModel({
        agent: fresh.agent,
        upstreamSessionId: fresh.upstreamSessionId,
        persistedModel,
        agentReportedModel: fresh.initialModel,
        logger: this.logger,
      });
      await restoreCurrentMode({
        agent: fresh.agent,
        upstreamSessionId: fresh.upstreamSessionId,
        persistedMode,
        agentReportedMode: fresh.initialMode,
        logger: this.logger,
      });
    }

    // Drop any buffered session/update notifications that arrived during
    // the restore calls — same race as doResurrect in session-manager.ts.
    fresh.agent.connection.drainBuffered("session/update");

    // Build the compaction seed text from the artifact + verbatim tail.
    let historyEntries: Array<{ method: string; params: unknown }> = [];
    if (this.historyStore) {
      try {
        historyEntries = await this.historyStore.load(this.sessionId);
      } catch (err) {
        // Serious: failure here produces a tail-less seed, silently degrading compaction quality.
        this.logger?.warn(`swapUpstream: historyStore.load failed: ${(err as Error).message}`);
      }
    }

    const seedText = renderCompactionSeed({
      synopsis: opts.artifact,
      title: opts.title,
      tail: historyEntries,
      tailK: opts.tailK,
      tailFloor: opts.tailFloor,
      // Anchor the tail against the synopsis watermark — only turns
      // past summarizedThroughEntry are "new"; older turns are already
      // represented in the synopsis. Floor lets callers force a small
      // continuity overlap on top.
      ...(opts.summarizedThroughEntry !== undefined
        ? { watermark: opts.summarizedThroughEntry }
        : {}),
      // The watermark this swap is about to install is what arms recall,
      // so read it from opts first; a swap that doesn't move it inherits
      // whatever the session already had.
      recallArmed:
        (opts.summarizedThroughEntry ?? this._summarizedThroughEntry ?? 0) > 0,
    });

    // Send the seed as a single session/prompt on the fresh agent. The
    // agent will produce an acknowledgement reply — that reply is not
    // real conversation; we capture it via internalPromptCapture so it
    // is neither broadcast to clients nor written to history.jsonl. The
    // user instead sees the synthetic "Compaction completed." message
    // emitted after the swap settles below.
    if (this.internalPromptCapture) {
      throw new Error("swapUpstream: internal prompt already in flight");
    }
    this.internalPromptCapture = {
      chunks: [],
      toolCalls: 0,
      thinkingChars: 0,
      messageChars: 0,
    };
    try {
      await fresh.agent.connection.request<unknown>("session/prompt", {
        sessionId: fresh.upstreamSessionId,
        prompt: [{ type: "text", text: seedText }],
      });
      const cap = this.internalPromptCapture;
      this.logger?.info(
        `swapUpstream: seed processed sessionId=${this.sessionId} seedChars=${seedText.length} toolCalls=${cap.toolCalls} thinkingChars=${cap.thinkingChars} messageChars=${cap.messageChars} used=${cap.lastUsed ?? "?"} size=${cap.lastSize ?? "?"} reply=${JSON.stringify(cap.chunks.join("").slice(0, 200))}`,
      );
    } finally {
      this.internalPromptCapture = undefined;
    }

    // Capture the pre-swap upstream id + summarizedThroughEntry so the
    // onCompactionSwapHook can persist a rollback breadcrumb before we
    // overwrite the fields below.
    const previousUpstreamSessionId = this.upstreamSessionId;
    const previousSummarizedThroughEntry = this._summarizedThroughEntry;

    if (opts.summarizedThroughEntry !== undefined) {
      this._summarizedThroughEntry = opts.summarizedThroughEntry;
    }

    // Atomically swap: kill the old agent, point this.agent and
    // this.upstreamSessionId at the new one. The in-memory rotation
    // (this.agent / this.upstreamSessionId) and ALL meta-write-triggering
    // hooks (agentChangeHandlers, onCompactionSwapHook, and
    // persistWatermarkHook) fire in one
    // synchronous block BEFORE any await — otherwise any concurrent
    // poller (waitFor-style helpers in tests, picker polls in
    // production) can observe rotation while the breadcrumb /
    // upstream-id meta writes are still un-enqueued, and a follow-up
    // flushMetaWrites would resolve nothing.
    const oldAgent = this.agent;
    this.agent = fresh.agent;
    this.upstreamSessionId = fresh.upstreamSessionId;
    this.agentMeta = fresh.agentMeta;
    this.agentCapabilities = fresh.agentCapabilities;
    this.resetModelVerb(fresh.modelVerb);

    if (crossAgent) {
      this.agentId = targetAgentId;
      // Old agent's advertised commands/models/modes don't apply on the
      // new agent. Clear and refresh from its session/new response —
      // mirrors the inline-swap behavior in the (now-replaced)
      // runAgentCommandInline path so the TUI's dropdowns repopulate
      // even when the agent doesn't emit a follow-up current_model_update.
      this.agentAdvertisedCommands = [];
      this.currentModel = fresh.initialModel;
      this.currentMode = fresh.initialMode;
      this.setAgentAdvertisedModels(fresh.initialModels ?? []);
      this.setAgentAdvertisedModes(fresh.initialModes ?? []);
    }

    // Re-broadcast config options and commands under the new upstream.
    this.broadcastMergedCommands();
    this.broadcastConfigOptions();

    // Fire meta-write-triggering hooks NOW (sync), so the next event-loop
    // yield happens with the writes already queued in mutateRecord's
    // per-session enqueueMetaWrite. agentChangeHandlers must run before
    // onCompactionSwapHook so meta.json's upstreamSessionId is updated
    // before the breadcrumb is written (the breadcrumb references the
    // previous id, not the current).
    this.notifyAgentChange("swapUpstream");
    // Persist the moved watermark. Not gated on crossAgent: a cross-agent
    // swap advances it too, and recall's gates read the record either way.
    if (opts.summarizedThroughEntry !== undefined && this.persistWatermarkHook) {
      try {
        this.persistWatermarkHook(opts.summarizedThroughEntry);
      } catch (err) {
        this.logger?.warn(
          `swapUpstream: persistWatermarkHook failed: ${(err as Error).message}`,
        );
      }
    }
    // Cross-agent swaps skip the rollback breadcrumb: rollbackToUpstream
    // resumes the prior upstream on this.agentId, which after a cross-
    // agent swap is the NEW agent — incompatible with a session created
    // by the old one. Compaction rollback only supports same-agent.
    if (!crossAgent && this.onCompactionSwapHook) {
      try {
        this.onCompactionSwapHook({
          previousUpstreamSessionId,
          ...(previousSummarizedThroughEntry !== undefined
            ? { previousSummarizedThroughEntry }
            : {}),
        });
      } catch (err) {
        this.logger?.warn(`swapUpstream: onCompactionSwapHook failed: ${(err as Error).message}`);
      }
    }

    await oldAgent.kill().catch(() => undefined);

    // Post-swap observation hook. Fires after the new agent is fully
    // installed and the old one is dead.
    this.notifyChain("agent.swap", {
      phase: "post",
      previousUpstreamSessionId,
      upstreamSessionId: this.upstreamSessionId,
      agentId: this.agentId,
    });

    // Signal to attached clients that the compaction swap completed.
    // Skipped on cross-agent swaps: /hydra agent surfaces completion via
    // broadcastAgentSwitch (session_info_update with the new agentId)
    // rather than the compaction wire channel.
    if (!crossAgent) {
      this.broadcastCompactionPhase({
        phase: "swapped",
        ...(this.title !== undefined ? { title: this.title } : {}),
        summarizedThroughEntry: opts.summarizedThroughEntry ?? this._summarizedThroughEntry ?? 0,
      });
    }

    // For cross-agent swaps, surface the agent-identity change to clients
    // so the TUI relabels and any agent-id-aware UI updates immediately
    // (mirrors the pre-existing inline /hydra agent path).
    if (crossAgent) {
      this.broadcastAgentSwitch(oldAgentId, targetAgentId);
    }

    // Surface a synthetic agent_message_chunk so the user sees a clean
    // "Compaction completed." in the conversation stream instead of the
    // agent's seed-prompt acknowledgement (which we just suppressed via
    // internalPromptCapture above).
    //
    // Broadcast-only — NOT recorded to history.jsonl. Recording would
    // grow history by 1 entry, which the synopsis-coordinator catch-up
    // loop interprets as "new user conversation arrived during
    // compaction" and would trigger a second swap, overwriting the
    // rollback breadcrumb we just wrote. The TUI / attached clients
    // receive this notification live; fresh attachers see compaction
    // completion via the hydra_compaction phase:"swapped" event
    // already broadcast above plus the cleared compactionState in
    // meta.json.
    // Name the swap by its CAUSE, not by the machinery it borrowed.
    //
    // Every mid-life agent replacement runs through this function, so
    // "Compaction completed." used to be shown for a workspace move as
    // well — which is wrong twice over: nothing was summarized away, and
    // it invites the user to worry about lost context at exactly the
    // moment they are trying to confirm a clean workspace transition.
    //
    // Workspace moves say nothing here at all. The swap is a step inside
    // `workspace start` / `stop`, not the outcome of one, and it is the
    // caller that knows the outcome — which branch merged, where the
    // work went, whether the directory survived. Announcing the step too
    // meant three lines for one action, two of them saying "returned".
    // Progress is already covered: the workspace phases drive a live
    // indicator ("moving session into workspace...", "returning to
    // source tree..."), so silence here is not silence on screen.
    //
    // It was also premature. This fires as soon as the new agent is up,
    // which is before startWorkspace has written the cwd/binding record
    // — so it claimed a move that nothing on disk yet justified.
    const completedText =
      opts.reason === "workspace-enter" || opts.reason === "workspace-leave"
        ? undefined
        : crossAgent
          ? `\nSwitched to ${targetAgentId}.\n`
          : "\nCompaction completed.\n";
    if (completedText !== undefined) {
      const completedParams = this.rewriteForClient({
        sessionId: this.upstreamSessionId,
        update: {
          sessionUpdate: "agent_message_chunk",
          content: { type: "text", text: completedText },
          _meta: { "hydra-acp": { synthetic: true } },
        },
      });
      for (const client of this.clients.values()) {
        void client.connection.notify("session/update", completedParams).catch(() => undefined);
      }
    }

    // agentChangeHandlers + onCompactionSwapHook moved above to fire
    // before the await on oldAgent.kill — see the comment up there.

    this.updatedAt = Date.now();
  }

  // Roll back the most recent compaction swap. Spawns a fresh agent
  // process and resumes the previous upstream session via session/load,
  // then atomically swaps it in, kills the post-compaction agent, clears
  // the current synopsis, and broadcasts phase: "rolled_back".
  //
  // Guards (all checked before any side effects):
  //   - loadExistingAgentSession must be configured
  //   - session must be quiesced
  async rollbackToUpstream(opts: {
    previousUpstreamSessionId: string;
    previousSummarizedThroughEntry?: number;
  }): Promise<void> {
    const quiesced = await this.isQuiescedForSwap();
    if (!quiesced) {
      throw new Error(
        "session is not quiesced for rollback — wait for in-flight work to complete",
      );
    }

    const loadAgent = this.loadExistingAgentSession;
    if (!loadAgent) {
      throw new Error("loadExistingAgentSession not configured for this session");
    }

    const agentId = this.agentId;
    const cwd = this.cwd;
    const agentArgs = this.agentArgs;
    const forwardedEnv = this.forwardedEnv;
    const persistedModel = this.currentModel;
    const persistedMode = this.currentMode;

    const fresh = await loadAgent(opts.previousUpstreamSessionId, {
      agentId,
      cwd,
      agentArgs,
      ...(forwardedEnv ? { forwardedEnv } : {}),
      mcpServers: this.mcpServersConfig ?? [],
    });

    // Bank without arming the ledger probe. Rollback reloads an EARLIER
    // upstream session, not the one whose costAmount we just banked, so the
    // probe would be comparing against the wrong quantity — and a low first
    // report would bank the same amount a second time. See the rollback note
    // in PROTOCOL.md "Cost ledger scope".
    this.accumulateAndResetCost();
    this.wireAgent(fresh.agent);

    await restoreCurrentModel({
      agent: fresh.agent,
      upstreamSessionId: fresh.upstreamSessionId,
      persistedModel,
      agentReportedModel: fresh.initialModel,
      logger: this.logger,
    });
    await restoreCurrentMode({
      agent: fresh.agent,
      upstreamSessionId: fresh.upstreamSessionId,
      persistedMode,
      agentReportedMode: fresh.initialMode,
      logger: this.logger,
    });

    fresh.agent.connection.drainBuffered("session/update");

    const oldAgent = this.agent;
    this.agent = fresh.agent;
    this.upstreamSessionId = fresh.upstreamSessionId;
    this.agentMeta = fresh.agentMeta;
    this.agentCapabilities = fresh.agentCapabilities;
    this.resetModelVerb(fresh.modelVerb);

    this.broadcastMergedCommands();
    this.broadcastConfigOptions();

    await oldAgent.kill().catch(() => undefined);

    // Restore the pre-compaction summarizedThroughEntry watermark.
    this._summarizedThroughEntry = opts.previousSummarizedThroughEntry;

    this.broadcastCompactionPhase({
      phase: "rolled_back",
      summarizedThroughEntry: opts.previousSummarizedThroughEntry ?? 0,
    });

    // Notify agent change handlers so SessionManager's persistAgentChange
    // fires and persists the restored upstreamSessionId to meta.json.
    this.notifyAgentChange("rollbackToUpstream");

    this.updatedAt = Date.now();
  }

  // Scan the recent tail of history.jsonl for an open tool-call chain:
  // a tool_call entry without a corresponding tool_call_update that has
  // status="completed" or status="failed". Scans at most `maxEntries`
  // entries from the end of the file to bound I/O cost.
  private async _hasOpenToolCall(maxEntries = QUIESCE_TAIL_SCAN_ENTRIES): Promise<boolean> {
    if (!this.historyStore) {
      return false;
    }
    const history = await this.historyStore.load(this.sessionId);
    const tail = history.length > maxEntries
      ? history.slice(-maxEntries)
      : history;

    // Track toolCallIds seen in tool_call (pending) and tool_call_update
    // with terminal status (resolved).
    const pending = new Set<string>();
    const resolved = new Set<string>();

    for (const entry of tail) {
      const params = entry.params as { update?: { sessionUpdate?: string; toolCallId?: unknown; status?: string } } | undefined;
      const update = params?.update;
      if (!update || typeof update.sessionUpdate !== "string") {
        continue;
      }
      const kind = update.sessionUpdate;
      const toolCallId = typeof update.toolCallId === "string" ? update.toolCallId : undefined;
      if (!toolCallId) {
        continue;
      }
      if (kind === "tool_call") {
        pending.add(toolCallId);
      } else if (kind === "tool_call_update") {
        const status = update.status as string | undefined;
        if (status === "completed" || status === "failed") {
          resolved.add(toolCallId);
        }
      }
    }

    // Any pending tool_call that hasn't been resolved is open.
    for (const id of pending) {
      if (!resolved.has(id)) {
        return true;
      }
    }
    return false;
  }

  // Read the persisted history from disk. Returns [] if no history
  // file exists (fresh session, never prompted). Used by attach() and
  // the HTTP /history endpoint.
  async getHistorySnapshot(
    tools: "inline" | "references" = "inline",
  ): Promise<CachedNotification[]> {
    if (!this.historyStore) {
      return [];
    }
    return this.historyStore.load(this.sessionId, { tools }).catch(() => []);
  }

  // Newest-first async iterator over the recall view (archives + live).
  // Streams each file through zlib (for .gz) → readline, so peak RAM is
  // one archive's parsed entries at a time. Consumers that early-exit
  // (break out of the loop) pay only for the archives they open —
  // matching in the live tail costs zero archive I/O. Yielded entries
  // carry the stable global entryId in the archives-first concatenated
  // view; the same id can be passed to sliceRecallHistory() to fetch
  // an exact range verbatim.
  async *iterRecallNewestFirst(): AsyncGenerator<{
    entryId: number;
    entry: CachedNotification;
  }> {
    if (!this.historyStore) {
      return;
    }
    yield* this.historyStore.iterRecallNewestFirst(this.sessionId);
  }

  // Return the total number of entries in the recall view (archives +
  // live). Used by recall tools to report "we hit the limit but there
  // are more" style truncation flags without walking everything.
  async getRecallTotalCount(): Promise<number> {
    if (!this.historyStore) {
      return 0;
    }
    return this.historyStore.getRecallTotalCount(this.sessionId).catch(() => 0);
  }

  // Fetch a contiguous [from, to] slice of the recall view without
  // materializing the whole thing. Uses the archive line-count cache to
  // open only the archive(s) that actually contain the requested range,
  // so range() calls near the live tail don't touch deep archives.
  async sliceRecallHistory(
    fromEntryId: number,
    toEntryId: number,
  ): Promise<CachedNotification[]> {
    if (!this.historyStore) {
      return [];
    }
    const slice = await this.historyStore
      .rangeSlice(this.sessionId, fromEntryId, toEntryId)
      .catch(() => []);
    return slice.map((r) => r.entry);
  }

  // Subscribe to recordable broadcast entries — fires once per entry
  // that lands in history (so snapshot-shaped session_info/model/mode/
  // available_commands updates do NOT trigger this; they're broadcast
  // live but not recorded). Returns an unsubscribe function the caller
  // must invoke when done.
  onBroadcast(handler: (entry: CachedNotification) => void): () => void {
    this.broadcastHandlers.push(handler);
    return () => {
      const i = this.broadcastHandlers.indexOf(handler);
      if (i >= 0) {
        this.broadcastHandlers.splice(i, 1);
      }
    };
  }

  // Push an ephemeral session/update notification to attached clients
  // without recording it in history or feeding it to the broadcast handlers
  // that drive the transformer chain. Used for transient UI signals (e.g.
  // the clarifier announcing a new question) where the daemon owns the
  // wire fan-out but the event itself isn't part of session history.
  broadcastClientUpdate(update: Record<string, unknown>): void {
    const params = this.rewriteForClient({
      sessionId: this.upstreamSessionId,
      update,
    });
    for (const client of this.clients.values()) {
      void client.connection
        .notify("session/update", params)
        .catch(() => undefined);
    }
  }

  // Broadcast a hydra_compaction phase event to attached clients.
  // Send a hydra_compaction lifecycle event to attached clients.
  // These are ephemeral push notifications — they are NOT appended to
  // history.jsonl so they don't cause the catch-up loop to re-iterate.
  broadcastCompactionPhase(update: Record<string, unknown>): void {
    const phase = update.phase;
    if (phase === "swapped" || phase === "failed" || phase === "rolled_back") {
      this._liveCompactionPhase = undefined;
    } else {
      this._liveCompactionPhase = update;
    }
    const params = this.rewriteForClient({
      sessionId: this.upstreamSessionId,
      update: { sessionUpdate: "hydra_compaction", ...update },
    });
    for (const handler of this.broadcastHandlers) {
      try {
        handler({ method: "session/update", params, recordedAt: Date.now() });
      } catch {
        void 0;
      }
    }
    for (const client of this.clients.values()) {
      void client.connection.notify("session/update", params).catch(() => undefined);
    }
    // Mirror to transformers as a typed lifecycle event so hooks don't
    // have to filter session/update for the hydra_compaction subtype.
    // Notification-only — observation hook. Cancellable compact:pre is
    // deferred to a future stage (requires a request-shaped dispatch
    // wired into SessionManager.dispatchSynthesisSwap).
    this.notifyChain("compaction", { ...update });
  }

  /**
   * Send a hydra_workspace lifecycle event to attached clients.
   *
   * Two jobs, which is why it is one event rather than two. Progress:
   * entering a workspace provisions a checkout, runs setup hooks that
   * may install dependencies, and then respawns the agent, so the
   * command can sit for a minute with the composer looking idle — which
   * is exactly when someone presses Enter again.
   *
   * And relocation: a client resolves the session's cwd once, at
   * session/new or attach, and has no other way to learn it changed.
   * That cwd is not decoration — it is what file completion, the git
   * panel and diff resolution are all computed against, so a client
   * that misses this event keeps aiming at the tree the session just
   * left. The terminal phases therefore carry the new cwd and binding.
   *
   * Ephemeral, like the compaction phases: NOT written to history.
   */
  broadcastWorkspacePhase(update: Record<string, unknown>): void {
    const params = this.rewriteForClient({
      sessionId: this.upstreamSessionId,
      update: { sessionUpdate: "hydra_workspace", ...update },
    });
    for (const handler of this.broadcastHandlers) {
      try {
        handler({ method: "session/update", params, recordedAt: Date.now() });
      } catch {
        void 0;
      }
    }
    for (const client of this.clients.values()) {
      void client.connection.notify("session/update", params).catch(() => undefined);
    }
    this.notifyChain("workspace", { ...update });
  }

  /**
   * Show a line in the conversation stream that no agent produced.
   *
   * Broadcast-only and never recorded, matching the swap notices above
   * it: history is the agent's transcript, and a status line from the
   * daemon is not part of it.
   *
   * Exists because a command's result text is only rendered once its
   * turn ends, while the swap notices stream the instant they happen. A
   * multi-step command that reports solely through its return value
   * therefore prints its LAST step first. This lets such a command
   * report a step at the moment it completes instead.
   */
  broadcastSyntheticText(text: string): void {
    const params = this.rewriteForClient({
      sessionId: this.upstreamSessionId,
      update: {
        sessionUpdate: "agent_message_chunk",
        content: { type: "text", text },
        _meta: { "hydra-acp": { synthetic: true } },
      },
    });
    for (const client of this.clients.values()) {
      void client.connection.notify("session/update", params).catch(() => undefined);
    }
  }

  // Register a client and (asynchronously) load the replay slice it
  // should receive. Returns both the slice to replay and the actual
  // historyPolicy applied (which may differ from the requested one
  // when after_message falls back to full). Validation errors throw
  // synchronously so callers can rely on either the registration being
  // in effect or having thrown; the disk-load is the only async work.
  attach(
    client: AttachedClient,
    historyPolicy: HistoryPolicy,
    opts: {
      afterMessageId?: string;
      raw?: boolean;
      toolContent?: "inline" | "references";
    } = {},
  ): Promise<{ entries: CachedNotification[]; appliedPolicy: HistoryPolicy }> {
    if (this.closed) {
      throw withCode(
        new Error("session is closed"),
        JsonRpcErrorCodes.SessionNotFound,
      );
    }
    if (this.clients.has(client.clientId)) {
      throw withCode(
        new Error(`client ${client.clientId} is already attached`),
        JsonRpcErrorCodes.AlreadyAttached,
      );
    }
    this.clients.set(client.clientId, client);
    this.updatedAt = Date.now();
    // "none" is a true opt-out — caller wants zero notifications.
    if (historyPolicy === "none") {
      return Promise.resolve({ entries: [], appliedPolicy: historyPolicy });
    }
    // "pending_only" gets snapshot state but no conversation history.
    // Callers using this policy (notably session/load — agent-shell's
    // resume path) already have their own conversation history but
    // still need current model/mode/usage/commands/title to render
    // correctly, since those are filtered from on-disk history.
    if (historyPolicy === "pending_only") {
      return Promise.resolve({
        entries: this.buildStateSnapshotReplay(),
        appliedPolicy: historyPolicy,
      });
    }
    return this.loadReplay(historyPolicy, opts);
  }

  private async loadReplay(
    historyPolicy: HistoryPolicy,
    opts: {
      afterMessageId?: string;
      raw?: boolean;
      toolContent?: "inline" | "references";
    },
  ): Promise<{ entries: CachedNotification[]; appliedPolicy: HistoryPolicy }> {
    // Search the raw snapshot, coalesce the slice. Coalescing first would
    // drop the messageIds of every non-leading chunk in a run (and every
    // non-trailing tool_call_update / non-final plan), so a TUI whose
    // lastSeenMessageId pointed at one of those would never find a cutoff
    // and we'd fall back to "full".
    //
    // opts.raw bypasses coalescing entirely so every original chunk is
    // replayed individually — used by the drip-replay debug path so the
    // streaming render can be reproduced at its real granularity. The
    // synthetic state snapshot is never coalesced, so it's emitted as-is
    // either way.
    const maybeCoalesce = (entries: CachedNotification[]): CachedNotification[] =>
      opts.raw ? entries : coalesceReplay(entries);
    const raw = await this.getHistorySnapshot(opts.toolContent ?? "inline");
    // Filter out state-update entries from historical data so a fresh-attaching
    // client sees only the synthesized snapshot (buildStateSnapshotReplay) for
    // canonical-state kinds like usage_update. Replaying historical usage_update
    // would cause UX flicker: cost totals rewind backward then climb back to the
    // current value — see buildStateSnapshotReplay at session.ts:1482 which
    // already emits one usage_update carrying the current cumulative total.
    // State-update messageIds are never used as after_message cutoffs (cutoffs
    // target turn_complete / prompt_received entries), so searching in the
    // filtered array for cutoff lookup is safe.
    // usage_update is dropped from raw replay because buildStateSnapshotReplay
    // already synthesizes the latest snapshot; raw replay would cause cost rewind.
    const replayable = raw.filter((e) => !isStateUpdate(e.method, e.params));
    const state = this.buildStateSnapshotReplay();
    if (historyPolicy === "after_message") {
      const cutoff = opts.afterMessageId
        ? findMessageIdIndex(replayable, opts.afterMessageId)
        : -1;
      if (cutoff < 0) {
        return {
          entries: [...state, ...maybeCoalesce(replayable)],
          appliedPolicy: "full",
        };
      }
      return {
        entries: [...state, ...maybeCoalesce(replayable.slice(cutoff + 1))],
        appliedPolicy: "after_message",
      };
    }
    return {
      entries: [...state, ...maybeCoalesce(replayable)],
      appliedPolicy: "full",
    };
  }

  // Synthesizes one session/update notification per cached STATE_UPDATE_KIND
  // so an attaching client receives the current snapshot through the
  // standard ACP event channel. Without this, third-party clients would
  // never see current_model/mode/usage/info/commands on resume — they're
  // filtered out of recorded history (canonical state lives in meta.json
  // and is *also* surfaced via the attach response _meta, but third-party
  // clients can't read hydra's namespaced meta).
  private buildStateSnapshotReplay(): CachedNotification[] {
    const out: CachedNotification[] = [];
    const sessionId = this.sessionId;
    const recordedAt = Date.now();
    if (this.title !== undefined && this.title.length > 0) {
      out.push({
        method: "session/update",
        params: {
          sessionId,
          update: {
            sessionUpdate: "session_info_update",
            title: this.title,
          },
        },
        recordedAt,
      });
    }
    if (
      (this.currentModel !== undefined && this.currentModel.length > 0) ||
      this.agentAdvertisedModels.length > 0
    ) {
      const update: Record<string, unknown> = {
        sessionUpdate: "current_model_update",
      };
      if (this.currentModel !== undefined && this.currentModel.length > 0) {
        update.currentModel = this.currentModel;
      }
      if (this.agentAdvertisedModels.length > 0) {
        update.availableModels = [...this.agentAdvertisedModels];
      }
      out.push({
        method: "session/update",
        params: { sessionId, update },
        recordedAt,
      });
    }
    if (this.currentMode !== undefined && this.currentMode.length > 0) {
      out.push({
        method: "session/update",
        params: {
          sessionId,
          update: {
            sessionUpdate: "current_mode_update",
            currentModeId: this.currentMode,
          },
        },
        recordedAt,
      });
    }
    const cmds = this.mergedAvailableCommands();
    if (cmds.length > 0) {
      out.push({
        method: "session/update",
        params: {
          sessionId,
          update: {
            sessionUpdate: "available_commands_update",
            availableCommands: cmds,
          },
        },
        recordedAt,
      });
    }
    if (this.agentAdvertisedModes.length > 0) {
      out.push({
        method: "session/update",
        params: {
          sessionId,
          update: {
            sessionUpdate: "available_modes_update",
            availableModes: [...this.agentAdvertisedModes],
          },
        },
        recordedAt,
      });
    }
    if (this.currentUsage !== undefined) {
      const u = this.currentUsage;
      const update: Record<string, unknown> = {
        sessionUpdate: "usage_update",
      };
      if (typeof u.used === "number") {
        update.used = u.used;
      }
      if (typeof u.size === "number") {
        update.size = u.size;
      }
      if (
        typeof u.costAmount === "number" ||
        typeof u.costCurrency === "string"
      ) {
        const cost: Record<string, unknown> = {};
        if (typeof u.costAmount === "number") {
          cost.amount = u.costAmount;
        }
        if (typeof u.costCurrency === "string") {
          cost.currency = u.costCurrency;
        }
        update.cost = cost;
      }
      // Only emit when at least one payload field is present — an empty
      // snapshot has nothing useful to say.
      if (Object.keys(update).length > 1) {
        out.push({
          method: "session/update",
          params: { sessionId, update },
          recordedAt,
        });
      }
    }
    if (this._liveCompactionPhase !== undefined) {
      out.push({
        method: "session/update",
        params: {
          sessionId,
          update: {
            sessionUpdate: "hydra_compaction",
            ...this._liveCompactionPhase,
          },
        },
        recordedAt,
      });
    }
    return out;
  }

  // Dispatch in-flight permission requests to a freshly-attached
  // client. Called by the daemon's WS handler *after* it finishes
  // replaying history, so the prompt lands at the bottom of the
  // transcript rather than above the conversation.
  replayPendingPermissions(client: AttachedClient): void {
    for (const flag of this.attentionFlags.values()) {
      if (flag.source !== "daemon" || !flag.reason.startsWith("permission:")) {
        continue;
      }
      const requestId = flag.reason.slice("permission:".length);
      const cb = this.permissionCallbacks.get(requestId);
      if (cb) {
        cb(client);
      }
    }
  }

  detach(clientId: string): void {
    const leaving = this.clients.get(clientId);
    if (!leaving) {
      return;
    }
    this.clients.delete(clientId);
    this.updatedAt = Date.now();
    this.broadcastClientDisconnected(leaving);
  }

  // Notify remaining attached clients that a peer just left, per
  // RFD #533. Fires for both explicit session/detach and ws-close
  // teardown (acp-ws calls Session.detach() in both paths). The
  // notification is broadcast (not recorded) — peer presence is
  // transient, not part of conversation history.
  private broadcastClientDisconnected(client: AttachedClient): void {
    const info: { clientId: string; name?: string; version?: string } = {
      clientId: client.clientId,
    };
    if (client.clientInfo?.name) {
      info.name = client.clientInfo.name;
    }
    if (client.clientInfo?.version) {
      info.version = client.clientInfo.version;
    }
    const update = {
      sessionUpdate: "client_disconnected",
      client: info,
      timestamp: new Date().toISOString(),
    };
    for (const peer of this.clients.values()) {
      void peer.connection
        .notify("session/update", {
          sessionId: this.sessionId,
          update,
        })
        .catch(() => undefined);
    }
  }

  // `sentBy` is per-prompt provenance the caller has already validated
  // (see daemon/sent-by.ts). It rides on the queue entry's originator so
  // it reaches prompt_queue_added, prompt_received, and the persisted
  // queue alike, rather than being re-derived at each broadcast.
  /**
   * Prepare an isolated session's prompt before it reaches the agent.
   *
   * Two jobs, both only for workspace-isolated sessions:
   *
   *   - rewrite absolute source-tree paths to their workspace
   *     equivalents, so "look at ~/dev/proj/foo.cpp" resolves to the file
   *     the agent should actually touch
   *   - prepend the orientation preamble on the FIRST prompt, and again
   *     on any prompt that named the source tree
   *
   * The re-assertion is the part that earns its keep. ACP has no
   * system-prompt field, so the preamble rides the prompt and is exactly
   * the sort of one-time note compaction discards; without it an agent
   * two hundred turns deep has no memory of the mapping. Re-asserting
   * when a prompt mentions the source tree targets the moment it
   * matters instead of paying on every turn.
   *
   * Rewriting on the way OUT (rather than mutating the stored prompt)
   * keeps the user's transcript showing the words they typed.
   */
  /**
   * Report a write that landed in the source tree instead of the
   * workspace.
   *
   * Detection, not prevention: the daemon learns about the agent's file
   * I/O from tool-call notifications, which arrive AFTER the write. By
   * the time this runs the user's checkout has already been modified.
   *
   * It is still worth doing, because the alternative is a silent breach.
   * The whole promise of an isolated session is that the user's tree is
   * untouched, so the one outcome we must never produce is that promise
   * being broken and nobody finding out. Actual prevention has to come
   * from the agent's own permission layer, which is per-agent and cannot
   * be assumed.
   *
   * Edge-triggered for free: the caller has already deduplicated by path
   * via filesEditedSeen, so a repeatedly-edited file reports once.
   */
  private reportIsolationBreach(editedPath: string, toolCallId: unknown): void {
    const ws = this.workspace;
    if (ws === undefined) {
      // The inverse case: writing into a workspace this session has LEFT.
      // After `detach` that directory is still there and still writable,
      // so the write succeeds, looks fine, and can never reach the source
      // tree. Silent wasted work is worth as much noise as a breach.
      const former = this.formerWorkspace;
      if (former !== undefined && editedPath.startsWith(`${former.path}/`)) {
        this.logger?.warn?.(
          `STALE WORKSPACE WRITE on session ${this.sessionId}: the agent wrote ${editedPath}, ` +
            `which is inside the workspace this session already left. That work will not reach ` +
            `${former.sourceCwd}.`,
        );
        this.notifyChain("workspace.staleWrite", {
          path: editedPath,
          formerWorkspacePath: former.path,
          sourceCwd: former.sourceCwd,
          toolCallId,
        });
      }
      return;
    }
    if (!isSourceTreeBreach(editedPath, ws.sourceCwd, ws.path)) {
      return;
    }
    this.logger?.warn?.(
      `ISOLATION BREACH on session ${this.sessionId}: the agent wrote ${editedPath}, ` +
        `which is in the source tree ${ws.sourceCwd}, not its workspace ${ws.path}. ` +
        `The user's checkout has been modified.`,
    );
    this.notifyChain("workspace.breach", {
      path: editedPath,
      sourceCwd: ws.sourceCwd,
      workspacePath: ws.path,
      toolCallId,
    });
  }

  /**
   * The post-departure half: this session used to be isolated and isn't
   * any more.
   *
   * Two jobs, both about the agent's own memory rather than the user's
   * words. The transcript it inherited refers to files by workspace path,
   * so those paths get rewritten to the source tree, and a one-time note
   * says plainly that the workspace is no longer where its work belongs.
   *
   * Worth doing even though `stop` deletes the workspace: after `detach`
   * the directory is still there and still writable, so an agent that
   * keeps using it does work that looks successful and never lands. That
   * is the failure this exists to prevent, and it is silent, which is why
   * a note is not enough on its own — the rewrite is what actually
   * redirects the next action.
   */
  private applyDepartedPromptRewrite(prompt: unknown[]): unknown[] {
    const former = this.formerWorkspace;
    if (former === undefined) {
      return prompt;
    }
    let sawFormerMention = false;
    let out = mapPromptText(prompt, (text) => {
      if (!mentionsSourceTree(text, former.path)) {
        return text;
      }
      sawFormerMention = true;
      return rewriteSourcePaths(text, former.path, former.sourceCwd).text;
    });

    if (!this.departureNoteSent || sawFormerMention) {
      const note = buildDepartureNote({
        sourceCwd: former.sourceCwd,
        formerWorkspacePath: former.path,
        removed: former.removed,
      });
      out = prefixPromptText(out, `${note}\n\n`);
      this.departureNoteSent = true;
    }
    return out;
  }

  private applyWorkspacePromptRewrite(prompt: unknown[]): unknown[] {
    const ws = this.workspace;
    if (ws === undefined) {
      return this.applyDepartedPromptRewrite(prompt);
    }
    let sawSourceMention = false;
    let out = mapPromptText(prompt, (text) => {
      if (!mentionsSourceTree(text, ws.sourceCwd)) {
        return text;
      }
      sawSourceMention = true;
      return rewriteSourcePaths(text, ws.sourceCwd, ws.path).text;
    });

    const needsPreamble = !this.workspacePreambleSent || sawSourceMention;
    if (needsPreamble) {
      const preamble = buildWorkspacePreamble({
        workspacePath: ws.path,
        sourceCwd: ws.sourceCwd,
        notes: this.workspaceNotes,
        ...(this.workspacePreambleSent ? { reassert: true } : {}),
      });
      out = prefixPromptText(out, `${preamble}\n\n`);
      this.workspacePreambleSent = true;
    }
    return out;
  }

  async prompt(
    clientId: string,
    params: unknown,
    sentBy?: SentBy,
  ): Promise<unknown> {
    const client = this.clients.get(clientId);
    if (!client) {
      throw withCode(
        new Error("client not attached"),
        JsonRpcErrorCodes.SessionNotFound,
      );
    }
    // Reject prompts on a session that's mid-close. The window is short
    // now (just the agent.kill() await before markClosed sweeps the
    // queue), but during it the session is still in the live map and a
    // new turn would silently be discarded by drainQueue's closing-guard.
    // Surface a clear error code so the client can show the user the
    // session is going away.
    if (this.closing) {
      throw withCode(
        new Error("session is closing; new prompts cannot be accepted"),
        JsonRpcErrorCodes.SessionClosing,
      );
    }
    // Slash commands (`/hydra ...`, `/model`, `/mode`, `/sessions`,
    // `/help`) flow through the same enqueueUserPrompt path as
    // regular prompts. They surface as user-kind queue entries that
    // broadcast prompt_queue_added/removed and prompt_received,
    // anchor the TUI's "thinking" placeholder, and can be amended/
    // cancelled like any other prompt. runQueueEntry dispatches them
    // by inspecting the prompt text after broadcastPromptReceived
    // — so the conversation surface stays consistent regardless of
    // whether a prompt goes to the agent or a slash handler.
    // Mint the messageId once; it's the stable identifier for the
    // prompt across both prompt_queue_added (fires now, on accept) and
    // prompt_received (fires later, when the entry leaves the queue
    // head — see deviation note on broadcastPromptReceived).
    const messageId = generateMessageId();
    // Title heuristic runs first — it needs to see firstPromptSeeded=false
    // to actually fire. If it can extract a first line it'll set both the
    // title AND the flag. If it can't (image-only / attachment-only / no
    // extractable text), the title stays empty but we still need the flag
    // set so the close-time snapshot regen gate doesn't skip the session
    // as "had no prompt." Promotion to true is unconditional here.
    this.maybeSeedTitleFromPrompt(params);
    this._firstPromptSeeded = true;
    // Any non-ancillary prompt promotes the session to interactive,
    // regardless of prior state. Three cases this handles:
    //   - undefined → true: editor-spawned session sees its first real
    //                       prompt, flips into the default listing
    //   - false     → true: a transformer-spawned worker (created with
    //                       interactive:false) gets attached and the
    //                       user types something — they've taken
    //                       interest, the session becomes a real one
    //   - true      → true: no-op
    // Ancillary turns (`_meta["hydra-acp"].ancillary = true`, used by
    // `hydra cat` and transformer-driven worker prompts) deliberately
    // skip promotion so they don't accidentally lift a behind-the-scenes
    // session into the default UI.
    const ancillary =
      extractHydraMeta(
        ((params ?? {}) as { _meta?: Record<string, unknown> })._meta,
      ).ancillary === true;
    if (!ancillary && this._interactive !== true) {
      this._interactive = true;
      for (const handler of this.interactiveHandlers) {
        try {
          handler(true);
        } catch {
          // Persistence is best-effort; never break the prompt path.
        }
      }
    }
    return this.enqueueUserPrompt(client, params, messageId, sentBy);
  }

  // DEVIATION FROM RFD #533: this broadcast is deliberately deferred
  // until the prompt actually becomes the active turn (i.e. drainQueue
  // is about to forward it to the agent), NOT when hydra first accepts
  // the request. The literal RFD doesn't pin the timing — it just says
  // peers should learn about the turn — but it was authored before
  // prompt queueing existed, so accept-time and start-time were the
  // same moment. With hydra's per-session FIFO, deferring gives
  // prompt_received a single, useful meaning ("the agent is now taking
  // a turn on this prompt"), which is how attached clients (notably
  // agent-shell) consume it. The accept-time signal that peers can use
  // for queue chip rendering is hydra-acp/prompt_queue/added instead.
  private broadcastPromptReceived(entry: UserPromptQueueEntry): void {
    // A requested turn takes over from any unsolicited one still open, so
    // only one turn is ever live and promptStartedAt below isn't clobbering
    // a start time the unsolicited turn owns. Must run before this method
    // sets promptStartedAt.
    this.closeUnsolicitedTurn("superseded");
    const sentBy: Record<string, unknown> = { clientId: entry.originator.clientId };
    if (entry.originator.name) {
      sentBy.name = entry.originator.name;
    }
    if (entry.originator.version) {
      sentBy.version = entry.originator.version;
    }
    if (entry.originator.fromSession) {
      sentBy.fromSession = entry.originator.fromSession;
    }
    if (entry.originator.fromSessionTitle) {
      sentBy.fromSessionTitle = entry.originator.fromSessionTitle;
    }
    if (entry.originator.fromLabel) {
      sentBy.fromLabel = entry.originator.fromLabel;
    }
    if (entry.originator.depth !== undefined) {
      sentBy.depth = entry.originator.depth;
    }
    this.promptStartedAt = Date.now();
    this.recordAndBroadcast(
      "session/update",
      {
        sessionId: this.sessionId,
        update: {
          sessionUpdate: "prompt_received",
          messageId: entry.messageId,
          prompt: entry.prompt,
          sentBy,
        },
      },
      entry.clientId,
    );

    // Compat shim for clients that don't yet implement RFD #533's
    // prompt_received. The marker in _meta lets prompt_received-aware
    // clients short-circuit this duplicate.
    const text = extractPromptText(entry.prompt);
    if (text.length > 0) {
      this.recordAndBroadcast(
        "session/update",
        {
          sessionId: this.sessionId,
          update: {
            sessionUpdate: "user_message_chunk",
            content: { type: "text", text },
            _meta: { "hydra-acp": { compatFor: "prompt_received" } },
          },
        },
        entry.clientId,
      );
    }
  }

  // Persist a usage_update snapshot to history.jsonl at turn boundaries.
  //
  // usage_update is filtered from `recordAndBroadcast` by STATE_UPDATE_KINDS
  // (session.ts:5502) — those kinds are "live wire only" and never recorded
  // to on-disk history, because their canonical state lives in meta.json.
  // However, analytics consumers need a per-turn time series, so we record
  // directly to historyStore here (bypassing recordAndBroadcast entirely).
  //
  // The recorded cost.amount is the cross-life cumulative total (via the
  // currentUsage getter at session.ts:582-590), matching the value that
  // used to flow over the wire pre-May-13. Analytics consumers diff
  // successive rows to get per-turn deltas.
  //
  // See also: GET /v1/sessions/:id/events — the HTTP endpoint that exposes
  // these persisted lines to external consumers.
  private recordCurrentUsageSnapshot(): void {
    if (this.historyStore === undefined) {
      return;
    }

    const usage = this.currentUsage;
    if (usage === undefined) {
      return;
    }

    const update: Record<string, unknown> = {
      sessionUpdate: "usage_update",
    };
    if (typeof usage.used === "number") {
      update.used = usage.used;
    }
    if (typeof usage.size === "number") {
      update.size = usage.size;
    }
    if (
      typeof usage.costAmount === "number" ||
      typeof usage.costCurrency === "string"
    ) {
      const cost: Record<string, unknown> = {};
      if (typeof usage.costAmount === "number") {
        cost.amount = usage.costAmount;
      }
      if (typeof usage.costCurrency === "string") {
        cost.currency = usage.costCurrency;
      }
      update.cost = cost;
    }

    // Only emit when at least one payload field is present — an empty
    // snapshot has nothing useful to say. Mirrors the guard at
    // buildStateSnapshotReplay (session.ts:1584).
    if (Object.keys(update).length <= 1) {
      return;
    }

    // Attribution: which agent, and which of ITS sessions, incurred this
    // cost. params.sessionId is the hydra id, so without this the row says
    // nothing about where the money actually went.
    //
    // This matters because a hydra session's upstream is not stable. It
    // rotates on compaction swap, /hydra agent switch, restart and rollback,
    // and meta.json only ever holds the CURRENT id — the previous ones are
    // overwritten and lost. A cost series spanning several upstream sessions
    // therefore becomes unattributable after the fact: reconciling it against
    // an agent's own ledger requires guessing which of its sessions were
    // involved (by cwd and time window), which is ambiguous whenever an agent
    // ran subagents or a second session in the same directory.
    //
    // agentId is included because it selects WHICH ledger to consult; a
    // session that switched from opencode to claude-acp has rows that must be
    // reconciled against different stores.
    //
    // Additive and hydra-namespaced, consistent with the existing
    // _meta["hydra-acp"].compatFor stamp. The events endpoint passes
    // params.update through verbatim, so consumers see it without a
    // version bump (see PROTOCOL.md "Stability guarantee").
    update._meta = {
      "hydra-acp": {
        upstreamSessionId: this.upstreamSessionId,
        agentId: this.agentId,
      },
    };

    const params = {
      sessionId: this.sessionId,
      update,
    };

    // .catch on the void: HistoryStore returns the raw task promise so
    // daemon shutdown can observe rejections via flushAll(), but
    // fire-and-forget callers must not surface unhandled rejections —
    // e.g. when a test's temp dir is torn down before the queued
    // mkdir runs (ENOENT). The store's internal `settled` chain still
    // logs/swallows for queue continuity; this catch is purely for the
    // local promise.
    void this.historyStore
      .append(this.sessionId, {
        method: "session/update",
        params,
        recordedAt: Date.now(),
      })
      .catch(() => undefined);
  }

  private broadcastTurnComplete(
    originatorClientId: string,
    response: unknown,
    promptMessageId?: string,
    wasAmend?: boolean,
  ): void {
    const stopReason =
      response &&
      typeof response === "object" &&
      "stopReason" in response &&
      typeof (response as { stopReason: unknown }).stopReason === "string"
        ? (response as { stopReason: string }).stopReason
        : undefined;
    const update: Record<string, unknown> = {
      sessionUpdate: "turn_complete",
      messageId: generateMessageId(),
    };
    if (stopReason !== undefined) {
      update.stopReason = stopReason;
    }
    // Attach the amend marker when this turn_complete closes an
    // amended turn, so renderer clients can paint the cancellation
    // as "amended" rather than the user-cancelled red banner without
    // waiting for the follow-up prompt_amended notification.
    const amend = this.amendInProgress;
    if (
      amend &&
      promptMessageId !== undefined &&
      amend.cancelledMessageId === promptMessageId
    ) {
      update._meta = {
        "hydra-acp": {
          amended: {
            cancelledMessageId: amend.cancelledMessageId,
            newMessageId: amend.newMessageId,
          },
        },
      };
    }
    this.promptStartedAt = undefined;
    // From here on, agent output with no prompt in flight means the agent
    // resumed a turn on its own. See noteAgentActivity.
    this.sawTurnComplete = true;
    // Snapshot the workspace at the turn boundary. A turn is the natural
    // unit: it is where the agent has stopped writing, so the tree is
    // momentarily coherent. Fire-and-forget by contract, because the
    // alternative is making every turn wait on a tree walk.
    this.scheduleWorkspaceSnapshotHook?.();
    if (promptMessageId !== undefined && stopReason !== undefined) {
      this.recordTerminal(promptMessageId, stopReason);
    }
    // For amend-originated entries (sent via hydra-acp/prompt/amend, not
    // session/prompt), the originator has no awaiting session/prompt
    // promise that would deliver the turn outcome — so include them in
    // the broadcast so their TUI can clear currentHeadMessageId and
    // adjust pendingTurns. For regular session/prompt entries, exclude
    // as before since the response itself carries the stopReason.
    this.recordCurrentUsageSnapshot();
    this.recordAndBroadcast(
      "session/update",
      {
        sessionId: this.sessionId,
        update,
      },
      wasAmend ? undefined : originatorClientId,
    );
    if (
      amend &&
      promptMessageId !== undefined &&
      amend.cancelledMessageId === promptMessageId
    ) {
      this.broadcastPromptAmended(amend);
    }
  }

  // Called for every agent→client session/update before it is broadcast.
  //
  // ACP models a turn as a request and a response: hydra sends
  // session/prompt, the response means the turn is over. Claude Code does
  // not honour that. When a background task it started (Monitor, Bash with
  // run_in_background) completes after the model already ended its turn,
  // the harness pokes itself with a synthetic <task-notification> message
  // and runs a *new* turn with nobody asking. There is no ACP message for
  // "I am starting a turn you did not request", so claude-acp sends none:
  // it just starts emitting content, and emits no turn_complete when that
  // turn ends either.
  //
  // The consequence is that a session reports itself idle while the agent
  // is working, so the next prompt gets dispatched on top of a running
  // agent and the two responses interleave. Detecting it needs no marker
  // from the agent: turn content arriving with no prompt in flight is
  // already a protocol violation, which makes the condition below sound —
  // a well-behaved agent can never trip it.
  //
  // Deliberately keyed on promptInFlight, not currentEntry.kind === "user",
  // so internal queue entries (title regen, agent swap, import seed) are
  // covered too. Prompts sent outside the queue are fenced by
  // internalPromptCapture and never reach this path, and session/load runs
  // before the Session exists, so neither can produce a false positive.
  private noteAgentActivity(envelope: unknown): void {
    if (this.closing || this.closed) {
      return;
    }
    // State-shaped updates (model, mode, usage, advertised commands) say
    // nothing about whether a turn is running — the agent emits them
    // outside turns routinely.
    if (isStateUpdate("session/update", envelope)) {
      return;
    }
    this.noteBackgroundTaskArming(envelope);
    this.lastAgentActivityAt = Date.now();
    if (this.unsolicitedTurn !== undefined) {
      // Still going: push the silence deadline out. Deliberately ahead of
      // the promptInFlight check: during a queue hold promptInFlight is
      // set while the unsolicited turn is still the thing producing this
      // output, and letting it lapse there would flip the session to idle
      // mid-work and release the hold early.
      this.armUnsolicitedTurnTimer();
      return;
    }
    if (this.promptInFlight || !this.sawTurnComplete) {
      return;
    }
    this.openUnsolicitedTurn();
  }

  // Harvest the background task an agent update announces, so an
  // unsolicited turn can tell clients what woke it. Two shapes, both
  // claude-acp `_meta` extensions rather than ACP: Monitor reports a
  // taskId on its tool_call_update, and Bash reports run_in_background
  // in its rawInput. Best-effort labelling only — a missing or stale
  // value costs nothing but a less specific header.
  private noteBackgroundTaskArming(envelope: unknown): void {
    const update = (envelope as { update?: Record<string, unknown> } | undefined)
      ?.update;
    if (!update || typeof update !== "object") {
      return;
    }
    const toolCallId = typeof update.toolCallId === "string"
      ? update.toolCallId
      : undefined;
    if (toolCallId === undefined) {
      return;
    }
    const rawInput = update.rawInput as Record<string, unknown> | undefined;
    const claudeMeta = extractClaudeCodeMeta(update._meta);
    this.rememberToolLabel(toolCallId, update, rawInput, claudeMeta);
    this.noteBackgroundTaskStopped(update, rawInput, claudeMeta);
    const taskId = typeof claudeMeta?.toolResponse?.taskId === "string"
      ? claudeMeta.toolResponse.taskId
      : extractBackgroundBashTaskId(update.rawOutput);
    const isBackground = taskId !== undefined ||
      (rawInput !== undefined && rawInput.run_in_background === true);
    if (!isBackground) {
      return;
    }
    const label = this.toolLabels.get(toolCallId)?.label ?? "background task";
    this.lastBackgroundTask = { toolCallId, label };
    // A background tool call arms once and then keeps reporting: the same
    // toolCallId arrives again on every tool_call_update. So preserve the
    // ORIGINAL armedAt across re-arms and move only the deadline.
    //
    // The two fields answer different questions. armedAt is when the job
    // started, which is what clients clock their "running Xs" readout
    // from (see armedSince). Overwriting it on every update reset that
    // clock, so a task that had been running for minutes read as though
    // it had just begun. expiresAt asks whether the job is still alive,
    // and an update is precisely the evidence that renews it.
    //
    // It also made the armed-tasks broadcast fire per update rather than
    // per change: the dedup key in onArmedTasksChanged includes
    // armedSince, so whether two updates coalesced came down to whether
    // they happened to land in the same millisecond.
    const now = Date.now();
    const existing = this.armedTasks.get(toolCallId);
    // A later update may be the one that carries the task id, and an
    // earlier one that had it must not be erased by a later one without.
    const knownTaskId = taskId ?? existing?.taskId;
    // Sticky, so no re-arm can demote a repeating watch to a one-shot and
    // hand the next resumption the right to clear it. Belt-and-braces
    // today: the sparse late update that carries neither title nor toolName
    // still carries toolResponse.taskId, which is what armed the entry in
    // the first place, so isRepeatingArming already answers true on its own.
    const repeating = isRepeatingArming(update.title, claudeMeta, rawInput) ||
      existing?.repeating === true;
    const ttlMs = armedTaskTtlMs(
      claudeMeta?.toolResponse?.timeoutMs,
      repeating,
    );
    this.armedTasks.set(toolCallId, {
      label,
      ...(knownTaskId !== undefined ? { taskId: knownTaskId } : {}),
      repeating,
      armedAt: existing?.armedAt ?? now,
      expiresAt: now + ttlMs,
    });
    this.onArmedTasksChanged();
  }

  // Background tasks currently armed: the agent finished its turn and
  // handed control back, but a watch it started is still pending, so the
  // session can restart itself without anyone prompting it.
  //
  // This is the third session state, distinct from both "working" and
  // "done": idle right now, but a wakeup is queued.
  get armedBackgroundTasks(): Array<{ label: string; taskId?: string }> {
    return [...this.armedTasks.values()].map((t) => ({
      label: t.label,
      ...(t.taskId !== undefined ? { taskId: t.taskId } : {}),
    }));
  }

  // When the longest-running armed task was armed, or undefined when none
  // are. Clients clock their "running Xs" readout from this: the useful
  // question is how long the job has been going, not how long the user has
  // been idle since the turn ended.
  get armedSince(): number | undefined {
    let oldest: number | undefined;
    for (const task of this.armedTasks.values()) {
      if (oldest === undefined || task.armedAt < oldest) {
        oldest = task.armedAt;
      }
    }
    return oldest;
  }

  // Called after any mutation of armedTasks. Re-arms the expiry timer and
  // tells attached clients, but only when the derived state they render
  // actually moved.
  //
  // Expiry is timer-driven rather than swept on read because the state is
  // now pushed, not polled: a session sitting idle for an hour has nobody
  // reading the getter, and "the job you were told about has expired" is
  // exactly the transition a user who walked away needs to see.
  private onArmedTasksChanged(): void {
    this.scheduleArmedExpiry();
    const count = this.armedTasks.size;
    const since = this.armedSince;
    if (count === this.lastArmedBroadcast?.count &&
      since === this.lastArmedBroadcast?.since) {
      return;
    }
    this.lastArmedBroadcast = { count, since };
    if (this.closed) {
      return;
    }
    this.broadcastQueueNotification("hydra-acp/session/armed_tasks_updated", {
      sessionId: this.sessionId,
      count,
      ...(since !== undefined ? { since } : {}),
      tasks: this.armedBackgroundTasks,
    });
  }

  private scheduleArmedExpiry(): void {
    if (this.armedExpiryTimer !== undefined) {
      clearTimeout(this.armedExpiryTimer);
      this.armedExpiryTimer = undefined;
    }
    let soonest: number | undefined;
    for (const task of this.armedTasks.values()) {
      if (soonest === undefined || task.expiresAt < soonest) {
        soonest = task.expiresAt;
      }
    }
    if (soonest === undefined || this.closed) {
      return;
    }
    this.armedExpiryTimer = setTimeout(
      () => {
        this.armedExpiryTimer = undefined;
        const now = Date.now();
        let dropped = false;
        for (const [id, task] of this.armedTasks) {
          if (task.expiresAt <= now) {
            this.armedTasks.delete(id);
            dropped = true;
          }
        }
        if (dropped) {
          this.onArmedTasksChanged();
        } else {
          this.scheduleArmedExpiry();
        }
      },
      Math.max(0, soonest - Date.now()),
    );
    if (typeof this.armedExpiryTimer.unref === "function") {
      this.armedExpiryTimer.unref();
    }
  }

  // The agent explicitly cancelled a background task, so stop counting it
  // toward the armed badge. TaskStop reports the id it killed as
  // rawInput.task_id, matching the taskId harvested at arming time.
  //
  // Only a partial answer to stale entries: an agent that kills the
  // underlying process some other way (observed: `pkill` from a plain
  // Bash) leaves the watch dead with no in-band signal at all, and the
  // entry survives until its TTL. There is no fix for that from outside
  // the agent, which is why the count is documented as best-effort.
  private noteBackgroundTaskStopped(
    update: Record<string, unknown>,
    rawInput: Record<string, unknown> | undefined,
    claudeMeta: { toolName?: unknown } | undefined,
  ): void {
    const isTaskStop = claudeMeta?.toolName === "TaskStop" ||
      update.title === "TaskStop";
    if (!isTaskStop) {
      return;
    }
    const stopped = rawInput?.task_id;
    if (typeof stopped !== "string" || stopped.length === 0) {
      return;
    }
    let dropped = false;
    for (const [id, task] of this.armedTasks) {
      if (task.taskId === stopped) {
        this.armedTasks.delete(id);
        dropped = true;
      }
    }
    if (dropped) {
      this.onArmedTasksChanged();
    }
  }

  // Remember the best human-readable label seen for a tool call, across
  // all of its updates.
  //
  // Not merely a convenience: a Monitor reports its taskId on a late,
  // sparse tool_call_update that carries neither `title` nor `rawInput`,
  // while the description ("validation harness completion") arrived on
  // earlier updates for the same toolCallId. Reading only the update that
  // carries the arming signal therefore yields the generic fallback, which
  // is what shipped and what a live resumption caught.
  //
  // A description always wins and always overwrites (later ones are more
  // current); a title only fills an empty slot, so it can't clobber a
  // description that arrived first.
  private rememberToolLabel(
    toolCallId: string,
    update: Record<string, unknown>,
    rawInput: Record<string, unknown> | undefined,
    claudeMeta: { toolName?: unknown } | undefined,
  ): void {
    const description = rawInput !== undefined &&
        typeof rawInput.description === "string" && rawInput.description
      ? rawInput.description
      : undefined;
    // Truncated because this is agent-authored text we re-broadcast as a
    // one-line header; a pathological description shouldn't ride along on
    // every client's turn marker.
    if (description !== undefined) {
      this.toolLabels.set(toolCallId, {
        label: description.slice(0, BACKGROUND_TASK_LABEL_MAX),
        fromDescription: true,
      });
    } else if (this.toolLabels.get(toolCallId)?.fromDescription !== true) {
      const fallback = typeof update.title === "string" && update.title
        ? update.title
        : typeof claudeMeta?.toolName === "string" && claudeMeta.toolName
        ? claudeMeta.toolName
        : undefined;
      if (fallback !== undefined) {
        this.toolLabels.set(toolCallId, {
          label: fallback.slice(0, BACKGROUND_TASK_LABEL_MAX),
          fromDescription: false,
        });
      }
    }
    while (this.toolLabels.size > TOOL_LABEL_LIMIT) {
      const oldest = this.toolLabels.keys().next().value;
      if (oldest === undefined) {
        break;
      }
      this.toolLabels.delete(oldest);
    }
  }

  // Open a synthetic turn for agent work nobody requested.
  //
  // promptStartedAt is what every "is this session busy" consumer reads
  // (turnStartedAt, the session list's BUSY column, isQuiescedSync), so
  // setting it here is the whole point — the wire event below is additive
  // detail for clients that want to label the resumption.
  //
  // turn_started / turn_ended are hydra-specific kinds carrying
  // _meta["hydra-acp"].unsolicited. We deliberately do NOT reuse
  // turn_complete: clients pair turn_complete against a prompt they saw
  // start, and handing them an unmatched one would corrupt their pending
  // turn accounting. An unknown sessionUpdate degrades to a no-op in
  // render-update's default branch, so unaware clients are unaffected.
  private openUnsolicitedTurn(): void {
    const startedAt = Date.now();
    const cause = this.lastBackgroundTask;
    // Clear every ONE-SHOT task armed since the last turn boundary, not just
    // the one we can name — but leave repeating watches alone.
    //
    // For a one-shot, notification delivery is batched and only happens at
    // turn boundaries, so a resumption is good evidence that everything
    // pending reported in. Clearing only the attributed one leaves the rest
    // stranded until their TTL, which is how sZNwrE44KnLbCN0u showed a false
    // BUSY for 28 minutes: a backgrounded vitest armed at 14:56:06 and a
    // Monitor watching for it armed at 14:57:27, the resumption was
    // attributed to the Monitor, and the vitest entry was already
    // unreachable because lastBackgroundTask only ever holds the most recent
    // arming.
    //
    // That reasoning does not extend to a Monitor, which fires once per
    // occurrence and keeps watching afterwards: its notification is evidence
    // that the watch is ALIVE, not that it is done. Clearing it on the first
    // firing is what made VHvFZxwYjpsF3scF report armedTasks: 0 with six
    // watches plainly running — each later firing found nothing armed, so
    // the badge never came back. A repeating entry leaves only via TaskStop
    // or its TTL, which each firing renews.
    //
    // `persistent` is not the discriminator: all six of those were
    // persistent: false and every one of them fired repeatedly. The tool
    // kind is (see isRepeatingArming).
    //
    // Still deliberately understates for one-shots: if two genuinely
    // independent jobs were running and only one finished, the badge goes
    // quiet early. That degrades to the behaviour before any of this
    // existed, whereas a stale entry actively claims a wakeup is coming.
    let discharged = false;
    for (const [id, task] of this.armedTasks) {
      if (task.repeating) {
        continue;
      }
      this.armedTasks.delete(id);
      discharged = true;
    }
    if (discharged) {
      this.onArmedTasksChanged();
    }
    this.unsolicitedTurn = {
      messageId: generateMessageId(),
      startedAt,
      timer: undefined,
      cause,
    };
    this.promptStartedAt = startedAt;
    this.logger?.info(
      `session ${this.sessionId} agent resumed with no prompt in flight` +
        (cause ? ` (after ${cause.label})` : ""),
    );
    const meta: Record<string, unknown> = { unsolicited: true };
    if (cause) {
      meta.cause = cause;
    }
    this.recordAndBroadcast("session/update", {
      sessionId: this.sessionId,
      update: {
        sessionUpdate: "turn_started",
        messageId: this.unsolicitedTurn.messageId,
        _meta: { "hydra-acp": meta },
      },
    });
    this.armUnsolicitedTurnTimer();
  }

  // Hold a user prompt at the head of the queue while the agent is mid-way
  // through a turn it started by itself. Without this the prompt is
  // dispatched onto a running agent: the agent queues it internally, its
  // answer interleaves with the work already in flight, and the
  // session/prompt response pairing can be lost entirely (observed: a
  // prompt that stayed open for 12 minutes after it had already been
  // answered).
  //
  // Called with the entry still IN promptQueue, deliberately, so a user
  // who gets bored can still cancel it, and so an amend can still reorder
  // around it. The caller re-reads the head after we return.
  //
  // Returns when the agent has been quiet for QUIET, or the turn closed, or
  // we hit CAP, or the entry/session went away. Never rejects: a hold that
  // goes wrong must not strand the queue.
  private async holdForUnsolicitedTurn(
    entry: UserPromptQueueEntry,
  ): Promise<void> {
    if (this.unsolicitedTurn === undefined) {
      return;
    }
    const holdStartedAt = Date.now();
    const cause = this.unsolicitedTurn.cause;
    this.broadcastQueueNotification("hydra-acp/prompt_queue/held", {
      sessionId: this.sessionId,
      messageId: entry.messageId,
      reason: "agent_resumed",
      ...(cause ? { cause } : {}),
      holdCapMs: UNSOLICITED_HOLD_CAP_MS,
    });
    let released: "quiet" | "cap" | "turn_ended" | "cancelled" | "closing" =
      "quiet";
    for (;;) {
      if (this.closing || this.closed) {
        released = "closing";
        break;
      }
      if (entry.cancelled) {
        released = "cancelled";
        break;
      }
      if (this.unsolicitedTurn === undefined) {
        released = "turn_ended";
        break;
      }
      const now = Date.now();
      const capLeft = UNSOLICITED_HOLD_CAP_MS - (now - holdStartedAt);
      if (capLeft <= 0) {
        released = "cap";
        break;
      }
      const quietLeft = UNSOLICITED_HOLD_QUIET_MS -
        (now - this.lastAgentActivityAt);
      if (quietLeft <= 0) {
        released = "quiet";
        break;
      }
      // Agent output arriving meanwhile pushes lastAgentActivityAt out and
      // the next pass recomputes from it, so the deadlines need no waking.
      // The poll bound is what lets a cancel or a closing turn be noticed
      // promptly instead of at the next deadline.
      const nap = Math.min(capLeft, quietLeft, UNSOLICITED_HOLD_POLL_MS);
      await new Promise<void>((resolve) => {
        const timer = setTimeout(resolve, nap);
        if (typeof timer.unref === "function") {
          timer.unref();
        }
      });
    }
    this.broadcastQueueNotification("hydra-acp/prompt_queue/released", {
      sessionId: this.sessionId,
      messageId: entry.messageId,
      reason: released,
      heldMs: Date.now() - holdStartedAt,
    });
    if (released === "cap") {
      this.logger?.warn(
        `session ${this.sessionId} dispatching a prompt into a still-running ` +
          `agent turn after ${UNSOLICITED_HOLD_CAP_MS}ms; responses may interleave`,
      );
    }
  }

  private armUnsolicitedTurnTimer(): void {
    const turn = this.unsolicitedTurn;
    if (turn === undefined) {
      return;
    }
    if (turn.timer !== undefined) {
      clearTimeout(turn.timer);
    }
    turn.timer = setTimeout(() => {
      this.closeUnsolicitedTurn("idle");
    }, UNSOLICITED_TURN_IDLE_MS);
    // Never hold the process open on a speculative deadline.
    if (typeof turn.timer.unref === "function") {
      turn.timer.unref();
    }
  }

  // Close an open unsolicited turn. Called on the silence deadline, when a
  // real prompt takes over, and from markClosed so history is never left
  // with a dangling turn_started.
  //
  // `reason` distinguishes the silence deadline (our guess that the agent
  // finished) from a takeover; clients that care can tell "we think it
  // stopped" from "something else started".
  private closeUnsolicitedTurn(reason: "idle" | "superseded" | "closed"): void {
    const turn = this.unsolicitedTurn;
    if (turn === undefined) {
      return;
    }
    if (turn.timer !== undefined) {
      clearTimeout(turn.timer);
    }
    this.unsolicitedTurn = undefined;
    this.promptStartedAt = undefined;
    // Analytics consumers diff successive usage_update rows for per-turn
    // cost. Without a row here an unsolicited turn's tokens silently fold
    // into whichever turn happens to close next.
    this.recordCurrentUsageSnapshot();
    if (this.closed) {
      return;
    }
    this.recordAndBroadcast("session/update", {
      sessionId: this.sessionId,
      update: {
        sessionUpdate: "turn_ended",
        messageId: generateMessageId(),
        startedMessageId: turn.messageId,
        durationMs: Date.now() - turn.startedAt,
        _meta: { "hydra-acp": { unsolicited: true, reason } },
      },
    });
  }

  // Record that a prompt's turn has ended, with its terminal stopReason.
  // Used by amendPrompt to resolve targetMessageIds that completed/cancelled
  // before the amend arrived. LRU-trimmed at RECENTLY_TERMINAL_LIMIT.
  private recordTerminal(messageId: string, stopReason: string): void {
    this.recentlyTerminal.set(messageId, {
      stopReason,
      terminatedAt: Date.now(),
    });
    while (this.recentlyTerminal.size > RECENTLY_TERMINAL_LIMIT) {
      const oldest = this.recentlyTerminal.keys().next().value;
      if (oldest === undefined) {
        break;
      }
      this.recentlyTerminal.delete(oldest);
    }
  }

  // Fire hydra-acp/prompt/amended for the M1→M2 linkage. The amendment's
  // current content is read live from the queue entry so any update_prompt
  // calls during the amend window are reflected. Best-effort: if M2 has
  // already been cancelled out of the queue by the time we get here, we
  // skip — the amendInProgress clearing in cancelQueuedPrompt should have
  // prevented this code path from running in that case.
  private broadcastPromptAmended(amend: {
    cancelledMessageId: string;
    newMessageId: string;
  }): void {
    const entry = this.findUserEntry(amend.newMessageId);
    if (!entry) {
      return;
    }
    const params: PromptAmendedParams = {
      sessionId: this.sessionId,
      cancelledMessageId: amend.cancelledMessageId,
      newMessageId: amend.newMessageId,
      prompt: entry.prompt,
      originator: entry.originator,
      amendedAt: Date.now(),
    };
    this.broadcastQueueNotification(
      "hydra-acp/prompt/amended",
      params as unknown as Record<string, unknown>,
    );
  }

  // Look up a user-prompt queue entry by messageId, searching both the
  // currentEntry slot and the waiting queue.
  private findUserEntry(
    messageId: string,
  ): UserPromptQueueEntry | undefined {
    if (
      this.currentEntry?.messageId === messageId &&
      this.currentEntry.kind === "user"
    ) {
      return this.currentEntry;
    }
    const queued = this.promptQueue.find(
      (e) => e.messageId === messageId && e.kind === "user",
    );
    return queued?.kind === "user" ? queued : undefined;
  }

  // Total visible-or-running entries: the in-flight head (if any) plus
  // the queue's user-visible waiting entries. Internal entries don't
  // count — they're an implementation detail and the wire never
  // surfaces them.
  private visibleQueueDepth(): number {
    let count =
      this.currentEntry?.kind === "user" && !this.currentEntry.cancelled
        ? 1
        : 0;
    for (const entry of this.promptQueue) {
      if (entry.kind === "user" && !entry.cancelled) count += 1;
    }
    return count;
  }

  private broadcastQueueAdded(
    entry: UserPromptQueueEntry,
    options?: { amending?: string; position?: number },
  ): void {
    const depth = this.visibleQueueDepth();
    // entry just landed at the tail of the queue. Its position equals
    // the count of user-visible entries already ahead of it = depth-1.
    // For amend-pending entries spliced at the head, the caller passes
    // an explicit position so the notification reflects the actual
    // queue order rather than the default tail-position derivation.
    const position =
      options?.position ?? Math.max(0, depth - 1);
    const params: Record<string, unknown> = {
      sessionId: this.sessionId,
      messageId: entry.messageId,
      originator: entry.originator,
      prompt: entry.prompt,
      position,
      queueDepth: depth,
      enqueuedAt: entry.enqueuedAt,
    };
    if (options?.amending !== undefined) {
      params._meta = {
        "hydra-acp": { amending: options.amending },
      };
    }
    this.broadcastQueueNotification("hydra-acp/prompt_queue/added", params);
  }

  private broadcastQueueUpdated(
    messageId: string,
    prompt: unknown[],
  ): void {
    this.broadcastQueueNotification("hydra-acp/prompt_queue/updated", {
      sessionId: this.sessionId,
      messageId,
      prompt,
    });
  }

  private broadcastQueueRemoved(
    messageId: string,
    reason: "started" | "cancelled" | "abandoned",
  ): void {
    this.broadcastQueueNotification("hydra-acp/prompt_queue/removed", {
      sessionId: this.sessionId,
      messageId,
      reason,
    });
  }

  // Fan-out for queue lifecycle notifications. Ephemeral by design —
  // these signals describe transient daemon state, not conversation
  // content, so we deliberately bypass recordAndBroadcast (no history,
  // no idle-timer arm, no rewrite-for-client since we already emit the
  // hydra sessionId).
  private broadcastQueueNotification(
    method: string,
    params: Record<string, unknown>,
  ): void {
    for (const client of this.clients.values()) {
      void client.connection.notify(method, params).catch(() => undefined);
    }
  }

  // Snapshot of user-visible queue state at this moment. Surfaced to
  // late-attaching clients via the session/attach response _meta so
  // they boot with the same chip list as their peers without waiting
  // for new prompt_queue_added notifications. Internal entries are
  // omitted (they're not surfaced on the wire at all).
  queueSnapshot(): PromptQueueSnapshotEntry[] {
    const out: PromptQueueSnapshotEntry[] = [];
    let position = 0;
    if (
      this.currentEntry?.kind === "user" &&
      !this.currentEntry.cancelled
    ) {
      out.push({
        messageId: this.currentEntry.messageId,
        originator: this.currentEntry.originator,
        prompt: this.currentEntry.prompt,
        position: position++,
        enqueuedAt: this.currentEntry.enqueuedAt,
      });
    }
    for (const entry of this.promptQueue) {
      if (entry.kind !== "user" || entry.cancelled) continue;
      out.push({
        messageId: entry.messageId,
        originator: entry.originator,
        prompt: entry.prompt,
        position: position++,
        enqueuedAt: entry.enqueuedAt,
      });
    }
    return out;
  }

  // Wait for any pending queue-file writes to settle. Test hook so
  // assertions about on-disk state don't race with fire-and-forget
  // rewrites. Production code doesn't need this — the chain
  // self-serializes.
  async flushPersistWrites(): Promise<void> {
    await this.queueWriteChain.catch(() => undefined);
  }

  // Push pre-existing queue entries back through the daemon-side
  // pipeline on startup. Called by SessionManager after resurrecting
  // a session that had a non-empty queue.ndjson on disk. Each entry
  // gets a synthetic UserPromptQueueEntry with no real caller
  // (resolve/reject are no-ops since the original WS is long gone),
  // then drainQueue picks it up like any other entry. Late-attaching
  // clients see the entries via prompt_queue_added broadcasts and the
  // attach-response snapshot.
  replayPersistedQueue(entries: PersistedQueueEntry[]): void {
    for (const persisted of entries) {
      const originator: PromptOriginator = {
        clientId: `hydra-resurrected_${persisted.messageId}`,
      };
      if (persisted.originator.clientInfo.name !== undefined) {
        originator.name = persisted.originator.clientInfo.name;
      }
      if (persisted.originator.clientInfo.version !== undefined) {
        originator.version = persisted.originator.clientInfo.version;
      }
      const entry: UserPromptQueueEntry = {
        kind: "user",
        messageId: persisted.messageId,
        originator,
        // Synthetic clientId. broadcastTurnComplete uses this as
        // excludeClientId for the peer-only broadcast; with a synthetic
        // id no real attached client matches the exclude, so everyone
        // sees turn_complete — which is what we want, since none of
        // them originated this restart-replayed prompt.
        clientId: originator.clientId,
        prompt: persisted.prompt as unknown[],
        enqueuedAt: persisted.enqueuedAt,
        cancelled: false,
        resolve: () => undefined,
        reject: () => undefined,
      };
      this.promptQueue.push(entry);
      this.broadcastQueueAdded(entry);
    }
    void this.drainQueue();
  }

  // Drop a queued prompt by messageId. Returns already_running when
  // the messageId names the in-flight entry — callers should fall back
  // to session/cancel for that case. Originator-agnostic: any attached
  // client may cancel any queued prompt (matches the existing slack
  // :stop_sign: reaction UX and the TUI's queue-edit dispatcher).
  cancelQueuedPrompt(messageId: string): CancelPromptResult {
    if (this.currentEntry?.messageId === messageId) {
      return { cancelled: false, reason: "already_running" };
    }
    const idx = this.promptQueue.findIndex((e) => e.messageId === messageId);
    if (idx < 0) {
      return { cancelled: false, reason: "not_found" };
    }
    const entry = this.promptQueue[idx]!;
    entry.cancelled = true;
    this.promptQueue.splice(idx, 1);
    if (entry.kind === "user") {
      this.broadcastQueueRemoved(messageId, "cancelled");
      this.persistRewrite();
    }
    // If this was the in-window amendment, clear amendInProgress so M1's
    // upcoming turn_complete doesn't claim it was amended — the user
    // walked back the amendment, leaving M1 as a plain cancel.
    if (this.amendInProgress?.newMessageId === messageId) {
      this.amendInProgress = undefined;
    }
    // The drainQueue loop won't see this entry again (we just spliced
    // it out). Resolve the original session/prompt promise so the
    // caller's await unblocks with a clean cancelled stop reason.
    entry.resolve({ stopReason: "cancelled" });
    return { cancelled: true, reason: "ok" };
  }

  // Replace the prompt payload of a queued (not-yet-running) entry.
  // Returns already_running for the in-flight head; not_found for
  // unknown messageIds or for internal queue entries (internal tasks
  // don't expose a mutable prompt). Broadcasts prompt_queue_updated on
  // success so every attached client refreshes its chip.
  updateQueuedPrompt(
    messageId: string,
    prompt: unknown[],
  ): UpdatePromptResult {
    if (this.currentEntry?.messageId === messageId) {
      return { updated: false, reason: "already_running" };
    }
    const entry = this.promptQueue.find((e) => e.messageId === messageId);
    if (!entry || entry.kind !== "user") {
      return { updated: false, reason: "not_found" };
    }
    entry.prompt = prompt;
    this.broadcastQueueUpdated(messageId, prompt);
    this.persistRewrite();
    return { updated: true, reason: "ok" };
  }

  // Amend the head prompt: cancel the in-flight turn and submit a
  // replacement that sits at the head of the queue. Resolves the
  // request immediately (the caller doesn't wait on cancel-settle).
  // Honours race outcomes — if the target finished or was cancelled
  // before this arrived, the request resolves with an outcome explaining
  // why and (depending on onTargetCompleted) optionally forwards as a
  // plain prompt. Queued targets are edited in place (same machinery
  // as updateQueuedPrompt).
  amendPrompt(
    clientId: string,
    params: AmendPromptParams,
  ): AmendPromptResult {
    const client = this.clients.get(clientId);
    if (!client) {
      throw withCode(
        new Error("client not attached"),
        JsonRpcErrorCodes.SessionNotFound,
      );
    }
    const { targetMessageId, prompt, replaceQueue, onTargetCompleted } = params;

    // Success path: target is the in-flight head.
    if (
      this.currentEntry?.messageId === targetMessageId &&
      this.currentEntry.kind === "user" &&
      !this.currentEntry.cancelled &&
      this.amendInProgress === undefined
    ) {
      return this.amendOnHead(client, prompt, targetMessageId, replaceQueue);
    }

    // Queued target: edit in place. Shares the same observable behavior
    // as update_prompt — prompt_queue_updated fires, no agent interaction.
    const queuedEntry = this.promptQueue.find(
      (e) => e.messageId === targetMessageId && e.kind === "user",
    );
    if (queuedEntry && queuedEntry.kind === "user" && !queuedEntry.cancelled) {
      queuedEntry.prompt = prompt;
      this.broadcastQueueUpdated(targetMessageId, prompt);
      this.persistRewrite();
      return { amended: true, reason: "ok", messageId: targetMessageId };
    }

    // Recently-terminal target — resolve by stopReason.
    const terminal = this.recentlyTerminal.get(targetMessageId);
    if (terminal) {
      if (terminal.stopReason === "cancelled") {
        return { amended: false, reason: "target_cancelled" };
      }
      if (onTargetCompleted === "send_anyway") {
        const newMessageId = this.enqueueAmendmentAsFollowUp(client, prompt);
        return {
          amended: false,
          reason: "target_completed",
          messageId: newMessageId,
        };
      }
      return { amended: false, reason: "target_completed" };
    }

    return { amended: false, reason: "target_not_found" };
  }

  // Head-of-queue amendment: splice M2 in front of any waiting entries,
  // broadcast the amend window's queue_added with the amending hint,
  // mark amendInProgress so the cancelled turn's broadcastTurnComplete
  // attaches the _meta marker and fires prompt_amended, then fire the
  // upstream session/cancel without awaiting it. drainQueue is already
  // running on the head; when its session/prompt returns, it advances
  // to M2 in the normal way.
  private amendOnHead(
    client: AttachedClient,
    prompt: unknown[],
    targetMessageId: string,
    replaceQueue: boolean | undefined,
  ): AmendPromptResult {
    const newMessageId = generateMessageId();
    const originator: PromptOriginator = { clientId: client.clientId };
    if (client.clientInfo?.name) {
      originator.name = client.clientInfo.name;
    }
    if (client.clientInfo?.version) {
      originator.version = client.clientInfo.version;
    }

    if (replaceQueue) {
      // Drop every other waiting user entry. Each gets a cancelled
      // queue_removed broadcast and its promise resolves with
      // cancelled stopReason so callers awaiting session/prompt unblock.
      const survivors: QueueEntry[] = [];
      for (const entry of this.promptQueue) {
        if (entry.kind === "user" && !entry.cancelled) {
          entry.cancelled = true;
          this.broadcastQueueRemoved(entry.messageId, "cancelled");
          entry.resolve({ stopReason: "cancelled" });
          continue;
        }
        survivors.push(entry);
      }
      this.promptQueue = survivors;
    }

    const entry: UserPromptQueueEntry = {
      kind: "user",
      messageId: newMessageId,
      originator,
      clientId: client.clientId,
      prompt,
      enqueuedAt: Date.now(),
      cancelled: false,
      wasAmend: true,
      // No-op resolve/reject: there's no client request awaiting M2's
      // session/prompt response. The amend_prompt request has already
      // returned by this point. drainQueue calls these unconditionally
      // when runQueueEntry settles; making them no-ops is safe.
      resolve: () => undefined,
      reject: () => undefined,
    };
    // Splice at the head of the waiting queue. currentEntry still holds
    // M1 until its turn settles; M2 is position 1 from the user's POV
    // (M1 in flight, M2 next).
    this.promptQueue.unshift(entry);
    this.persistRewrite();
    this.broadcastQueueAdded(entry, {
      amending: targetMessageId,
      position: 1,
    });

    this.amendInProgress = {
      cancelledMessageId: targetMessageId,
      newMessageId,
    };

    // If M1 is an in-flight extension command dispatch (e.g. the
    // planner's `/hydra planner create`), the agent.connection cancel
    // below is a no-op for it — no agent.session/prompt is parked.
    // Tell the extension directly so it can release its
    // commands/invoke and drainQueue can advance to M2. Extensions
    // outside this dispatch see nothing.
    this.cancelExtensionDispatch(targetMessageId, "amended");

    // Fire-and-forget the cancel notification. The agent's session/prompt
    // for M1 will return with stopReason cancelled; drainQueue's await
    // resolves and we advance to M2 naturally.
    void this.agent.connection
      .notify("session/cancel", { sessionId: this.upstreamSessionId })
      .catch(() => undefined);

    return {
      amended: true,
      reason: "ok",
      messageId: newMessageId,
    };
  }

  // Send the amendment as a plain follow-up prompt — used when the
  // target already completed and the caller opted in to send_anyway.
  // Returns the new prompt's messageId so the result can surface it.
  private enqueueAmendmentAsFollowUp(
    client: AttachedClient,
    prompt: unknown[],
  ): string {
    const messageId = generateMessageId();
    const originator: PromptOriginator = { clientId: client.clientId };
    if (client.clientInfo?.name) {
      originator.name = client.clientInfo.name;
    }
    if (client.clientInfo?.version) {
      originator.version = client.clientInfo.version;
    }
    const entry: UserPromptQueueEntry = {
      kind: "user",
      messageId,
      originator,
      clientId: client.clientId,
      prompt,
      enqueuedAt: Date.now(),
      cancelled: false,
      resolve: () => undefined,
      reject: () => undefined,
    };
    this.promptQueue.push(entry);
    this.persistRewrite();
    this.broadcastQueueAdded(entry);
    void this.drainQueue();
    return messageId;
  }

  async cancel(clientId: string): Promise<void> {
    const client = this.clients.get(clientId);
    if (!client) {
      throw withCode(
        new Error("client not attached"),
        JsonRpcErrorCodes.SessionNotFound,
      );
    }
    // session/cancel is a notification per the ACP spec — agents process it
    // and don't reply. Sending it as a request would hang our promise
    // forever waiting for a response that never comes. The downside: an
    // agent that doesn't support cancel (current opencode after PR #29929
    // returns UnsupportedOperationError) replies with an id-less error
    // frame we can't correlate. We record the send time so the orphan-error
    // observer in wireAgent can attribute a closely-following error to this
    // cancel and surface it to clients via hydra-acp/cancel_failed.
    this.lastCancelAt = Date.now();
    // If the in-flight currentEntry is an extension command dispatch
    // (e.g. a `/hydra planner ...` slash command held open by the
    // planner's commands/invoke), the downstream agent.session/cancel
    // is a no-op for it — no agent turn is parked. Tell the extension
    // directly so it can release its commands/invoke and drainQueue
    // can advance.
    if (
      this.currentEntry?.kind === "user" &&
      this.currentEntry.messageId !== undefined
    ) {
      this.cancelExtensionDispatch(this.currentEntry.messageId, "cancelled");
    }
    // Walk the request-side transformer chain with tailKind=notification:
    // transformers that declared "request:session/cancel" intercept get
    // a chance to observe (continue), suppress (stop), or do async
    // cleanup before agent dispatch (processing + discharge). This is
    // the primitive that lets a transformer holding a session/prompt
    // processing-claim release the claim with stopReason "cancelled"
    // and unwind its own background work before cancel reaches the
    // agent — and, when the held prompt never reached the agent at
    // all, lets the transformer fully absorb the cancel via "stop".
    // forwardRequest handles rewriteForAgent (sessionId → upstreamSessionId).
    await this.forwardRequest(
      "session/cancel",
      { sessionId: this.sessionId },
      new Set<string>(),
      0,
      "notification",
    );
  }

  // Add a transformer to this session's chain retroactively. No-ops if it's
  // already present. Fires session.opened on the new transformer so it gets
  // the same lifecycle signal it would have received at session creation.
  addTransformer(ref: TransformerRef): void {
    const existing = this.transformChain.findIndex((t) => t.name === ref.name);
    if (existing >= 0) {
      this.transformChain[existing] = ref;
    } else {
      this.transformChain.push(ref);
    }
    if (ref.intercepts.has("lifecycle:session.opened")) {
      void ref.connection
        .notify("hydra-acp/transformer/session_event", {
          event: "session.opened",
          sessionId: this.sessionId,
        })
        .catch(() => undefined);
    }
  }

  // Walk the request-side chain then forward to the agent.
  // originatedBy: transformer names already in the lineage — skipped for loop
  //   prevention and to implement resume-routing on re-entry from emit_message.
  // startIdx: chain position to start from (0 for normal, emitterIdx+1 for re-entry).
  // tailKind: how the chain tail dispatches to the agent — "request" (default)
  //   for request methods, "notification" for fire-and-forget methods like
  //   session/cancel. Notifications return undefined and ignore stop payloads.
  async forwardRequest(
    method: string,
    params: unknown,
    originatedBy = new Set<string>(),
    startIdx = 0,
    tailKind: "request" | "notification" = "request",
  ): Promise<unknown> {
    let envelope = this.rewriteForAgent(params);
    for (let i = startIdx; i < this.transformChain.length; i++) {
      const t = this.transformChain[i]!;
      if (originatedBy.has(t.name)) {
        continue;
      }
      const intercept = `request:${method}`;
      if (!t.intercepts.has(intercept)) {
        continue;
      }
      const token = `t_${generateChainToken()}`;
      let result: { action: string; payload?: unknown } | undefined;
      try {
        result = await t.connection.request("hydra-acp/transformer/message", {
          token,
          phase: "request",
          method,
          direction: "client→agent",
          sessionId: this.sessionId,
          envelope,
        }) as { action: string; payload?: unknown } | undefined;
      } catch (err) {
        this.logger?.warn(
          `transformer ${t.name} error on ${intercept}: ${(err as Error).message}`,
        );
        continue;
      }
      const action = result?.action ?? "continue";
      if (action === "stop") {
        if (tailKind === "notification") {
          return undefined;
        }
        return (result?.payload as Record<string, unknown> | undefined) ??
          defaultStopPayload(method);
      }
      if (action === "continue") {
        // A transformer may rewrite the envelope and signal `continue` to
        // hand the modified version on to the next transformer (and the
        // agent). Adopt the rewritten payload — the clarifier uses this
        // path to prepend deviation blocks to session/prompt envelopes.
        if (result?.payload && typeof result.payload === "object") {
          envelope = result.payload;
        }
        originatedBy.add(t.name);
        continue;
      }
      if (action === "processing") {
        const claimIdx = i;
        const claimEnvelope = envelope;
        const claimOriginatedBy = new Set(originatedBy);
        return new Promise((resolve) => {
          const timer = setTimeout(() => {
            if (this.pendingClaims.delete(token)) {
              this.broadcastQueueNotification(
                "hydra-acp/transformer/abandoned_request",
                { sessionId: this.sessionId, token, transformerName: t.name },
              );
              // Fail-open: resume from the next transformer rather than stopping.
              void this.forwardRequest(
                method,
                claimEnvelope,
                new Set([...claimOriginatedBy, t.name]),
                claimIdx + 1,
                tailKind,
              )
                .then(resolve)
                .catch(() =>
                  resolve(tailKind === "notification" ? undefined : defaultStopPayload(method)),
                );
            }
          }, TRANSFORMER_CLAIM_TIMEOUT_MS);
          if (typeof timer.unref === "function") {
            timer.unref();
          }
          this.pendingClaims.set(token, {
            resolve,
            timer,
            transformerName: t.name,
            method,
            envelope: claimEnvelope,
            chainIdx: claimIdx,
            originatedBy: claimOriginatedBy,
            side: "request",
            tailKind,
          });
        });
      }
      // Unknown action — treat as continue without payload-adoption to be
      // safe. Add to originatedBy so we don't loop back on re-emissions.
      originatedBy.add(t.name);
    }
    if (tailKind === "notification") {
      await this.agent.connection.notify(method, envelope);
      return undefined;
    }
    return this.agent.connection.request(method, envelope);
  }

  // Push a model change to the agent, tolerating both wire verbs
  // (`session/set_model` and `session/set_config_option` with
  // configId "model" — see model-verb.ts for why both exist). Routes
  // through forwardRequest so the transformer chain still sees the
  // call; a probe that gets MethodNotFound means transformers may see
  // the rejected verb first, then the accepted one.
  //
  // Every hydra path that changes a live session's model MUST go
  // through here rather than forwarding session/set_model directly —
  // otherwise agents on @agentclientprotocol/sdk >= 0.26 (pi-acp) fail
  // the change with -32601.
  async forwardModelChange(
    modelId: string,
    extraParams?: Record<string, unknown>,
  ): Promise<unknown> {
    const outcome = await requestModelChange({
      request: (method, params) => this.forwardRequest(method, params),
      sessionId: this.sessionId,
      modelId,
      verb: this.modelVerb,
      extraParams,
      logger: this.logger,
    });
    // An accepted call is ground truth — pin it so later hints can't
    // move us back onto a verb the agent already rejected.
    this.modelVerb = outcome.verb;
    this.modelVerbConfirmed = true;
    return outcome.result;
  }

  // Adopt an inferred lead verb (from a session/new response shape or an
  // agent notification). No-op once a real call has confirmed a verb, or
  // when there's nothing to infer.
  private noteModelVerbHint(verb: ModelVerb | undefined, source: string): void {
    if (verb === undefined || this.modelVerbConfirmed || verb === this.modelVerb) {
      return;
    }
    this.logger?.info(
      `model verb for agent ${this.agentId} inferred as ${verb} from ${source} (was ${this.modelVerb})`,
    );
    this.modelVerb = verb;
  }

  // Reset the model-verb state for a fresh agent generation. A swapped-in
  // agent may speak the other verb, so nothing about the dead agent's
  // answer carries over.
  private resetModelVerb(verb: ModelVerb | undefined): void {
    this.modelVerb = verb ?? MODEL_VERB_SET_MODEL;
    this.modelVerbConfirmed = false;
  }

  // Walk the agent→client request chain. Currently dispatched for
  // session/request_permission, but the helper is generic — any future
  // agent→client request (fs/*, terminal/*) can route through this same
  // path by declaring `request:<method>` with direction "agent→client".
  //
  // Returns:
  //   { shortCircuit: false, envelope } — pass the (possibly rewritten)
  //     envelope to the original handler. Default when no transformer stops.
  //   { shortCircuit: true, payload } — return this payload to the agent
  //     in place of the handler's reply. The handler is NOT called.
  //
  // Actions:
  //   continue   — pass to next transformer; payload (if returned) replaces envelope.
  //   stop       — short-circuit. Payload becomes the synthesized response.
  //                Default for stop without payload is defaultAgentRequestDeny.
  //   processing — park a claim. The transformer answers later via
  //                emit_message with respondsTo, and that value becomes
  //                the short-circuit payload.
  async runAgentRequestChain(
    method: string,
    params: unknown,
    originatedBy = new Set<string>(),
    startIdx = 0,
  ): Promise<
    | { shortCircuit: false; envelope: unknown }
    | { shortCircuit: true; payload: unknown }
  > {
    let envelope = params;
    const interceptName = `request:${method}`;
    for (let i = startIdx; i < this.transformChain.length; i++) {
      const t = this.transformChain[i]!;
      if (originatedBy.has(t.name)) {
        continue;
      }
      if (!t.intercepts.has(interceptName)) {
        continue;
      }
      const token = `t_${generateChainToken()}`;
      let result: { action: string; payload?: unknown } | undefined;
      try {
        result = await t.connection.request("hydra-acp/transformer/message", {
          token,
          phase: "request",
          method,
          direction: "agent→client",
          sessionId: this.sessionId,
          envelope,
        }) as { action: string; payload?: unknown } | undefined;
      } catch (err) {
        this.logger?.warn(
          `transformer ${t.name} error on ${interceptName}: ${(err as Error).message}`,
        );
        continue;
      }
      const action = result?.action ?? "continue";
      if (action === "stop") {
        return {
          shortCircuit: true,
          payload: result?.payload ?? defaultAgentRequestDeny(method),
        };
      }
      if (action === "continue") {
        if (result?.payload && typeof result.payload === "object") {
          envelope = result.payload;
        }
        originatedBy.add(t.name);
        continue;
      }
      if (action === "processing") {
        const claimIdx = i;
        const claimEnvelope = envelope;
        const claimOriginatedBy = new Set(originatedBy);
        const claimMethod = method;
        return new Promise<
          | { shortCircuit: false; envelope: unknown }
          | { shortCircuit: true; payload: unknown }
        >((resolve) => {
          const timer = setTimeout(() => {
            if (this.pendingClaims.delete(token)) {
              this.broadcastQueueNotification(
                "hydra-acp/transformer/abandoned_request",
                { sessionId: this.sessionId, token, transformerName: t.name },
              );
              // Fail-open: resume from the next transformer rather than
              // forcing a denial. If no further transformer claims, the
              // handler runs with the envelope as-of the abandonment.
              void this.runAgentRequestChain(
                claimMethod,
                claimEnvelope,
                new Set([...claimOriginatedBy, t.name]),
                claimIdx + 1,
              )
                .then(resolve)
                .catch(() =>
                  resolve({ shortCircuit: false, envelope: claimEnvelope }),
                );
            }
          }, TRANSFORMER_CLAIM_TIMEOUT_MS);
          if (typeof timer.unref === "function") {
            timer.unref();
          }
          this.pendingClaims.set(token, {
            // Discharge value is the transformer's synthesized response.
            resolve: (v) => resolve({ shortCircuit: true, payload: v }),
            timer,
            transformerName: t.name,
            method: claimMethod,
            envelope: claimEnvelope,
            chainIdx: claimIdx,
            originatedBy: claimOriginatedBy,
            side: "agent-request",
          });
        });
      }
      // Unknown action — continue without payload-adoption.
      originatedBy.add(t.name);
    }
    return { shortCircuit: false, envelope };
  }

  // Called by the WS handler when emit_message carries respondsTo.
  // Discharges the outstanding claim so the original requester unblocks.
  dischargeClaim(token: string, result: unknown): boolean {
    const claim = this.pendingClaims.get(token);
    if (!claim) {
      return false;
    }
    clearTimeout(claim.timer);
    this.pendingClaims.delete(token);
    claim.resolve(result);
    return true;
  }

  // Called by the WS handler on hydra-acp/connection/keep_alive.
  // Resets the abandonment timer for an outstanding processing claim.
  keepAliveClaim(
    token: string,
    estimatedRemainingMs?: number,
  ): boolean {
    const claim = this.pendingClaims.get(token);
    if (!claim) {
      return false;
    }
    clearTimeout(claim.timer);
    const timeout = typeof estimatedRemainingMs === "number" && estimatedRemainingMs > 0
      ? Math.min(estimatedRemainingMs * 1.5, 30 * 60 * 1000) // cap at 30 min
      : TRANSFORMER_CLAIM_TIMEOUT_MS;
    const timer = setTimeout(() => {
      if (this.pendingClaims.delete(token)) {
        this.broadcastQueueNotification(
          "hydra-acp/transformer/abandoned_request",
          { sessionId: this.sessionId, token, transformerName: claim.transformerName },
        );
        if (claim.side === "response") {
          void this.runResponseChain(
            claim.envelope,
            new Set([...claim.originatedBy, claim.transformerName]),
            claim.chainIdx + 1,
          )
            .then(() => claim.resolve(undefined))
            .catch(() => claim.resolve(undefined));
        } else if (claim.side === "agent-request") {
          void this.runAgentRequestChain(
            claim.method,
            claim.envelope,
            new Set([...claim.originatedBy, claim.transformerName]),
            claim.chainIdx + 1,
          )
            .then(claim.resolve)
            .catch(() =>
              claim.resolve({
                shortCircuit: false,
                envelope: claim.envelope,
              }),
            );
        } else {
          const tailKind = claim.tailKind ?? "request";
          void this.forwardRequest(
            claim.method,
            claim.envelope,
            new Set([...claim.originatedBy, claim.transformerName]),
            claim.chainIdx + 1,
            tailKind,
          )
            .then(claim.resolve)
            .catch(() =>
              claim.resolve(tailKind === "notification" ? undefined : defaultStopPayload(claim.method)),
            );
        }
      }
    }, timeout);
    if (typeof timer.unref === "function") {
      timer.unref();
    }
    claim.timer = timer;
    return true;
  }

  // Called by the WS handler when a transformer emits via route:"chain".
  // Finds the emitter's position and re-enters the appropriate chain walk
  // from the next slot, with the emitter in originatedBy so it cannot see
  // its own re-emission. Returns the value the chain (and ultimately the
  // agent) produced — `undefined` for session/update notifications (no
  // return value), the agent's response for request methods. The WS
  // handler surfaces this so a transformer can re-emit a modified
  // request via the chain and capture the response (e.g. to discharge
  // a parked processing claim).
  async emitToChain(
    emitterName: string,
    method: string,
    envelope: unknown,
  ): Promise<unknown> {
    const emitterIdx = this.transformChain.findIndex((t) => t.name === emitterName);
    const startIdx = emitterIdx >= 0 ? emitterIdx + 1 : 0;
    const originatedBy = new Set([emitterName]);

    // session/update is a notification — run the response-side chain.
    if (method === "session/update") {
      await this.runResponseChain(envelope, originatedBy, startIdx);
      return undefined;
    }
    // Everything else is treated as a request — forward to the agent if the
    // chain doesn't stop it.
    return this.forwardRequest(method, envelope, originatedBy, startIdx);
  }

  // Companion to emitToChain for session/prompt envelopes that
  // ORIGINATE a fresh user-equivalent turn on this session (e.g. the
  // planner dispatching a worker, or planner re-prompting an
  // orchestrator). Enqueues a real UserPromptQueueEntry instead of
  // calling forwardRequest directly — so broadcastPromptReceived
  // fires, turnStartedAt is set, queue chips render, and
  // broadcastTurnComplete pairs the turn correctly on the wire.
  //
  // The emitter's own request:session/prompt intercept is skipped
  // (via chainStartIdx threaded through to forwardRequest) so a
  // transformer that both injects prompts AND intercepts them
  // doesn't loop on itself — same skip semantics as emitToChain,
  // just with the queue lifecycle layered on top.
  //
  // Returns the agent's session/prompt response once the queued
  // entry drains and the agent completes the turn. If the entry is
  // dropped via cancelQueuedPrompt before reaching the head, resolves
  // with { stopReason: "cancelled" } like any other cancelled queue
  // entry.
  async emitToQueue(
    emitterName: string,
    envelope: unknown,
  ): Promise<unknown> {
    const emitterIdx = this.transformChain.findIndex((t) => t.name === emitterName);
    const chainStartIdx = emitterIdx >= 0 ? emitterIdx + 1 : 0;
    const promptArray = (((envelope ?? {}) as { prompt?: unknown[] }).prompt ??
      []) as unknown[];
    const messageId = generateMessageId();
    const synthClientId = `transformer:${emitterName}`;
    const originator: PromptOriginator = {
      clientId: synthClientId,
      name: emitterName,
    };
    return new Promise<unknown>((resolve, reject) => {
      const entry: UserPromptQueueEntry = {
        kind: "user",
        messageId,
        originator,
        clientId: synthClientId,
        prompt: promptArray,
        enqueuedAt: Date.now(),
        cancelled: false,
        emitterName,
        chainStartIdx,
        resolve,
        reject,
      };
      const insertedAt = this.insertEntryAt(entry, "tail");
      this.persistRewrite();
      this.broadcastQueueAdded(entry, { position: insertedAt });
      void this.drainQueue();
    });
  }

  private rewriteForAgent(params: unknown): unknown {
    if (params && typeof params === "object" && !Array.isArray(params)) {
      const obj = params as Record<string, unknown>;
      if (obj.sessionId === this.sessionId) {
        return { ...obj, sessionId: this.upstreamSessionId };
      }
    }
    return params;
  }

  async close(opts: CloseOptions = {}): Promise<void> {
    if (opts.deleteRecord) {
      this.deleteRecordIntent = true;
    }
    if (this.closed) {
      return;
    }
    // Reentrancy guard: if a close is already in progress (e.g. picker
    // `k` racing with an attached-client disconnect, or two callers
    // hitting kill in parallel), return the in-flight promise instead
    // of starting a second close. Without this, both calls fire agent
    // regen + agent.kill in parallel — wastes tokens and causes the
    // second regen to reject with "connection closed" when the first
    // kill lands.
    if (this.closeInFlight) {
      return this.closeInFlight;
    }
    this.closing = true;
    this.closeInFlight = this.doClose(opts);
    return this.closeInFlight;
  }

  private async doClose(opts: CloseOptions): Promise<void> {
    this.logger?.info(
      `session ${this.sessionId} closing deleteRecord=${opts.deleteRecord ?? false}`,
    );
    this.cancelIdleTimer();
    for (const claim of this.pendingClaims.values()) {
      clearTimeout(claim.timer);
    }
    this.pendingClaims.clear();
    await this.agent.kill().catch(() => undefined);
    this.markClosed({ deleteRecord: opts.deleteRecord ?? false });
  }

  onClose(handler: (opts: { deleteRecord: boolean }) => void): () => void {
    this.closeHandlers.push(handler);
    return () => {
      const i = this.closeHandlers.indexOf(handler);
      if (i >= 0) {
        this.closeHandlers.splice(i, 1);
      }
    };
  }

  // Subscribe to title updates. The SessionManager hooks this to
  // persist the new title to disk so a daemon restart restores it.
  onTitleChange(handler: (title: string) => void): void {
    this.titleHandlers.push(handler);
  }

  // External entry point for retitling a live session from outside the
  // ACP slash-command path (e.g. PATCH /v1/sessions/:id from the picker).
  // Goes through the same enqueuePrompt path as /hydra title so it
  // serializes after any in-flight turn and shares broadcast/persistence.
  retitle(title: string): Promise<unknown> {
    return this.runTitleCommand(title);
  }

  // External entry point for the LLM-regen title path (T in the picker,
  // equivalent to bare /hydra title with no arg).
  retitleFromAgent(): Promise<unknown> {
    return this.runTitleCommand("");
  }

  // Update the canonical title and broadcast a session_info_update to
  // every attached client. Clients that already speak the spec's
  // session_info_update need no hydra-specific wiring to pick this up.
  // Idempotent on identical values.
  private setTitle(title: string): void {
    const trimmed = title.trim();
    if (!trimmed || trimmed === this.title) {
      return;
    }
    this.title = trimmed;
    this.recordAndBroadcast("session/update", {
      sessionId: this.sessionId,
      update: {
        sessionUpdate: "session_info_update",
        title: trimmed,
        updatedAt: new Date().toISOString(),
      },
    });
    for (const handler of this.titleHandlers) {
      try {
        handler(trimmed);
      } catch {
        void 0;
      }
    }
  }

  // First-prompt heuristic: derive a session title from the first
  // session/prompt's text. Replaces whatever was set at session/new
  // (typically an editor frame name like "Claude Agent @ hydra-acp")
  // — the first prompt is a better summary for cross-client display
  // than the editor's static frame label. Subsequent prompts don't
  // touch the title; that'd flap as conversations evolved.
  private maybeSeedTitleFromPrompt(params: unknown): void {
    if (this.firstPromptSeeded) {
      return;
    }
    // Machine traffic is not a conversation summary. An ancillary turn
    // (`hydra cat`, transformer-driven worker prompts) or one carrying
    // per-prompt provenance came from a program or a peer session, not
    // from someone describing what this session is for, so titling a
    // session "Build 12847 failed: 3 link errors" is just wrong. Same
    // reasoning as the slash-command skip below. Note the caller
    // promotes _firstPromptSeeded unconditionally right after this
    // returns, so a skip here means the session keeps whatever title
    // session/new gave it rather than deferring to a later prompt.
    const meta = extractHydraMeta(
      ((params ?? {}) as { _meta?: Record<string, unknown> })._meta,
    );
    if (meta.ancillary === true || this.promptCarriesSentBy(params)) {
      return;
    }
    const promptParams = (params ?? {}) as { prompt?: unknown };
    const text = extractPromptText(promptParams.prompt);
    const seed = firstLine(text, 200);
    if (!seed) {
      return;
    }
    // Skip slash commands as title seeds. `/hydra planner create`,
    // `/model gpt-5`, etc. are administrative or routing prompts —
    // not the conversational summary a session title is meant to
    // capture. Subsequent non-slash prompts can still seed (the
    // _firstPromptSeeded flag stays false for slash-only flows so
    // the next real prompt wins).
    if (seed.startsWith("/")) {
      return;
    }
    this._firstPromptSeeded = true;
    this.setTitle(seed);
  }

  // Apply an agent-emitted current_model_update. Returns true if the
  // notification was a model update (caller still needs to broadcast
  // it). Returns false otherwise so the caller can try the next kind.
  // current_model_update can carry availableModels in the same payload
  // (per ACP spec); we cache that list too so session/set_model can
  // validate against it.
  private maybeApplyAgentModel(params: unknown): boolean {
    const obj = (params ?? {}) as { update?: unknown };
    const update = (obj.update ?? {}) as {
      sessionUpdate?: unknown;
      currentModel?: unknown;
      model?: unknown;
      availableModels?: unknown;
    };
    if (update.sessionUpdate !== "current_model_update") {
      return false;
    }
    const models = parseModelsList(update.availableModels);
    if (models.length > 0) {
      this.setAgentAdvertisedModels(models);
    }
    const raw =
      typeof update.currentModel === "string"
        ? update.currentModel
        : typeof update.model === "string"
        ? update.model
        : undefined;
    if (raw === undefined) {
      return true;
    }
    const trimmed = raw.trim();
    if (!trimmed || trimmed === this.currentModel) {
      return true;
    }
    this.logger?.info(
      `live current_model_update: sessionId=${this.sessionId} ${JSON.stringify(this.currentModel)} → ${JSON.stringify(trimmed)}`,
    );
    this.currentModel = trimmed;
    for (const handler of this.modelHandlers) {
      try {
        handler(trimmed);
      } catch {
        void 0;
      }
    }
    this.broadcastConfigOptions();
    return true;
  }

  // Apply an agent-emitted config_option_update. claude-acp and opencode
  // emit this (not the spec-shaped current_model_update /
  // available_modes_update) to carry the current value AND option list for
  // model and mode. The payload is `configOptions: [{ id, currentValue,
  // options: [{ value, name }] }, ...]`. We harvest the "model" and "mode"
  // entries — other ids (e.g. "effort") are agent-internal and ignored.
  // Harvesting the mode list here is what populates availableModes for
  // agents that never send available_modes_update (so the TUI's Shift+Tab
  // cycle has something to cycle through). Returns true when recognized so
  // the wireAgent loop stops trying further extractors (the original frame
  // still broadcasts; config-options-aware clients render it directly).
  private maybeApplyAgentConfigOption(params: unknown): boolean {
    const obj = (params ?? {}) as { update?: unknown };
    const update = (obj.update ?? {}) as {
      sessionUpdate?: unknown;
      configOptions?: unknown;
    };
    if (update.sessionUpdate !== "config_option_update") {
      return false;
    }
    const list = update.configOptions;
    if (!Array.isArray(list)) {
      return true;
    }
    for (const raw of list) {
      if (!raw || typeof raw !== "object") {
        continue;
      }
      const opt = raw as {
        id?: unknown;
        currentValue?: unknown;
        options?: unknown;
      };
      if (opt.id === "model") {
        const models = parseModelsList(opt.options);
        if (models.length > 0) {
          this.setAgentAdvertisedModels(models);
        }
        const cv = opt.currentValue;
        if (typeof cv === "string") {
          const trimmed = cv.trim();
          if (trimmed && trimmed !== this.currentModel) {
            this.logger?.info(
              `live config_option_update(model): sessionId=${this.sessionId} ${JSON.stringify(this.currentModel)} → ${JSON.stringify(trimmed)}`,
            );
            // Delegate to applyModelChange so the daemon also emits a
            // spec-shaped current_model_update. claude-acp/opencode carry
            // the new model only in this non-spec config_option_update;
            // clients that don't render it (notably the TUI) would
            // otherwise stay pinned to the agent's earlier stale value.
            this.applyModelChange(trimmed);
          }
        }
      } else if (opt.id === "mode") {
        const modes = parseModesList(opt.options);
        if (modes.length > 0) {
          this.setAgentAdvertisedModes(modes);
        }
        const cv = opt.currentValue;
        if (typeof cv === "string") {
          const trimmed = cv.trim();
          if (trimmed && trimmed !== this.currentMode) {
            this.logger?.info(
              `live config_option_update(mode): sessionId=${this.sessionId} ${JSON.stringify(this.currentMode)} → ${JSON.stringify(trimmed)}`,
            );
            // Mirror the model branch: emit a spec-shaped
            // current_mode_update so mode-only clients (the TUI) repaint.
            this.applyModeChange(trimmed);
          }
        }
      } else if (typeof opt.id === "string" && opt.id.trim()) {
        // Non-standard config option (e.g. "effort", "thought_level").
        // Store it so buildConfigOptions can surface it alongside
        // model/mode/agent — agents advertise these only in the
        // config_option_update payload, never via a dedicated channel.
        const id = opt.id.trim();
        const options = parseModelsList(opt.options);
        if (options.length > 0) {
          const modeList = parseModesList(opt.options);
          const valueOpts: ConfigOptionValue[] = modeList.length > 0
            ? modeList.map((m) => ({
                value: m.id,
                name: m.name ?? m.id,
              }))
            : options.map((m) => ({
                value: m.modelId,
                name: m.name ?? m.modelId,
              }));
          const rawName = (opt as { name?: unknown }).name;
          const name = typeof rawName === "string" && rawName.trim() ? rawName.trim() : id;
          const rawCv = opt.currentValue;
          const currentValue =
            typeof rawCv === "string" && rawCv.trim()
              ? rawCv.trim()
              : valueOpts[0]?.value ?? "";
          const existing = this.agentAdvertisedConfigOptions.findIndex(
            (o) => o.id === id,
          );
          if (existing >= 0) {
            const updated = { ...this.agentAdvertisedConfigOptions[existing]! };
            updated.options = valueOpts;
            if (typeof rawCv === "string" && rawCv.trim()) {
              updated.currentValue = rawCv.trim();
            }
            this.agentAdvertisedConfigOptions[existing] = updated;
          } else {
            this.agentAdvertisedConfigOptions.push({
              id,
              name,
              category: "other",
              type: "select",
              currentValue,
              options: valueOpts,
            });
          }
        }
      }
    }
    return true;
  }

  private maybeApplyAgentMode(params: unknown): boolean {
    const obj = (params ?? {}) as { update?: unknown };
    const update = (obj.update ?? {}) as {
      sessionUpdate?: unknown;
      currentModeId?: unknown;
      currentMode?: unknown;
      mode?: unknown;
    };
    if (update.sessionUpdate !== "current_mode_update") {
      return false;
    }
    const raw =
      typeof update.currentModeId === "string"
        ? update.currentModeId
        : typeof update.currentMode === "string"
        ? update.currentMode
        : typeof update.mode === "string"
        ? update.mode
        : undefined;
    if (raw === undefined) {
      return true;
    }
    const trimmed = raw.trim();
    if (!trimmed || trimmed === this.currentMode) {
      return true;
    }
    this.logger?.info(
      `current_mode_update: sessionId=${this.sessionId} ${JSON.stringify(this.currentMode)} → ${JSON.stringify(trimmed)}`,
    );
    this.currentMode = trimmed;
    for (const handler of this.modeHandlers) {
      try {
        handler(trimmed);
      } catch {
        void 0;
      }
    }
    this.broadcastConfigOptions();
    return true;
  }

  // usage_update carries any subset of {used, size, cost.amount,
  // cost.currency}. Merge non-undefined fields onto currentUsage so a
  // sparse update preserves prior values, and fire usage handlers only
  // if something actually changed.
  private maybeApplyAgentUsage(params: unknown): boolean {
    const obj = (params ?? {}) as { update?: unknown };
    const update = (obj.update ?? {}) as {
      sessionUpdate?: unknown;
      used?: unknown;
      size?: unknown;
      cost?: unknown;
    };
    if (update.sessionUpdate !== "usage_update") {
      return false;
    }
    const next: UsageSnapshot = { ...(this._currentUsage ?? {}) };
    let changed = false;
    if (typeof update.used === "number" && next.used !== update.used) {
      next.used = update.used;
      changed = true;
    }
    if (typeof update.size === "number" && next.size !== update.size) {
      next.size = update.size;
      changed = true;
    }
    if (update.cost && typeof update.cost === "object") {
      const cost = update.cost as { amount?: unknown; currency?: unknown };
      if (typeof cost.amount === "number") {
        // Must run before the change check: an agent that resumes its ledger
        // may re-report a value we already hold, and the probe still needs
        // to fire so the duplicate banked copy is dropped.
        if (this.reconcileCostLedger(cost.amount)) {
          changed = true;
        }
        if (next.costAmount !== cost.amount) {
          next.costAmount = cost.amount;
          changed = true;
        }
      }
      if (
        typeof cost.currency === "string" &&
        next.costCurrency !== cost.currency
      ) {
        next.costCurrency = cost.currency;
        changed = true;
      }
    }
    if (!changed) {
      return true;
    }
    this._currentUsage = next;
    // Fire handlers with the split, not the collapsed total. The sole
    // consumer is SessionManager's persistSnapshot, and meta.json needs both
    // fields kept apart — see persistableUsage. A daemon restart reconstructs
    // the lifetime total by summing them.
    const snapshot = this.persistableUsage ?? next;
    for (const handler of this.usageHandlers) {
      try {
        handler(snapshot);
      } catch {
        void 0;
      }
    }
    return true;
  }

  // Retain the previous life's raw amount for adjudication. Call only on
  // paths where the incoming agent reloads the SAME upstream session, since
  // that raw amount is precisely the spend the agent may re-report. Cold
  // resurrect is the only such path; rollback targets a different session.
  //
  // Note this is costAmount, NOT the lifetime total: cumulativeCost covers
  // retired upstream sessions the reloaded agent has never seen and could
  // never report, so including it would make the comparison unwinnable for
  // any session that has rotated.
  private armCostLedgerProbe(): void {
    const raw = this._currentUsage?.costAmount;
    if (typeof raw === "number" && raw > 0) {
      this.costLedgerProbe = raw;
    }
  }

  // One-shot adjudication of the first cost report after reloading an
  // upstream session. The retained raw amount is still sitting in
  // _currentUsage.costAmount and is about to be overwritten by replacement:
  //
  //   incoming >= retained — the agent's ledger survived the reload and
  //     already covers it; replacement alone is correct, do nothing.
  //   incoming <  retained — the agent restarted at $0, so replacement would
  //     drop the retained spend; bank it into cumulativeCost first.
  //
  // Returns true if the banked total was adjusted, so the caller can force a
  // persist even when the reported amount itself is unchanged.
  private reconcileCostLedger(incoming: number): boolean {
    const probe = this.costLedgerProbe;
    if (probe === undefined) {
      return false;
    }
    this.costLedgerProbe = undefined;
    // Tolerance absorbs float drift in the agent's own summation; the two
    // populations (continued ledger vs restarted at ~0) are far apart.
    if (incoming >= probe - 1e-6) {
      return false;
    }
    this.cumulativeCost += probe;
    return true;
  }

  // Notify agentChange handlers that the upstream (and possibly the agent)
  // rotated, so SessionManager's persistAgentChange writes the new ids and
  // stamps the retiring generation's spend.
  //
  // retiringGenerationCost is consumed here and cleared. Clearing is
  // load-bearing: the next rotation may retire a generation that never
  // reported any usage (two swaps with no turn in between), and
  // accumulateAndResetCost only assigns the field when there is a nonzero
  // amount to bank. A sticky value would then be stamped onto a
  // zero-spend generation, mis-attributing the earlier generation's spend
  // a second time. The lifetime total is unaffected — cumulativeCost is
  // banked separately — but per-generation attribution would be wrong.
  private notifyAgentChange(context: string): void {
    const retiredCost = this.retiringGenerationCost;
    this.retiringGenerationCost = undefined;
    for (const handler of this.agentChangeHandlers) {
      try {
        handler({
          agentId: this.agentId,
          upstreamSessionId: this.upstreamSessionId,
          ...(retiredCost !== undefined ? { retiredCost } : {}),
        });
      } catch (err) {
        this.logger?.warn(
          `${context}: agentChange handler failed: ${(err as Error).message}`,
        );
      }
    }
  }

  // Move currentUsage.costAmount into cumulativeCost and clear it so the
  // next agent life starts accumulating from $0. Fires usageHandlers so
  // meta.json is updated before the new agent starts emitting.
  private accumulateAndResetCost(): void {
    // Called when the upstream agent rotates (compaction swap, /hydra agent
    // switch, seed-from-import). Roll the prior life's cost into the
    // cumulative running total, then reset per-life context-window
    // utilization so the status bar shows "0 tokens used" right after
    // a swap instead of carrying the OLD agent's last figure until the
    // new agent's first turn emits a usage_update.
    //
    // used must be set to 0 (NOT cleared to undefined): the TUI's
    // usage_update handler only writes the field when the incoming
    // event has it `!== undefined`, so an omitted field is interpreted
    // as "no change". Setting an explicit 0 forces the visible
    // refresh to 0/<size>.
    //
    // size is preserved when known — the model's context window is a
    // property of the agent+model pair, not the agent's runtime state,
    // and the new agent will overwrite if its model changes.
    //
    // cumulativeCost is the cross-lives running total and rolls
    // forward; costAmount is reset implicitly by being absent from
    // next (the currentUsage getter folds cumulativeCost into the
    // displayed costAmount).
    const amount = this._currentUsage?.costAmount;
    if (amount) {
      this.cumulativeCost += amount;
      this.retiringGenerationCost = amount;
    }
    const next: UsageSnapshot = {
      used: 0,
      cumulativeCost: this.cumulativeCost,
      ...(typeof this._currentUsage?.size === "number"
        ? { size: this._currentUsage.size }
        : {}),
      ...(this._currentUsage?.costCurrency
        ? { costCurrency: this._currentUsage.costCurrency }
        : {}),
    };
    this._currentUsage = next;
    for (const handler of this.usageHandlers) {
      try {
        handler(next);
      } catch {
        void 0;
      }
    }
    // Broadcast a usage_update so already-attached clients (the TUI's
    // status bar in particular) drop the OLD agent's used/size figures
    // immediately rather than wait for the new agent's first turn to
    // emit a fresh usage_update. State-update kinds are not appended
    // to history.jsonl by recordAndBroadcast, so this is a pure
    // live-broadcast — no double-record, no replay churn.
    const displayed = this.currentUsage;
    if (displayed !== undefined) {
      const update: Record<string, unknown> = { sessionUpdate: "usage_update" };
      if (typeof displayed.used === "number") {
        update.used = displayed.used;
      }
      if (typeof displayed.size === "number") {
        update.size = displayed.size;
      }
      if (
        typeof displayed.costAmount === "number" ||
        typeof displayed.costCurrency === "string"
      ) {
        const cost: Record<string, unknown> = {};
        if (typeof displayed.costAmount === "number") {
          cost.amount = displayed.costAmount;
        }
        if (typeof displayed.costCurrency === "string") {
          cost.currency = displayed.costCurrency;
        }
        update.cost = cost;
      }
      this.recordAndBroadcast("session/update", {
        sessionId: this.upstreamSessionId,
        update,
      });
    }
  }

  // Returns a modified envelope with cost.amount replaced by the running
  // total (cumulativeCost + raw agent amount). No-op if the envelope
  // doesn't carry a numeric cost.amount.
  private injectCumulativeCost(envelope: unknown): unknown {
    if (!this.cumulativeCost)
      return envelope;
    if (!envelope || typeof envelope !== "object")
      return envelope;
    const obj = envelope as Record<string, unknown>;
    if (!obj.update || typeof obj.update !== "object")
      return envelope;
    const update = obj.update as Record<string, unknown>;
    if (update.sessionUpdate !== "usage_update")
      return envelope;
    if (!update.cost || typeof update.cost !== "object")
      return envelope;
    const cost = update.cost as Record<string, unknown>;
    if (typeof cost.amount !== "number")
      return envelope;
    return {
      ...obj,
      update: {
        ...update,
        cost: { ...cost, amount: this.cumulativeCost + cost.amount },
      },
    };
  }

  // Deprecated alias — currentUsage already returns the total.
  get totalUsage(): UsageSnapshot | undefined {
    return this.currentUsage;
  }

  // Update the cached agent command list, fire persist handlers, and
  // broadcast the merged list to attached clients. Idempotent on a
  // structurally identical list so we don't churn meta.json on noisy
  // re-emissions.
  private setAgentAdvertisedCommands(commands: AdvertisedCommand[]): void {
    if (sameAdvertisedCommands(this.agentAdvertisedCommands, commands)) {
      // Still broadcast — a fresh attach might be racing — but skip
      // persistence to avoid pointless meta.json writes.
      this.broadcastMergedCommands();
      return;
    }
    this.agentAdvertisedCommands = commands;
    for (const handler of this.agentCommandsHandlers) {
      try {
        handler(commands);
      } catch {
        void 0;
      }
    }
    this.broadcastMergedCommands();
  }

  private setAgentAdvertisedModes(modes: AdvertisedMode[]): void {
    if (sameAdvertisedModes(this.agentAdvertisedModes, modes)) {
      this.broadcastAvailableModes();
      return;
    }
    this.agentAdvertisedModes = modes;
    for (const handler of this.agentModesHandlers) {
      try {
        handler(modes);
      } catch {
        void 0;
      }
    }
    this.broadcastAvailableModes();
  }

  private setAgentAdvertisedModels(models: AdvertisedModel[]): void {
    this.logger?.info(
      `setAgentAdvertisedModels: sessionId=${this.sessionId} currentModel=${JSON.stringify(this.currentModel)} newList=[${models.map((m) => m.modelId).join(",")}]`,
    );
    if (sameAdvertisedModels(this.agentAdvertisedModels, models)) {
      // No structural change — skip the persistence fan-out but still
      // rebroadcast so a racing mid-session attach gets the snapshot
      // (same idempotency contract as commands/modes setters).
      this.broadcastAvailableModels();
      return;
    }
    this.agentAdvertisedModels = models;
    for (const handler of this.agentModelsHandlers) {
      try {
        handler(models);
      } catch {
        void 0;
      }
    }
    this.broadcastAvailableModels();
  }

  // Subscribe to snapshot-state updates. SessionManager wires these to
  // persist the new value into meta.json so cold resurrect can restore
  // them via the attach response _meta.
  onAgentCommandsChange(
    handler: (commands: AdvertisedCommand[]) => void,
  ): void {
    this.agentCommandsHandlers.push(handler);
  }

  onAgentModesChange(handler: (modes: AdvertisedMode[]) => void): void {
    this.agentModesHandlers.push(handler);
  }

  onAgentModelsChange(handler: (models: AdvertisedModel[]) => void): void {
    this.agentModelsHandlers.push(handler);
  }

  onModelChange(handler: (model: string) => void): void {
    this.modelHandlers.push(handler);
  }

  onModeChange(handler: (mode: string) => void): void {
    this.modeHandlers.push(handler);
  }

  onInteractiveChange(handler: (interactive: boolean) => void): void {
    this.interactiveHandlers.push(handler);
  }

  onPriorityChange(handler: (priority: number | undefined) => void): void {
    this.priorityHandlers.push(handler);
  }

  // Update the user-set sort weight. Passing 0 or undefined returns the
  // session to normal priority. Notifies registered handlers so the
  // SessionManager can persist to meta.json. No client broadcast — the
  // picker's auto-refresh picks the new value up on the next tick.
  setPriority(priority: number | undefined): void {
    const next =
      priority === undefined || priority <= 0 ? undefined : Math.floor(priority);
    if (next === this._priority) {
      return;
    }
    this._priority = next;
    this.updatedAt = Date.now();
    for (const handler of this.priorityHandlers) {
      try {
        handler(next);
      } catch {
        void 0;
      }
    }
  }

  // Apply a model change initiated by a client request (session/set_model)
  // when the agent doesn't emit a current_model_update notification, or
  // emits a non-spec shape (e.g. config_option_update). Fires modelHandlers
  // (persistence) and broadcasts a synthetic current_model_update so all
  // attached clients — including the originator — repaint immediately.
  //
  // The broadcast fires even when `modelId` already equals currentModel.
  // claude-acp emits a stale current_model_update (with the pre-change
  // value) during set_model processing and a separate config_option_update
  // with the new value; the configOption path updates currentModel here
  // before our synthetic broadcast would run, so a value-equality guard
  // would suppress the corrective broadcast and leave attached clients
  // (notably the TUI, which doesn't render config_option_update) showing
  // the stale model from the agent's earlier notification.
  applyModelChange(modelId: string): void {
    const trimmed = modelId.trim();
    if (!trimmed) {
      return;
    }
    this.modelChangeInFlight = true;
    try {
      if (trimmed !== this.currentModel) {
        this.logger?.info(
          `applyModelChange: sessionId=${this.sessionId} ${JSON.stringify(this.currentModel)} → ${JSON.stringify(trimmed)}`,
        );
        this.currentModel = trimmed;
        for (const handler of this.modelHandlers) {
          try {
            handler(trimmed);
          } catch {
            void 0;
          }
        }
      }
      const update: Record<string, unknown> = {
        sessionUpdate: "current_model_update",
        currentModel: trimmed,
      };
      if (this.agentAdvertisedModels.length > 0) {
        update.availableModels = [...this.agentAdvertisedModels];
      }
      this.recordAndBroadcast("session/update", {
        sessionId: this.upstreamSessionId,
        update,
      });
      this.broadcastConfigOptions();
    } finally {
      this.modelChangeInFlight = false;
    }
  }

  // Apply a mode change initiated by a client request (session/set_mode)
  // when the agent doesn't emit a current_mode_update notification on its
  // own. Fires modeHandlers (persistence) and broadcasts a synthetic
  // current_mode_update so all attached clients — including the originator
  // — repaint immediately, mirroring applyModelChange. Without the
  // broadcast, peer clients (e.g. the TUI when set_mode was issued by Zed
  // through the shim) would stay on the prior mode.
  applyModeChange(modeId: string): void {
    const trimmed = modeId.trim();
    if (!trimmed) {
      return;
    }
    this.modeChangeInFlight = true;
    try {
      if (trimmed !== this.currentMode) {
        this.logger?.info(
          `applyModeChange: sessionId=${this.sessionId} ${JSON.stringify(this.currentMode)} → ${JSON.stringify(trimmed)}`,
        );
        this.currentMode = trimmed;
        for (const handler of this.modeHandlers) {
          try {
            handler(trimmed);
          } catch {
            void 0;
          }
        }
      }
      const update: Record<string, unknown> = {
        sessionUpdate: "current_mode_update",
        currentModeId: trimmed,
      };
      if (this.agentAdvertisedModes.length > 0) {
        update.availableModes = [...this.agentAdvertisedModes];
      }
      this.recordAndBroadcast("session/update", {
        sessionId: this.upstreamSessionId,
        update,
      });
      this.broadcastConfigOptions();
    } finally {
      this.modeChangeInFlight = false;
    }
  }

  // Assemble the spec-shaped configOptions snapshot for this session.
  // Order reflects the agent's preferred prominence: model and mode (the
  // dimensions users toggle constantly) first, then the hydra-native
  // `agent` selector. model/mode are included only when hydra actually
  // knows that dimension for the connected agent; `agent` is always
  // present since hydra owns the swap concept regardless of the backend.
  buildConfigOptions(): ConfigOption[] {
    const out: ConfigOption[] = [];
    if (this.agentAdvertisedModels.length > 0) {
      const options: ConfigOptionValue[] = this.agentAdvertisedModels.map(
        (m) => ({
          value: m.modelId,
          name: m.name ?? m.modelId,
          ...(m.description !== undefined ? { description: m.description } : {}),
        }),
      );
      const currentValue =
        this.currentModel && options.some((o) => o.value === this.currentModel)
          ? this.currentModel
          : options[0]!.value;
      out.push({
        id: "model",
        name: "Model",
        category: "model",
        type: "select",
        currentValue,
        options,
      });
    }
    if (this.agentAdvertisedModes.length > 0) {
      const options: ConfigOptionValue[] = this.agentAdvertisedModes.map(
        (m) => ({
          value: m.id,
          name: m.name ?? m.id,
          ...(m.description !== undefined ? { description: m.description } : {}),
        }),
      );
      const currentValue =
        this.currentMode && options.some((o) => o.value === this.currentMode)
          ? this.currentMode
          : options[0]!.value;
      out.push({
        id: "mode",
        name: "Session Mode",
        category: "mode",
        type: "select",
        currentValue,
        options,
      });
    }
    const agents = this.availableAgentsFn?.() ?? [];
    const agentOptions: ConfigOptionValue[] = agents.map((a) => ({
      value: a.id,
      name: a.name ?? a.id,
      ...(a.description !== undefined ? { description: a.description } : {}),
    }));
    // currentValue must be one of the listed options; inject the live
    // agent when the catalog snapshot hasn't loaded it (or is empty).
    if (!agentOptions.some((o) => o.value === this.agentId)) {
      agentOptions.unshift({ value: this.agentId, name: this.agentId });
    }
    out.push({
      id: "agent",
      name: "Agent",
      category: "_hydra_agent",
      type: "select",
      currentValue: this.agentId,
      options: agentOptions,
    });
    // Append extra config options advertised by the agent (e.g. effort).
    out.push(...this.agentAdvertisedConfigOptions);
    return out;
  }

  // Broadcast a config_option_update carrying the full snapshot. Fired
  // alongside the legacy current_mode_update / current_model_update and on
  // agent swaps so config-options-aware clients stay in sync via the
  // spec mechanism. config_option_update is a STATE_UPDATE_KIND, so this
  // broadcasts live but is not recorded to history.
  private broadcastConfigOptions(): void {
    this.recordAndBroadcast("session/update", {
      sessionId: this.upstreamSessionId,
      update: {
        sessionUpdate: "config_option_update",
        configOptions: this.buildConfigOptions(),
      },
    });
  }

  // Return a shallow clone of an agent-emitted config_option_update
  // envelope with the hydra-native `agent` option appended to its
  // configOptions (unless the agent already advertised one). Preserves
  // the agent's own options (mode/model/effort/…) and their order; the
  // `agent` selector rides last, matching its lower prominence. The
  // original envelope is not mutated.
  private mergeAgentOptionIntoEnvelope(envelope: unknown): unknown {
    if (!envelope || typeof envelope !== "object") {
      return envelope;
    }
    const env = envelope as { update?: unknown };
    if (!env.update || typeof env.update !== "object") {
      return envelope;
    }
    const update = env.update as {
      configOptions?: unknown;
      [k: string]: unknown;
    };
    const list = Array.isArray(update.configOptions)
      ? [...update.configOptions]
      : [];
    const hasAgent = list.some(
      (o) => o && typeof o === "object" && (o as { id?: unknown }).id === "agent",
    );
    if (hasAgent) {
      return envelope;
    }
    const agentOption = this.buildConfigOptions().find((o) => o.id === "agent");
    if (!agentOption) {
      return envelope;
    }
    return {
      ...env,
      update: { ...update, configOptions: [...list, agentOption] },
    };
  }

  onUsageChange(handler: (usage: UsageSnapshot) => void): void {
    this.usageHandlers.push(handler);
  }

  // Returns a freshly merged command list (hydra ∪ extension ∪ agent) for
  // callers that need a snapshot — notably acp-ws.ts's buildResponseMeta
  // when assembling the attach response. Order: built-in hydra verbs,
  // top-level daemon verbs (/model, /sessions, /help), extension-registered
  // entries, then whatever the agent advertised.
  mergedAvailableCommands(): AdvertisedCommand[] {
    // Clients (Zed, agent-shell, …) don't reliably handle multi-word
    // slash commands, so advertise bare verbs only. Sub-commands
    // (`/hydra kill`, `/model <id>`) are still accepted by the session
    // dispatcher — users just type the rest themselves.
    const out: AdvertisedCommand[] = this.daemonTopLevelCommands();
    const bareAliases = this.aliasableBareVerbs();
    // Auto-expose each /hydra <verb> as bare /verb where safe.
    for (const c of HYDRA_COMMANDS) {
      if (bareAliases.get(c.verb) !== "__hydra__") {
        continue;
      }
      const head = c.argsHint ? `${c.verb} ${c.argsHint}` : c.verb;
      out.push({
        name: head,
        description: `Alias for '/hydra ${c.verb}': ${c.description}`,
      });
    }
    if (this.extensionCommands) {
      for (const { name, command } of this.extensionCommands.list()) {
        // An empty verb means "advertise the bare `/hydra <name>`
        // form" — render with no trailing space.
        const head = command.verb ? `hydra ${name} ${command.verb}` : `hydra ${name}`;
        const display = command.argsHint ? `${head} ${command.argsHint}` : head;
        const entry: AdvertisedCommand = { name: display };
        if (command.description) {
          entry.description = command.description;
        }
        out.push(entry);
        // Convention: names starting with `hydra-acp-` are surfaced under
        // the elided short form too, matching the dispatch fallback in
        // handleSlashCommand. Both forms work; the short form is the
        // recommended UX, the long form is preserved for explicit usage
        // and backward compatibility.
        const short = name.startsWith("hydra-acp-") ? name.slice("hydra-acp-".length) : name;
        if (name.startsWith("hydra-acp-") && short.length > 0) {
          const shortHead = command.verb ? `hydra ${short} ${command.verb}` : `hydra ${short}`;
          const shortDisplay = command.argsHint
            ? `${shortHead} ${command.argsHint}`
            : shortHead;
          const shortEntry: AdvertisedCommand = { name: shortDisplay };
          if (command.description) {
            shortEntry.description = command.description;
          }
          out.push(shortEntry);
        }
        // Fully-bare `/short <verb>` form when the short name is safely
        // aliasable (no conflict with a reserved top-level slash command,
        // a /hydra built-in verb, or another extension).
        if (short.length > 0 && bareAliases.get(short) === name) {
          const bareHead = command.verb ? `${short} ${command.verb}` : short;
          const bareDisplay = command.argsHint ? `${bareHead} ${command.argsHint}` : bareHead;
          const bareEntry: AdvertisedCommand = { name: bareDisplay };
          if (command.description) {
            bareEntry.description = command.description;
          }
          out.push(bareEntry);
        }
      }
    }
    out.push(...this.agentAdvertisedCommands);
    return out;
  }

  // The daemon's own top-level slash commands — single source of truth
  // for both advertising (mergedAvailableCommands) and reserved-name
  // derivation (aliasableBareVerbs).
  private daemonTopLevelCommands(): AdvertisedCommand[] {
    return [
      { name: "hydra", description: "Hydra session command (kill, restart, title, agent <agent>)" },
      { name: "model", description: "Switch model; omit arg to list available models" },
      { name: "mode", description: "Switch mode; omit arg to list available modes" },
      { name: "sessions", description: "List all sessions" },
      { name: "help", description: "Show available commands" },
    ];
  }

  // Compute which bare `/verb` words can be safely auto-aliased to
  // `/hydra <verb>`. Value is "__hydra__" for a built-in hydra verb,
  // otherwise the extension process name that owns the alias. Reserved
  // bare verbs are derived (not hardcoded) from the daemon's own
  // top-level commands and whatever the underlying agent advertised —
  // aliasing never shadows something the client already recognizes.
  // Additional exclusions: hydra-vs-extension collisions (hydra wins)
  // and extension-vs-extension collisions (nobody wins — user must
  // type the long `/hydra <name>` form).
  private aliasableBareVerbs(): Map<string, string> {
    const reserved = new Set<string>();
    const firstWord = (name: string): string => name.split(/\s+/)[0] ?? "";
    for (const c of this.daemonTopLevelCommands()) {
      const w = firstWord(c.name);
      if (w) {
        reserved.add(w);
      }
    }
    for (const c of this.agentAdvertisedCommands) {
      // Agents may advertise with or without the leading slash; reserve
      // the bare form either way or the alias check silently misses.
      const raw = firstWord(c.name);
      const w = raw.startsWith("/") ? raw.slice(1) : raw;
      if (w) {
        reserved.add(w);
      }
    }
    const result = new Map<string, string>();
    for (const c of HYDRA_COMMANDS) {
      if (!reserved.has(c.verb)) {
        result.set(c.verb, "__hydra__");
      }
    }
    if (!this.extensionCommands) {
      return result;
    }
    const shortOwners = new Map<string, string | "__conflict__">();
    const seenExtNames = new Set<string>();
    for (const { name } of this.extensionCommands.list()) {
      if (seenExtNames.has(name)) {
        continue;
      }
      seenExtNames.add(name);
      const short = name.startsWith("hydra-acp-")
        ? name.slice("hydra-acp-".length)
        : name;
      if (!short || reserved.has(short) || result.has(short)) {
        continue;
      }
      const prev = shortOwners.get(short);
      if (prev === undefined) {
        shortOwners.set(short, name);
      } else if (prev !== name) {
        shortOwners.set(short, "__conflict__");
      }
    }
    for (const [short, owner] of shortOwners) {
      if (owner !== "__conflict__") {
        result.set(short, owner);
      }
    }
    return result;
  }

  // The agent's own advertised commands (not merged with hydra verbs).
  // Used by SessionManager to persist into meta.json so cold resurrect
  // can re-deliver via the attach response _meta.
  agentOnlyAdvertisedCommands(): AdvertisedCommand[] {
    return [...this.agentAdvertisedCommands];
  }

  // True when the agent advertised a slash command with this first word.
  // Accepts the word with or without its leading slash.
  private agentKnowsSlashCommand(word: string): boolean {
    const strip = (s: string): string => (s.startsWith("/") ? s.slice(1) : s);
    const bare = strip(word);
    if (!bare) {
      return false;
    }
    for (const c of this.agentAdvertisedCommands) {
      if (strip(c.name.split(/\s+/)[0] ?? "") === bare) {
        return true;
      }
    }
    return false;
  }

  // The agent's advertised modes list, for callers that need a snapshot.
  availableModes(): AdvertisedMode[] {
    return [...this.agentAdvertisedModes];
  }

  // The agent's advertised models list. Used by acp-ws.ts's dedicated
  // session/set_model handler to validate the requested modelId before
  // forwarding to the agent (catches cross-agent set_model storms from
  // clients that assume a different agent is on the other end). When
  // the agent never advertised any models, returns [] and the
  // set_model handler falls back to pass-through.
  availableModels(): AdvertisedModel[] {
    return [...this.agentAdvertisedModels];
  }

  // Pick up an agent-emitted session_info_update and store its title
  // as our canonical record. The notification is also forwarded to
  // clients via the surrounding recordAndBroadcast call. Authoritative
  // — overrides our placeholder.
  private maybeApplyAgentSessionInfo(params: unknown): void {
    const obj = (params ?? {}) as { update?: unknown };
    const update = (obj.update ?? {}) as {
      sessionUpdate?: unknown;
      title?: unknown;
    };
    if (update.sessionUpdate !== "session_info_update") {
      return;
    }
    if (typeof update.title !== "string") {
      return;
    }
    const trimmed = update.title.trim();
    if (!trimmed || trimmed === this.title) {
      return;
    }
    this.title = trimmed;
    this._firstPromptSeeded = true;
    for (const handler of this.titleHandlers) {
      try {
        handler(trimmed);
      } catch {
        void 0;
      }
    }
  }

  // Dispatch a /hydra <verb> [args] slash command typed in any client's
  // composer. Returns a synthesized session/prompt response so the
  // caller's promise resolves like a normal turn. To add a verb: append
  // an entry to HYDRA_COMMANDS (drives validation + client advertising)
  // and a dispatch case in the switch below.
  //
  // Extensions/transformers can also bind verbs via the
  // ExtensionCommandRegistry: "/hydra <process-name> <verb> [args]" routes
  // to that process's WS connection. Built-in hydra verbs win on name
  // collision so an extension can never shadow them.
  // Dispatch a /hydra <verb> [args] slash command. `messageId` is the
  // queue entry's id when called from runQueueEntry (so extensions can
  // correlate amends); undefined when called from out-of-band entry
  // points like the REST retitle API.
  private async handleSlashCommand(
    text: string,
    messageId?: string,
  ): Promise<unknown> {
    const rest = text.slice("/hydra".length).trim();
    const match = rest.match(/^(\S+)(?:\s+([\s\S]*))?$/);
    const first = match?.[1] ?? "";
    const remainder = (match?.[2] ?? "").trim();
    if (first === "") {
      // "/hydra" alone: no-op, return success so the user's
      // composer doesn't show an error.
      return { stopReason: "end_turn" };
    }
    // Dispatch directly to the inline variants when we're called
    // from runQueueEntry (messageId is set — the calling user-kind
    // entry already provides serialization). When called from
    // out-of-band paths (REST retitle, setAgent), messageId is
    // undefined and we wrap in enqueuePrompt to preserve ordering.
    const inline = messageId !== undefined;
    if (HYDRA_COMMANDS.some((c) => c.verb === first)) {
      switch (first) {
        case "title":
          return inline ? this.runTitleCommandInline(remainder) : this.runTitleCommand(remainder);
        case "agent":
          return inline ? this.runAgentCommandInline(remainder) : this.runAgentCommand(remainder);
        case "config":
          return this.handleConfigCommand(`/config ${remainder}`);
        case "kill":
          // Kill is intentionally not queued (see runKillCommand
          // comment) — fire directly in both paths.
          return this.runKillCommand();
        case "workspace":
          return this.runWorkspaceCommand(remainder);
        case "restart":
          return inline ? this.runRestartCommandInline() : this.runRestartCommand();
        case "compact":
          return inline ? this.runCompactCommandInline(remainder) : this.runCompactCommand(remainder);
        case "uncompact":
          return inline ? this.runUncompactCommandInline() : this.runUncompactCommand();
        case "fork":
          return inline
            ? this.runForkCommandInline(remainder, messageId)
            : this.runForkCommand(remainder);
        default: {
          const err = new Error(
            `no dispatcher for /hydra verb ${first}`,
          ) as Error & { code: number };
          err.code = JsonRpcErrorCodes.InternalError;
          throw err;
        }
      }
    }
    if (this.extensionCommands?.has(first)) {
      return inline
        ? this.runExtensionCommandInline(first, remainder, messageId)
        : this.runExtensionCommand(first, remainder);
    }
    // Convention: ecosystem packages are named `hydra-acp-<foo>`. Allow
    // the user to elide the prefix so `/hydra planner ...` routes the
    // same as `/hydra hydra-acp-planner ...`. Built-ins and exact-name
    // matches above still win — this is strictly the fallback.
    const eliprefixed = `hydra-acp-${first}`;
    if (this.extensionCommands?.has(eliprefixed)) {
      return inline
        ? this.runExtensionCommandInline(eliprefixed, remainder, messageId)
        : this.runExtensionCommand(eliprefixed, remainder);
    }
    const known = HYDRA_COMMANDS.map((c) => c.verb);
    if (this.extensionCommands) {
      const seen = new Set<string>();
      for (const { name } of this.extensionCommands.list()) {
        if (!seen.has(name)) {
          known.push(name);
          seen.add(name);
        }
      }
    }
    const err = new Error(
      `unknown /hydra verb: ${first} (known: ${known.join(", ")})`,
    ) as Error & { code: number };
    err.code = JsonRpcErrorCodes.InvalidParams;
    throw err;
  }

  // "/hydra <name> <verb> [args]" — name matches a registered extension
  // or transformer. We split the remainder into verb + args, validate the
  // verb against what the process advertised, and forward as a
  // hydra-acp/commands/invoke request on the process's WS connection.
  // The reply's text (if any) is broadcast as a synthetic
  // agent_message_chunk so it appears in the conversation alongside the
  // user's invocation.
  private runExtensionCommand(name: string, remainder: string): Promise<unknown> {
    return this.enqueuePrompt(() =>
      this.runExtensionCommandInline(name, remainder, undefined),
    );
  }

  // Inline core, callable from runQueueEntry where the calling entry
  // is already serialized by drainQueue. `messageId` is the user-kind
  // queue entry's id; we pass it through to commands/invoke so the
  // extension can correlate its in-flight dispatch with prompt-queue
  // events (amend, cancel) that target the same id.
  private async runExtensionCommandInline(
    name: string,
    remainder: string,
    messageId: string | undefined,
  ): Promise<unknown> {
    const entry = this.extensionCommands?.get(name);
    if (!entry) {
      return this.emitExtensionReply(
        `extension "${name}" is no longer connected`,
      );
    }
    const m = remainder.match(/^(\S+)(?:\s+([\s\S]*))?$/);
    const verb = m?.[1] ?? "";
    const args = (m?.[2] ?? "").trim();
    // The verb (possibly "") must be one the extension advertised.
    // An extension that registers a `""` verb opts into receiving
    // `/hydra <name>` with no following word; otherwise the user
    // gets the "unknown verb" error below.
    if (!entry.commands.some((c) => c.verb === verb)) {
      const verbs = entry.commands.map((c) => c.verb).join(", ");
      return this.emitExtensionReply(
        `/hydra ${name}${verb ? ` ${verb}` : ""}: unknown verb (known: ${verbs || "(none)"})`,
      );
    }
    const params: Record<string, unknown> = {
      sessionId: this.sessionId,
      verb,
      args,
    };
    if (messageId !== undefined) {
      params.messageId = messageId;
    }

    // Race the extension's commands/invoke against an externally-
    // triggered cancel signal so we can unstick the queue when an
    // entry is amended/cancelled mid-flight. The extension lives
    // outside the daemon's broadcast fanout (it's not an attached
    // client), so we need to fire it a dedicated notification AND
    // resolve the await internally — see cancelExtensionDispatch.
    let cancelResolve: (
      payload: { stopReason: "cancelled"; reason: "amended" | "cancelled" | "abandoned" },
    ) => void = () => undefined;
    const cancelPromise = new Promise<{
      stopReason: "cancelled";
      reason: "amended" | "cancelled" | "abandoned";
    }>((resolve) => {
      cancelResolve = resolve;
    });

    if (messageId !== undefined) {
      this.inFlightExtensionDispatches.set(messageId, {
        extensionName: name,
        connection: entry.connection,
        cancel: (reason) =>
          cancelResolve({ stopReason: "cancelled", reason }),
      });
    }

    let reply: unknown;
    let wasCancelled = false;
    try {
      const requestPromise = entry.connection.request(
        "hydra-acp/commands/invoke",
        params,
      );
      const result = await Promise.race([requestPromise, cancelPromise]);
      if (
        result &&
        typeof result === "object" &&
        (result as { stopReason?: unknown }).stopReason === "cancelled" &&
        "reason" in (result as Record<string, unknown>)
      ) {
        wasCancelled = true;
        this.logger?.info(
          `extension ${name} ${verb} cancelled (cancelExtensionDispatch); abandoning in-flight commands/invoke`,
        );
        return { stopReason: "cancelled" };
      }
      reply = result;
    } catch (err) {
      return this.emitExtensionReply(
        `${name} ${verb}: ${(err as Error).message}`,
      );
    } finally {
      if (messageId !== undefined && !wasCancelled) {
        this.inFlightExtensionDispatches.delete(messageId);
      }
    }
    const text =
      reply && typeof reply === "object" &&
      typeof (reply as { text?: unknown }).text === "string"
        ? ((reply as { text: string }).text)
        : "";
    if (text.length > 0) {
      return this.emitExtensionReply(text);
    }
    return { stopReason: "end_turn" };
  }

  // Trigger the cancel race for an in-flight extension dispatch keyed
  // by the user-prompt queue messageId. Fires the
  // `hydra-acp/commands/cancel` notification to the extension's
  // connection up front (so a fast extension can respond before the
  // race fallback fires) and resolves the internal cancel promise so
  // runExtensionCommandInline returns immediately with stopReason
  // "cancelled". Idempotent — multiple calls for the same messageId
  // (e.g. amend then cancel before the race settles) are no-ops
  // after the first.
  //
  // Called from amendOnHead (reason: "amended"), Session.cancel chain
  // walk for extension-bound currentEntry (reason: "cancelled"), and
  // markClosed teardown (reason: "abandoned").
  private cancelExtensionDispatch(
    messageId: string,
    reason: "amended" | "cancelled" | "abandoned",
  ): boolean {
    const dispatch = this.inFlightExtensionDispatches.get(messageId);
    if (!dispatch) {
      return false;
    }
    this.inFlightExtensionDispatches.delete(messageId);
    // Fire the notification synchronously so the extension can begin
    // its own cleanup; the cancel.resolve below is what unblocks
    // drainQueue. If the extension responds to commands/invoke
    // before the race resolves, that response is dropped because
    // wasCancelled is already true.
    try {
      dispatch.connection.notify("hydra-acp/commands/cancel", {
        sessionId: this.sessionId,
        messageId,
        reason,
      });
    } catch (err) {
      this.logger?.warn(
        `notify commands/cancel to ${dispatch.extensionName} failed: ${(err as Error).message}`,
      );
    }
    dispatch.cancel(reason);
    return true;
  }

  private emitExtensionReply(text: string): unknown {
    this.recordAndBroadcast("session/update", {
      sessionId: this.upstreamSessionId,
      update: {
        sessionUpdate: "agent_message_chunk",
        content: { type: "text", text: `\n${text}\n` },
        _meta: { "hydra-acp": { synthetic: true } },
      },
    });
    return { stopReason: "end_turn" };
  }

  private async handleSessionsCommand(): Promise<unknown> {
    let text: string;
    if (!this.listSessions) {
      text = "_(session listing not available)_";
    } else {
      const sessions = await this.listSessions();
      if (sessions.length === 0) {
        text = "_(no sessions)_";
      } else {
        const lines = sessions.map((s) => {
          const id = s.sessionId.replace(/^hydra_session_/, "").slice(0, 12);
          const model = s.currentModel ? ` · ${s.currentModel}` : "";
          const marker = s.sessionId === this.sessionId ? " ◀" : "";
          const title = s.title ? `  ${s.title}` : "";
          return `\`${id}\`  ${s.cwd}${model}${marker}${title}`;
        });
        text = `Sessions (${sessions.length}):\n${lines.join("\n")}`;
      }
    }
    this.recordAndBroadcast("session/update", {
      sessionId: this.upstreamSessionId,
      update: {
        sessionUpdate: "agent_message_chunk",
        content: { type: "text", text: `\n${text}\n` },
        _meta: { "hydra-acp": { synthetic: true } },
      },
    });
    return { stopReason: "end_turn" };
  }

  private handleHelpCommand(): Promise<unknown> {
    const commands = this.mergedAvailableCommands();
    const lines = commands.map((c) => {
      const desc = c.description ? `  ${c.description}` : "";
      return `\`/${c.name}\`${desc}`;
    });
    const text = lines.length > 0
      ? `Available commands:\n${lines.join("\n")}`
      : "_(no commands advertised)_";
    this.recordAndBroadcast("session/update", {
      sessionId: this.upstreamSessionId,
      update: {
        sessionUpdate: "agent_message_chunk",
        content: { type: "text", text: `\n${text}\n` },
        _meta: { "hydra-acp": { synthetic: true } },
      },
    });
    return Promise.resolve({ stopReason: "end_turn" });
  }

  private async handleModelCommand(text: string): Promise<unknown> {
    const arg = text.slice("/model".length).trim();
    if (arg === "") {
      const models = this.agentAdvertisedModels;
      const current = this.currentModel;
      let body: string;
      if (models.length === 0) {
        body = current ? `Current model: ${current}` : "_(no models advertised yet)_";
      } else {
        const inList = current ? models.some((m) => m.modelId === current) : true;
        const lines = models.map((m) => {
          const marker = m.modelId === current ? "▶ " : "  ";
          const desc = m.name && m.name !== m.modelId ? `  ${m.name}` : "";
          return `${marker}${m.modelId}${desc}`;
        });
        // Current model is valid but not in the advertised list (e.g. an
        // alias like "opus[1m]" that the agent normalizes to a canonical
        // id in its availableModels). Show it at the top so the user
        // can see what they're on.
        if (!inList && current) {
          lines.unshift(`▶ ${current}`);
        }
        body = lines.join("\n");
      }
      this.recordAndBroadcast("session/update", {
        sessionId: this.upstreamSessionId,
        update: {
          sessionUpdate: "agent_message_chunk",
          content: { type: "text", text: `\n${body}\n` },
          _meta: { "hydra-acp": { synthetic: true } },
        },
      });
      return { stopReason: "end_turn" };
    }
    // Resolve the requested id against the advertised list so a bare
    // "claude-opus-4-7" maps to the agent's "anthropic/claude-opus-4-7",
    // and an ambiguous/unknown id gets a friendly message instead of
    // silently corrupting the session.
    const resolution = resolveModelId(arg, this.agentAdvertisedModels);
    let modelId = arg;
    if (resolution.kind === "resolved") {
      modelId = resolution.modelId;
    } else if (resolution.kind === "ambiguous" || resolution.kind === "unknown") {
      // Narrow the "Available models" hint to substring matches of the
      // user's query so a quick `/model sonnet` doesn't dump the full
      // 70-row provider catalog. Fall back to the complete list only
      // when nothing contains the query (typo case).
      const allIds = this.agentAdvertisedModels.map((m) => m.modelId);
      const needle = arg.toLowerCase();
      const filtered =
        resolution.kind === "ambiguous"
          ? resolution.candidates
          : allIds.filter((id) => id.toLowerCase().includes(needle));
      const shown = filtered.length > 0 ? filtered : allIds;
      const reason =
        resolution.kind === "ambiguous"
          ? `"${arg}" matches multiple models: ${resolution.candidates.join(", ")}`
          : filtered.length > 0
            ? `"${arg}" is not an available model. Did you mean`
            : `"${arg}" is not an available model`;
      const heading =
        resolution.kind === "ambiguous" || filtered.length === 0
          ? "Available models"
          : "Matching models";
      this.recordAndBroadcast("session/update", {
        sessionId: this.upstreamSessionId,
        update: {
          sessionUpdate: "agent_message_chunk",
          content: { type: "text", text: `\n${reason}.\n${heading}:\n  ${shown.join("\n  ")}\n` },
          _meta: { "hydra-acp": { synthetic: true } },
        },
      });
      return { stopReason: "end_turn" };
    }
    await this.forwardModelChange(modelId);
    // Mirror the daemon's session/set_model WS handler (acp-ws.ts) —
    // update the cached currentModel and broadcast a synthetic
    // current_model_update. Some agents don't emit one themselves, so
    // without this the slash-command path silently leaves the session
    // pinned to the previous model.
    this.applyModelChange(modelId);
    return { stopReason: "end_turn" };
  }

  // /mode — the text-command twin of session/set_mode, so clients that
  // can only send prompts (e.g. Slack) can switch modes. With no arg it
  // lists advertised modes; with an arg it forwards session/set_mode to
  // the agent and then applies the change locally. The forward +
  // applyModeChange pair MUST stay identical to the daemon's
  // session/set_mode handler (see acp-ws.ts) — applyModeChange owns the
  // persistence + synthetic current_mode_update broadcast for both paths.
  private async handleModeCommand(text: string): Promise<unknown> {
    const arg = text.slice("/mode".length).trim();
    if (arg === "") {
      const modes = this.agentAdvertisedModes;
      const current = this.currentMode;
      let body: string;
      if (modes.length === 0) {
        body = current ? `Current mode: ${current}` : "_(no modes advertised yet)_";
      } else {
        const inList = current ? modes.some((m) => m.id === current) : true;
        const lines = modes.map((m) => {
          const marker = m.id === current ? "▶ " : "  ";
          const desc = m.name && m.name !== m.id ? `  ${m.name}` : "";
          return `${marker}${m.id}${desc}`;
        });
        // Current mode valid but not in the advertised list — surface it
        // at the top so the user can see what they're on.
        if (!inList && current) {
          lines.unshift(`▶ ${current}`);
        }
        body = lines.join("\n");
      }
      this.recordAndBroadcast("session/update", {
        sessionId: this.upstreamSessionId,
        update: {
          sessionUpdate: "agent_message_chunk",
          content: { type: "text", text: `\n${body}\n` },
          _meta: { "hydra-acp": { synthetic: true } },
        },
      });
      return { stopReason: "end_turn" };
    }
    // Validate against the advertised list when the agent supplied one,
    // so a fat-fingered id from Slack gets a helpful error instead of a
    // silent no-op. Pass-through when no modes were advertised.
    const modes = this.agentAdvertisedModes;
    if (modes.length > 0 && !modes.some((m) => m.id === arg)) {
      const known = modes.map((m) => m.id).join(", ");
      throw withCode(
        new Error(`unknown mode: ${arg} (known: ${known})`),
        JsonRpcErrorCodes.InvalidParams,
      );
    }
    await this.forwardRequest("session/set_mode", {
      sessionId: this.sessionId,
      modeId: arg,
    });
    this.applyModeChange(arg);
    return { stopReason: "end_turn" };
  }

  // /config — list or set an agent-advertised configOption. With no arg it
  // lists all options with their current values; with one arg it shows the
  // named option; with two args it validates and forwards
  // session/set_config_option to apply the change.
  private async handleConfigCommand(text: string): Promise<unknown> {
    const match = text.slice("/config".length).trim().match(/^(\S+)(?:\s+([\s\S]*))?$/);
    const id = match?.[1];
    const value = match?.[2] ?? "";

    if (!id) {
      // No arg: list all config options with current values marked.
      const options = this.buildConfigOptions();
      if (options.length === 0) {
        this.recordAndBroadcast("session/update", {
          sessionId: this.upstreamSessionId,
          update: {
            sessionUpdate: "agent_message_chunk",
            content: { type: "text", text: "\n_(no config options advertised yet)_\n" },
            _meta: { "hydra-acp": { synthetic: true } },
          },
        });
        return { stopReason: "end_turn" };
      }
      const blocks = options.map((o) => renderConfigOptionBlock(o));
      this.recordAndBroadcast("session/update", {
        sessionId: this.upstreamSessionId,
        update: {
          sessionUpdate: "agent_message_chunk",
          content: { type: "text", text: `\n${blocks.join("\n\n")}\n` },
          _meta: { "hydra-acp": { synthetic: true } },
        },
      });
      return { stopReason: "end_turn" };
    }

    // One arg (id): look up the option and display its current value + choices.
    const options = this.buildConfigOptions();
    const option = options.find((o) => o.id === id);
    if (!option) {
      const known = options.map((o) => o.id).join("\n  ");
      this.recordAndBroadcast("session/update", {
        sessionId: this.upstreamSessionId,
        update: {
          sessionUpdate: "agent_message_chunk",
          content: { type: "text", text: `\n"${id}" is not a known config option.\nAvailable options:\n  ${known}\n` },
          _meta: { "hydra-acp": { synthetic: true } },
        },
      });
      return { stopReason: "end_turn" };
    }

    if (!value) {
      // One arg: render just this option's block.
      this.recordAndBroadcast("session/update", {
        sessionId: this.upstreamSessionId,
        update: {
          sessionUpdate: "agent_message_chunk",
          content: {
            type: "text",
            text: `\n${renderConfigOptionBlock(option)}\n`,
          },
          _meta: { "hydra-acp": { synthetic: true } },
        },
      });
      return { stopReason: "end_turn" };
    }

    // Run the value through the same fuzzy resolver the /model slash
    // command uses, so `/hydra config model sonnet-4-6` resolves to
    // `ncp-anthropic/claude-sonnet-4-6` and `/hydra config agent codex`
    // matches `gpt-5-codex`. The trailing-segment tier degenerates to
    // case-insensitive equality for slash-free values (most config
    // options), which is a strict widening.
    const allValues = option.options.map((c) => c.value);
    const resolution = resolveCandidate(value, allValues);
    let resolvedValue = value;
    if (resolution.kind === "resolved") {
      resolvedValue = resolution.modelId;
    } else if (resolution.kind === "ambiguous" || resolution.kind === "unknown") {
      const needle = value.toLowerCase();
      const filtered =
        resolution.kind === "ambiguous"
          ? resolution.candidates
          : allValues.filter((v) => v.toLowerCase().includes(needle));
      const shown = filtered.length > 0 ? filtered : allValues;
      const reason =
        resolution.kind === "ambiguous"
          ? `"${value}" matches multiple values for "${id}": ${resolution.candidates.join(", ")}`
          : filtered.length > 0
            ? `"${value}" is not a valid value for "${id}". Did you mean`
            : `"${value}" is not a valid value for "${id}"`;
      const heading =
        resolution.kind === "ambiguous" || filtered.length === 0
          ? "Valid values"
          : "Matching values";
      this.recordAndBroadcast("session/update", {
        sessionId: this.upstreamSessionId,
        update: {
          sessionUpdate: "agent_message_chunk",
          content: { type: "text", text: `\n${reason}.\n${heading}:\n  ${shown.join("\n  ")}\n` },
          _meta: { "hydra-acp": { synthetic: true } },
        },
      });
      return { stopReason: "end_turn" };
    }

    // hydra synthesizes three config ids that the underlying agent
    // doesn't understand: `model`, `mode`, `agent`. The daemon's WS twin
    // (acp-ws.ts handleSetConfigOption) special-cases them to dispatch
    // to session/set_model / session/set_mode / agent swap respectively.
    // The text path must do the same — a raw upstream
    // session/set_config_option for configId=model is silently ignored
    // by the agent, which is why `/hydra config model opus-4-7`
    // appeared to no-op.
    if (id === "model") {
      if (resolvedValue !== this.currentModel) {
        await this.forwardModelChange(resolvedValue);
      }
      this.applyModelChange(resolvedValue);
      return { stopReason: "end_turn" };
    }
    if (id === "mode") {
      if (resolvedValue !== this.currentMode) {
        await this.forwardRequest("session/set_mode", {
          sessionId: this.sessionId,
          modeId: resolvedValue,
        });
      }
      this.applyModeChange(resolvedValue);
      return { stopReason: "end_turn" };
    }
    if (id === "agent") {
      if (resolvedValue !== this.agentId) {
        await this.runAgentCommandInline(resolvedValue);
      }
      return { stopReason: "end_turn" };
    }
    await this.forwardRequest("session/set_config_option", {
      sessionId: this.sessionId,
      configId: id,
      value: resolvedValue,
    });
    return { stopReason: "end_turn" };
  }

  // /hydra title. With an arg, sets the title directly (synchronous,
  // broadcasts session_info_update). Without an arg, asks the manager
  // to schedule a background synopsis via the ephemeral-agent path —
  // returns end_turn immediately; the new title (and synopsis) land on
  // the cold record asynchronously.
  private runTitleCommand(arg: string): Promise<unknown> {
    return this.enqueuePrompt(() => this.runTitleCommandInline(arg));
  }

  // Inline core for /hydra title — dispatchable directly from
  // runQueueEntry without an extra enqueuePrompt wrap (the calling
  // entry is already serialized by drainQueue).
  private async runTitleCommandInline(arg: string): Promise<unknown> {
    if (arg) {
      this.setTitle(arg);
      return { stopReason: "end_turn" };
    }
    this.scheduleSynopsisHook?.();
    return { stopReason: "end_turn" };
  }

  // Send a prompt to the underlying agent and capture its reply chunks
  // privately (no fan-out to clients, no recording into history). Used
  // by /hydra agent's transcript-injection path. Returns the joined
  // agent_message_chunk text.
  private async runInternalPrompt(text: string): Promise<string> {
    if (this.internalPromptCapture) {
      throw new Error("internal prompt already in flight");
    }
    const capture = {
      chunks: [] as string[],
      toolCalls: 0,
      thinkingChars: 0,
      messageChars: 0,
    };
    this.internalPromptCapture = capture;
    try {
      await this.agent.connection.request<unknown>("session/prompt", {
        sessionId: this.upstreamSessionId,
        prompt: [{ type: "text", text }],
      });
      return capture.chunks.join("");
    } finally {
      this.internalPromptCapture = undefined;
    }
  }

  // Schedule an agent switch via the compaction coordinator. The
  // coordinator generates a synthesis artifact in the target agent's
  // idiom, then swaps on the next idle edge (mirroring /hydra compact).
  // Returns end_turn immediately with a synthetic banner — the actual
  // process swap lands asynchronously when the synthesis completes and
  // the session quiesces.
  //
  // Public entry for swapping the underlying agent from a client request
  // (session/set_config_option with configId "agent"), the protocol twin
  // of the `/hydra agent` text command. Both routes funnel through the
  // same scheduler so behavior is identical regardless of trigger.
  setAgent(newAgentId: string): Promise<unknown> {
    return this.runAgentCommand(newAgentId);
  }

  private runAgentCommand(newAgentId: string): Promise<unknown> {
    return this.enqueuePrompt(() => this.runAgentCommandInline(newAgentId));
  }

  private async runAgentCommandInline(arg: string): Promise<unknown> {
    if (arg === "status") {
      return this.runAgentStatusCommandInline();
    }
    const rawAgentId = arg;
    if (!rawAgentId) {
      throw withCode(
        new Error("/hydra agent requires an agent id"),
        JsonRpcErrorCodes.InvalidParams,
      );
    }
    // Canonicalize (e.g. "claude" -> "claude-acp") so `/hydra agent`
    // accepts the same fuzzy shorthands `--agent` does. Unknown ids
    // fall through unchanged so bootstrapAgent surfaces the usual
    // AgentNotInstalled error downstream.
    const resolved = this.resolveAgentIdHook
      ? await this.resolveAgentIdHook(rawAgentId)
      : undefined;
    const newAgentId = resolved ?? rawAgentId;
    if (newAgentId === this.agentId) {
      throw withCode(
        new Error(`already on agent ${newAgentId}`),
        JsonRpcErrorCodes.InvalidParams,
      );
    }
    if (!this.scheduleCompactionHook) {
      this.emitExtensionReply(
        "agent switching not configured for this session",
      );
      return { stopReason: "end_turn" };
    }
    this.scheduleCompactionHook({ targetAgentId: newAgentId });
    this.emitExtensionReply(
      `Agent switch to ${newAgentId} scheduled. The session will rotate to ${newAgentId} once synthesis completes.`,
    );
    return { stopReason: "end_turn" };
  }

  private async runAgentStatusCommandInline(): Promise<unknown> {
    const target = await this.getPendingAgentSwapHook?.();
    if (!target) {
      this.emitExtensionReply("No agent switch pending.");
      return { stopReason: "end_turn" };
    }
    this.emitExtensionReply(
      `Agent switch to ${target} pending — will rotate on the next idle edge.`,
    );
    return { stopReason: "end_turn" };
  }

  // Close this session in-place. Bypasses enqueuePrompt deliberately so a
  // mid-turn /hydra kill takes effect immediately — agent.kill() will tear
  // down any in-flight request as a side effect. The record is kept
  // (deleteRecord:false) so the session goes cold and can be resurrected.
  // Returns end_turn so the prompt() caller's response resolves normally,
  // but every attached client has already received hydra-acp/session/closed
  // by the time this returns.
  private async runKillCommand(): Promise<unknown> {
    // Agent dies immediately. The cold record's synopsis is regenerated
    // out-of-band by the synopsis coordinator (scheduled via the
    // SessionManager onClose hook) — no LLM call blocks the kill.
    await this.close({ deleteRecord: false });
    return { stopReason: "end_turn" };
  }

  // Restart the underlying agent with a fresh session/new, preserving the
  // conversation history. Unlike /hydra agent, this allows the same agentId
  // — useful when the proxy has changed available models (e.g. opus became
  // available after a quota reset) and the resumed session is locked to a
  // stale model list.
  private runRestartCommand(): Promise<unknown> {
    return this.enqueuePrompt(() => this.runRestartCommandInline());
  }

  private async runRestartCommandInline(): Promise<unknown> {
    if (!this.spawnReplacementAgent) {
      throw withCode(
        new Error("agent restart not configured for this session"),
        JsonRpcErrorCodes.InternalError,
      );
    }
    // Queued: waits for any in-flight turn to finish naturally, then
    // respawns. Use forceCancel() to abort a stuck turn immediately.
    await this.respawnAgent();
    return { stopReason: "end_turn" };
  }

  // "/hydra compact" — schedules a synopsis-based compaction job and
  // emits a synthetic confirmation. The actual compaction (summarization
  // + upstream swap) runs asynchronously via the coordinator; this
  // method returns end_turn immediately.
  private runCompactCommand(arg?: string): Promise<unknown> {
    return this.enqueuePrompt(() => this.runCompactCommandInline(arg));
  }

  private async runCompactCommandInline(arg?: string): Promise<unknown> {
    if (arg === "status") {
      return this.runCompactStatusCommandInline();
    }
    if (!this.scheduleCompactionHook) {
      this.emitExtensionReply(
        "compaction scheduling not configured for this session",
      );
      return { stopReason: "end_turn" };
    }
    this.scheduleCompactionHook();
    this.emitExtensionReply(
      "Compaction scheduled. The session will rotate to a fresh upstream once summarization completes.",
    );
    return { stopReason: "end_turn" };
  }

  private async runCompactStatusCommandInline(): Promise<unknown> {
    const state = await this.getCompactionStateHook?.();
    const summarized = this._summarizedThroughEntry;
    if (state == null && summarized == null) {
      this.emitExtensionReply("This session has never been compacted.");
      return { stopReason: "end_turn" };
    }
    if (state == null) {
      this.emitExtensionReply(
        `No compaction in progress. Last summarized through entry: ${summarized}`,
      );
      return { stopReason: "end_turn" };
    }
    const lines: string[] = [
      `Compaction state: ${state.status}${state.iter != null ? ` (iteration ${state.iter})` : ""}`,
      `Summarized through entry: ${summarized ?? 0}`,
      `Pending attempts: ${state.attempts ?? 0}`,
    ];
    this.emitExtensionReply(lines.join("\n"));
    return { stopReason: "end_turn" };
  }

  private runUncompactCommand(): Promise<unknown> {
    return this.enqueuePrompt(() => this.runUncompactCommandInline());
  }

  /**
   * `/hydra workspace <verb>`.
   *
   * Parsing lives here; the work lives on SessionManager behind
   * workspaceHook, because it needs the provider registry, the record
   * store, and history length — none of which Session should know
   * about. Same split as forkHook and uncompactHook.
   */
  private async runWorkspaceCommand(remainder: string): Promise<unknown> {
    if (!this.workspaceHook) {
      this.emitExtensionReply(
        "Workspaces are not available on this session (no workspace hook configured).",
      );
      return { stopReason: "end_turn" };
    }
    const [verb = "status", ...rest] = remainder.split(/\s+/).filter((s) => s.length > 0);
    if (!(WORKSPACE_VERBS as readonly string[]).includes(verb)) {
      this.emitExtensionReply(
        `Unknown workspace verb "${verb}". Use one of: ${WORKSPACE_VERBS.join(", ")}.`,
      );
      return { stopReason: "end_turn" };
    }
    // Flags split out of the name rather than parsed positionally, because
    // a label is free-form and may legitimately be several words. An
    // unrecognized `--flag` is REFUSED rather than folded into the label:
    // silently naming a workspace "--clen" is how a typo turns a
    // deliberate choice into its opposite with a plausible-looking reply.
    const flags = rest.filter((token) => token.startsWith("--"));
    const unknown = flags.filter((f) => f !== "--clean" && f !== "--deep");
    if (unknown.length > 0) {
      this.emitExtensionReply(
        `Unknown workspace flag(s) ${unknown.join(", ")}. Supported: --clean (start), --deep (clean).`,
      );
      return { stopReason: "end_turn" };
    }
    const opts = {
      clean: flags.includes("--clean"),
      deep: flags.includes("--deep"),
    };
    // Refused rather than ignored, for the same reason: a flag that reads
    // as accepted and does nothing is worse than one that is rejected.
    if (opts.clean && verb !== "start") {
      this.emitExtensionReply(`--clean applies to \`start\`, not to \`${verb}\`.`);
      return { stopReason: "end_turn" };
    }
    if (opts.deep && verb !== "clean") {
      this.emitExtensionReply(`--deep applies to \`clean\`, not to \`${verb}\`.`);
      return { stopReason: "end_turn" };
    }
    const name = rest
      .filter((token) => !token.startsWith("--"))
      .join(" ")
      .trim();
    try {
      const message = await this.workspaceHook(
        verb as WorkspaceVerb,
        name.length > 0 ? name : undefined,
        opts,
      );
      this.emitExtensionReply(message);
    } catch (err) {
      this.emitExtensionReply(
        `Workspace ${verb} failed: ${err instanceof Error ? err.message : String(err)}`,
      );
    }
    return { stopReason: "end_turn" };
  }

  private async runUncompactCommandInline(): Promise<unknown> {
    if (!this.uncompactHook) {
      this.emitExtensionReply(
        "Rollback not available: uncompact hook not configured for this session.",
      );
      return { stopReason: "end_turn" };
    }
    try {
      await this.uncompactHook();
      this.emitExtensionReply(
        "Rolled back to pre-compaction upstream. The session is now using the previous agent context.",
      );
    } catch (err) {
      this.emitExtensionReply(
        `Rollback failed: ${err instanceof Error ? err.message : String(err)}`,
      );
    }
    return { stopReason: "end_turn" };
  }

  // "/hydra fork [verbatim]" — fork the current conversation into a new
  // session. Default mode is synthesis (full history + generated brief);
  // pass "verbatim" to slice at the last completed turn instead. Runs
  // out of the prompt queue so it doesn't fight in-flight turns.
  private runForkCommand(arg?: string): Promise<unknown> {
    return this.enqueuePrompt(() => this.runForkCommandInline(arg, undefined));
  }

  // Walk the persisted history and return the messageId of the last
  // session/update entry whose messageId != `target` and that appears
  // before `target`. Returns undefined when there is no such entry
  // (target is the first, or history load fails).
  private async findMessageIdBefore(target: string): Promise<string | undefined> {
    if (!this.historyStore) {
      return undefined;
    }
    const entries = await this.historyStore.load(this.sessionId);
    let last: string | undefined;
    for (const entry of entries) {
      if (entry.method !== "session/update") {
        continue;
      }
      const params = entry.params as { update?: { messageId?: unknown } } | undefined;
      const id = params?.update?.messageId;
      if (typeof id !== "string") {
        continue;
      }
      if (id === target) {
        return last;
      }
      last = id;
    }
    return undefined;
  }

  private async runForkCommandInline(
    arg: string | undefined,
    messageId: string | undefined,
  ): Promise<unknown> {
    if (!this.forkHook) {
      this.emitExtensionReply("Fork not configured for this session.");
      return { stopReason: "end_turn" };
    }
    const trimmed = (arg ?? "").trim();
    let mode: "verbatim" | "synthesis" | undefined;
    if (trimmed === "verbatim") {
      mode = "verbatim";
    } else if (trimmed === "synthesis" || trimmed === "") {
      mode = undefined;
    } else {
      this.emitExtensionReply(
        `Unknown fork argument: \`${trimmed}\`. Use \`/hydra fork\` or \`/hydra fork verbatim\`.`,
      );
      return { stopReason: "end_turn" };
    }
    try {
      const forkOpts: {
        mode?: "verbatim" | "synthesis";
        forkAt?: string;
      } = {};
      if (mode) {
        forkOpts.mode = mode;
      }
      // Anchor the fork just before the /hydra fork trigger turn so the
      // in-flight command doesn't render as a phantom open turn in the
      // new session. Walk history for the last session/update messageId
      // that precedes ours; if there isn't one (fork issued as the very
      // first prompt), let forkSession fall back to its default anchor.
      if (messageId && this.historyStore) {
        const prev = await this.findMessageIdBefore(messageId).catch(() => undefined);
        if (prev) {
          forkOpts.forkAt = prev;
        }
      }
      const r = await this.forkHook(
        Object.keys(forkOpts).length > 0 ? forkOpts : undefined,
      );
      const shortId = r.sessionId.replace(/^hydra_session_/, "");
      this.emitExtensionReply(
        `Forked to [\`${shortId}\`](hydra://sessions/${shortId}).`,
      );
    } catch (err) {
      this.emitExtensionReply(
        `Fork failed: ${err instanceof Error ? err.message : String(err)}`,
      );
    }
    return { stopReason: "end_turn" };
  }

  // Last-resort cancellation. When an agent ignores session/cancel (current
  // opencode returns UnsupportedOperation and keeps generating), the only
  // way to actually stop the turn is to tear the subprocess down. Rather
  // than respawn + replay the transcript (slow, and renders as an agent
  // "switch"), we close the session keeping its record: agent.kill() aborts
  // the in-flight turn, and the next prompt auto-resurrects via session/load
  // (cheap — the agent restores its own context). The forceCancelling flag
  // makes runQueueEntry render the aborted turn as "cancelled" rather than a
  // raw connection error. Runs OUTSIDE the prompt queue so a wedged turn
  // can't block it.
  async forceCancel(): Promise<{ stopReason: string }> {
    if (this.closed || this.closing) {
      throw withCode(
        new Error("session is closing"),
        JsonRpcErrorCodes.SessionClosing,
      );
    }
    this.lastCancelAt = 0;
    this.forceCancelling = true;
    await this.close({ deleteRecord: false });
    return { stopReason: "cancelled" };
  }

  // Shared kill-and-respawn used by /hydra restart (queued) and forceCancel
  // (immediate). Spawns a fresh agent, swaps it in, kills the old one, and
  // re-seeds the conversation transcript so the new process has context.
  private async respawnAgent(): Promise<void> {
    const spawnAgent = this.spawnReplacementAgent!;
    const agentId = this.agentId;
    const transcript = await this.buildSwitchTranscript(agentId);

    const fresh = await spawnAgent({
      agentId,
      cwd: this.cwd,
      agentArgs: this.agentArgs,
      ...(this.forwardedEnv ? { forwardedEnv: this.forwardedEnv } : {}),
    });
    this.accumulateAndResetCost();
    this.wireAgent(fresh.agent);

    const oldAgent = this.agent;
    this.agent = fresh.agent;
    this.upstreamSessionId = fresh.upstreamSessionId;
    this.agentMeta = fresh.agentMeta;
    this.agentCapabilities = fresh.agentCapabilities;
    this.resetModelVerb(fresh.modelVerb);
    this.agentAdvertisedCommands = [];
    this.broadcastMergedCommands();
    // Re-advertise the restarted agent's models/modes from its session/new
    // response (see runAgentCommand) so clients' dropdowns repopulate even
    // when the agent doesn't emit a follow-up current_model_update.
    this.currentModel = fresh.initialModel;
    this.currentMode = fresh.initialMode;
    this.setAgentAdvertisedModels(fresh.initialModels ?? []);
    this.setAgentAdvertisedModes(fresh.initialModes ?? []);
    // Killing the old agent rejects any in-flight session/prompt bound to
    // its (already-captured) connection — that's how a stuck turn ends.
    await oldAgent.kill().catch(() => undefined);

    if (transcript) {
      await this.runInternalPrompt(transcript).catch(() => undefined);
    }

    this.broadcastAgentSwitch(agentId, agentId);

    const info = { agentId, upstreamSessionId: this.upstreamSessionId };
    for (const handler of this.agentChangeHandlers) {
      try {
        handler(info);
      } catch {
        void 0;
      }
    }
  }

  // Walk the persisted history and produce a labeled transcript suitable
  // for handing to a fresh agent. Includes user prompts, agent replies,
  // and tool-call outcomes; skips hydra-synthesized markers (so multi-hop
  // switches don't accumulate banners) and other update kinds we don't
  // think the next agent benefits from re-seeing (plans, thoughts,
  // mode/model/usage).
  //
  // The header text defaults to the agent-swap framing; callers like
  // seedFromImport pass a custom header when the new agent is taking
  // over an imported session rather than swapping mid-conversation.
  private async buildSwitchTranscript(
    prevAgentId: string,
    headerOverride?: { intro: string; followup: string },
  ): Promise<string> {
    const lines: Array<{ speaker: string; text: string }> = [];
    const history = await this.getHistorySnapshot();
    for (const note of history) {
      if (note.method !== "session/update") {
        continue;
      }
      const params = (note.params ?? {}) as { update?: Record<string, unknown> };
      const update = params.update;
      if (!update) {
        continue;
      }
      const meta = update._meta as
        | { "hydra-acp"?: { synthetic?: boolean } }
        | undefined;
      if (meta?.["hydra-acp"]?.synthetic) {
        continue;
      }
      const kind = update.sessionUpdate as string | undefined;
      if (kind === "prompt_received") {
        const text = extractPromptText(update.prompt);
        if (text) {
          lines.push({ speaker: "user", text });
        }
      } else if (kind === "agent_message_chunk") {
        const content = update.content as { text?: string } | undefined;
        const text = content?.text;
        if (text) {
          lines.push({ speaker: `agent: ${prevAgentId}`, text });
        }
      } else if (kind === "tool_call" || kind === "tool_call_update") {
        const status = update.status as string | undefined;
        const title = update.title as string | undefined;
        if (status === "completed" || status === "failed") {
          lines.push({
            speaker: "tool",
            text: `${title ?? "?"} ${status}`,
          });
        }
      }
    }
    if (lines.length === 0) {
      return "";
    }
    // Coalesce consecutive same-speaker entries (chunks → paragraph).
    const coalesced: string[] = [];
    let current: { speaker: string; text: string } | undefined;
    for (const line of lines) {
      if (current && current.speaker === line.speaker) {
        current.text += line.text;
      } else {
        if (current) {
          coalesced.push(`<${current.speaker}>: ${current.text.trim()}`);
        }
        current = { speaker: line.speaker, text: line.text };
      }
    }
    if (current) {
      coalesced.push(`<${current.speaker}>: ${current.text.trim()}`);
    }
    const intro =
      headerOverride?.intro ??
      `You are taking over this conversation from ${prevAgentId}. Below is the transcript so far.`;
    const followup =
      headerOverride?.followup ??
      `Each line is prefixed with its speaker. Continue from where ${prevAgentId} left off, responding to the user's most recent message.`;
    return [
      intro,
      followup,
      "",
      "--- begin transcript ---",
      ...coalesced,
      "--- end transcript ---",
    ].join("\n");
  }

  // Replay the persisted history into a freshly-spawned agent so an
  // imported session has context. Called by SessionManager.doResurrect
  // on the first wake-up of a session whose meta.json has an empty
  // upstreamSessionId (the import marker). Wrapped in enqueuePrompt so
  // any user prompts arriving mid-seed queue behind it (mirrors the
  // /hydra agent path so the agent isn't asked to respond to a user
  // turn before it has absorbed the imported transcript). Best-effort:
  // if the agent fails to absorb the transcript we still leave the
  // session usable — the user just continues without context.
  async seedFromImport(): Promise<void> {
    await this.enqueuePrompt(async () => {
      const transcript = await this.buildSwitchTranscript(this.agentId, {
        intro:
          "You are continuing a conversation that was imported from another hydra. Below is the transcript so far.",
        followup:
          "Each line is prefixed with its speaker. Treat this as context for the next user message; do not re-respond to earlier turns.",
      });
      if (!transcript) {
        return undefined;
      }
      await this.runInternalPrompt(transcript).catch(() => undefined);
      return undefined;
    });
  }

  // Seed a forked session's fresh agent with a compaction-style brief:
  // [synopsis header if present] + recent turns verbatim. Called on first
  // attach when the session has forkedFromSessionId set. `synopsis` is
  // optional — fork/btw paths pass the parent's synopsis when one exists
  // (orientation), and omit it otherwise; renderCompactionSeed then emits
  // title + recent turns only, with a closing note pointing at recall. The
  // seed is sent via internalPromptCapture so neither the seed prompt nor
  // the agent's acknowledgement lands in history.jsonl. Safe with empty
  // history (tail degrades to nothing).
  async seedFromFork(synopsis?: SessionSynopsis): Promise<void> {
    await this.enqueuePrompt(async () => {
      const title = this.title ?? "(untitled)";

      let historyEntries: Array<{ method: string; params: unknown }> = [];
      if (this.historyStore) {
        try {
          historyEntries = await this.historyStore.load(this.sessionId);
        } catch (err) {
          this.logger?.warn(`seedFromFork: historyStore.load failed: ${(err as Error).message}`);
        }
      }

      // Pass the FULL history — renderCompactionSeed turn-extracts and keeps
      // the last TAIL_K *turns*. Pre-slicing to the last TAIL_K *entries*
      // here starved the extractor of a prompt_received boundary whenever the
      // tail landed mid-agent-turn, yielding an empty tail (synopsis-only
      // seed). Mirrors swapUpstream's compaction path.
      const seedText = renderCompactionSeed({
        synopsis,
        title,
        tail: historyEntries,
        tailK: TAIL_K,
        // Continuity floor — fork/btw always want a few recent turns
        // verbatim even when the synopsis (if present) covers
        // everything up to fork time. Capped by TAIL_K.
        tailFloor: FORK_TAIL_FLOOR,
        // Anchor against this fork's own watermark. For verbatim/btw
        // forks this is the sliced-history length (stamped at fork
        // time); for synthesis forks it's the source length. Either
        // way, post-watermark = 0, so the floor drives the tail and
        // any in-flight open turn from a mid-turn /btw renders in its
        // own section.
        watermark: this._summarizedThroughEntry,
        recallArmed: (this._summarizedThroughEntry ?? 0) > 0,
      });

      if (this.internalPromptCapture) {
        throw new Error("seedFromFork: internal prompt already in flight");
      }
      this.internalPromptCapture = {
        chunks: [],
        toolCalls: 0,
        thinkingChars: 0,
        messageChars: 0,
      };
      try {
        await this.agent.connection.request<unknown>("session/prompt", {
          sessionId: this.upstreamSessionId,
          prompt: [{ type: "text", text: seedText }],
        });
        const cap = this.internalPromptCapture;
        this.logger?.info(
          `seedFromFork: seed processed sessionId=${this.sessionId} seedChars=${seedText.length} toolCalls=${cap.toolCalls} thinkingChars=${cap.thinkingChars} messageChars=${cap.messageChars}`,
        );
      } finally {
        this.internalPromptCapture = undefined;
      }

      return undefined;
    });
  }

  // Tell every attached client the agent identity has changed via
  // session_info_update carrying agentId inside _meta["hydra-acp"] —
  // the ACP schema for session_info_update is just title/updatedAt/_meta,
  // so non-hydra clients harmlessly ignore the extension; hydra-aware
  // ones read it and relabel. synthetic=true so a future /hydra agent's
  // transcript builder filters it out.
  private broadcastAgentSwitch(_oldAgentId: string, newAgentId: string): void {
    this.recordAndBroadcast("session/update", {
      sessionId: this.sessionId,
      update: {
        sessionUpdate: "session_info_update",
        _meta: { "hydra-acp": { synthetic: true, agentId: newAgentId, pendingAgentSwap: null } },
      },
    });
    this.broadcastConfigOptions();
  }

  // Push a session_info_update carrying pendingAgentSwap so the TUI
  // can show "switching to X" in the session bar during a /hydra agent
  // synthesis run. Pass null to clear (e.g. on synthesis failure).
  broadcastPendingAgentSwap(targetAgentId: string | null): void {
    this.recordAndBroadcast("session/update", {
      sessionId: this.sessionId,
      update: {
        sessionUpdate: "session_info_update",
        _meta: { "hydra-acp": { synthetic: true, pendingAgentSwap: targetAgentId } },
      },
    });
  }

  // stdin-stream lifecycle. Cat --stream calls openStream() once after
  // session/new, then forwards stdin chunks via streamWrite(). The agent
  // either consumes via the file path (when shell tools are available)
  // or — once the MCP surface lands — via tool calls that route through
  // streamRead() / streamTail() / streamHead() / streamWaitFor().
  hasStreamBuffer(): boolean {
    return this.streamBuffer !== undefined;
  }

  get streamPath(): string | undefined {
    return this.streamFilePath;
  }

  openStream(opts: {
    mode?: "memory" | "file";
    capacityBytes?: number;
    fileCapBytes?: number;
    filePathFor?: (sessionId: string) => string;
  }): { filePath?: string; capacityBytes: number; fileCapBytes?: number } {
    if (this.streamBuffer !== undefined) {
      throw new Error(
        `stream buffer already open for session ${this.sessionId}`,
      );
    }
    const mode = opts.mode ?? "memory";
    const filePath =
      mode === "file" && opts.filePathFor !== undefined
        ? opts.filePathFor(this.sessionId)
        : undefined;
    const bufferOpts: ConstructorParameters<typeof SessionStreamBuffer>[0] = {};
    if (opts.capacityBytes !== undefined) {
      bufferOpts.capacityBytes = opts.capacityBytes;
    }
    if (filePath !== undefined) {
      bufferOpts.filePath = filePath;
    }
    if (opts.fileCapBytes !== undefined) {
      bufferOpts.fileCapBytes = opts.fileCapBytes;
    }
    bufferOpts.onFileCapReached = () => {
      // Notify any attached client so the agent's UI / cat's caller can
      // surface the truncation. The fact that the cap was hit is a
      // recordable event — it changes how the agent should interpret
      // subsequent reads of the file projection.
      this.recordAndBroadcast("session/update", {
        sessionId: this.upstreamSessionId,
        update: {
          sessionUpdate: "stream_truncated",
          ...(filePath !== undefined ? { filePath } : {}),
          fileCapBytes: opts.fileCapBytes,
        },
      });
    };
    const buf = new SessionStreamBuffer(bufferOpts);
    this.streamBuffer = buf;
    this.streamFilePath = filePath;
    const result: { filePath?: string; capacityBytes: number; fileCapBytes?: number } = {
      capacityBytes: buf.capacity,
    };
    if (filePath !== undefined) {
      result.filePath = filePath;
    }
    if (opts.fileCapBytes !== undefined) {
      result.fileCapBytes = opts.fileCapBytes;
    }
    return result;
  }

  streamWrite(chunkB64: string, eof?: boolean): { writeCursor: number } {
    const buf = this.requireStreamBuffer();
    if (chunkB64.length > 0) {
      const chunk = Buffer.from(chunkB64, "base64");
      buf.append(chunk);
    }
    if (eof === true) {
      buf.close();
    }
    return { writeCursor: buf.writeCursorPos };
  }

  async streamRead(
    cursor: number,
    maxBytes: number | undefined,
    waitMs: number | undefined,
  ): Promise<{
    bytes: string;
    nextCursor: number;
    gap?: number;
    eof?: boolean;
  }> {
    const buf = this.requireStreamBuffer();
    const cap = Math.max(
      0,
      Math.min(maxBytes ?? STREAM_READ_MAX_BYTES, STREAM_READ_MAX_BYTES),
    );
    let r: RawStreamReadResult = buf.read(cursor, cap);
    if (
      r.bytes.length === 0 &&
      r.eof !== true &&
      waitMs !== undefined &&
      waitMs > 0
    ) {
      const outcome = await buf.waitForData(r.nextCursor, waitMs);
      if (outcome === "data" || outcome === "eof") {
        r = buf.read(r.nextCursor, cap);
      }
    }
    const out: {
      bytes: string;
      nextCursor: number;
      gap?: number;
      eof?: boolean;
    } = {
      bytes: r.bytes.toString("base64"),
      nextCursor: r.nextCursor,
    };
    if (r.gap !== undefined) {
      out.gap = r.gap;
    }
    if (r.eof === true) {
      out.eof = true;
    }
    return out;
  }

  streamTail(bytes: number): {
    bytes: string;
    startCursor: number;
    endCursor: number;
    truncated: boolean;
  } {
    const buf = this.requireStreamBuffer();
    const r = buf.tail(bytes);
    return {
      bytes: r.bytes.toString("base64"),
      startCursor: r.startCursor,
      endCursor: r.endCursor,
      truncated: r.truncated,
    };
  }

  streamHead(bytes: number): {
    bytes: string;
    startCursor: number;
    endCursor: number;
    truncated: boolean;
  } {
    const buf = this.requireStreamBuffer();
    const r = buf.head(bytes);
    return {
      bytes: r.bytes.toString("base64"),
      startCursor: r.startCursor,
      endCursor: r.endCursor,
      truncated: r.truncated,
    };
  }

  async streamWaitFor(
    cursor: number,
    timeoutMs: number,
  ): Promise<"data" | "eof" | "timeout"> {
    const buf = this.requireStreamBuffer();
    return buf.waitForData(cursor, timeoutMs);
  }

  streamGrep(opts: RawStreamGrepOptions): RawStreamGrepResult {
    const buf = this.requireStreamBuffer();
    return buf.grep(opts);
  }

  streamInfo(): {
    writeCursor: number;
    oldestAvailable: number;
    capacity: number;
    closed: boolean;
  } {
    const buf = this.requireStreamBuffer();
    return {
      writeCursor: buf.writeCursorPos,
      oldestAvailable: buf.oldestAvailable,
      capacity: buf.capacity,
      closed: buf.isClosed,
    };
  }

  private requireStreamBuffer(): SessionStreamBuffer {
    if (this.streamBuffer === undefined) {
      const err = new Error(
        `session ${this.sessionId} has no stream buffer; POST /v1/sessions/:id/stdin/open first`,
      ) as Error & { code: number };
      err.code = JsonRpcErrorCodes.StreamNotEnabled;
      throw err;
    }
    return this.streamBuffer;
  }

  private markClosed(opts: { deleteRecord: boolean }): void {
    if (this.closed) {
      return;
    }
    // Close an open unsolicited turn while we can still broadcast, so
    // history never ends on a turn_started with no turn_ended after it.
    // Must precede the closing/closed flags for the broadcast to go out.
    this.closeUnsolicitedTurn("closed");
    if (this.armedExpiryTimer !== undefined) {
      clearTimeout(this.armedExpiryTimer);
      this.armedExpiryTimer = undefined;
    }
    const deleteRecord = opts.deleteRecord || this.deleteRecordIntent;
    opts = { deleteRecord };
    this.closing = true;
    this.closed = true;
    this.cancelIdleTimer();
    if (this.extensionCommandsUnsub) {
      this.extensionCommandsUnsub();
      this.extensionCommandsUnsub = undefined;
    }
    // Tell every in-flight extension command dispatch to release —
    // the session is going down, their commands/invoke will never
    // get a useful response, and their cleanup hooks need to fire.
    for (const messageId of [...this.inFlightExtensionDispatches.keys()]) {
      this.cancelExtensionDispatch(messageId, "abandoned");
    }
    // If a user-prompt turn is currently in-flight, synthesize a
    // turn_complete before clearing clients. This writes a proper close
    // record to history so clients that replay after a restart don't see
    // an open turn and get stuck in "busy" state. Skip if the entry's
    // turn has already terminated — runQueueEntry's catch broadcasts
    // turn_complete(error) on agent.kill()-driven rejection and runs in
    // a microtask that can settle BEFORE close()'s `await agent.kill()`
    // continuation. Without this dedup, the same prompt gets both
    // (error) and (interrupted) on the wire.
    if (
      this.currentEntry?.kind === "user" &&
      !this.recentlyTerminal.has(this.currentEntry.messageId)
    ) {
      this.broadcastTurnComplete(
        this.currentEntry.clientId,
        { stopReason: "interrupted" },
        this.currentEntry.messageId,
        this.currentEntry.wasAmend,
      );
    }
    this.currentEntry = undefined;
    // Drain any still-queued entries. Broadcast prompt_queue_removed
    // (abandoned) for user-visible ones so attached clients can drop
    // their chips, and resolve every entry's promise with cancelled so
    // callers awaiting the session/prompt response don't dangle. Do
    // this BEFORE notifying session_closed so the queue events arrive
    // ahead of the terminal signal.
    const stranded = this.promptQueue;
    this.promptQueue = [];
    for (const entry of stranded) {
      entry.cancelled = true;
      if (entry.kind === "user") {
        this.broadcastQueueRemoved(entry.messageId, "abandoned");
      }
      try {
        entry.resolve({ stopReason: "cancelled" });
      } catch {
        void 0;
      }
    }
    // Notify transformers the session is closing before we tear down.
    this.notifyChain("session.closed", {});
    // Edge-trigger state is per-session; release it.
    this.toolCompletionSeen.clear();
    this.toolCallKind.clear();
    this.filesEditedSeen.clear();
    // markClosed is the explicit-shutdown path (close() was called,
    // user typed /hydra kill, agent exited, idle timer fired, etc.).
    // The session is going cold; clear the persisted queue so it
    // doesn't get replayed on the next daemon start. Daemon-crash
    // paths bypass this and the queue file persists for restart
    // resurrection.
    const sessionId = this.sessionId;
    this.queueWriteChain = this.queueWriteChain
      .catch(() => undefined)
      .then(() => deleteQueue(sessionId).catch(() => undefined));
    for (const client of this.clients.values()) {
      void client.connection
        .notify("hydra-acp/session/closed", { sessionId: this.sessionId })
        .catch(() => undefined);
    }
    this.clients.clear();
    if (this.streamBuffer !== undefined) {
      const buf = this.streamBuffer;
      const path = this.streamFilePath;
      this.streamBuffer = undefined;
      this.streamFilePath = undefined;
      buf.close();
      if (path !== undefined) {
        void buf
          .drainFileWrites()
          .then(() => fsp.unlink(path).catch(() => undefined));
      }
    }
    for (const handler of this.closeHandlers) {
      handler(opts);
    }
  }

  // Last meaningful activity timestamp. Bumped only by recordable
  // broadcasts in recordAndBroadcast — the same signal historyMtimeIso
  // uses for the picker. Initialized at construction (and seeded from
  // the newest entry on resurrect) so the inactivity window starts
  // ticking from a sensible floor when there's no history yet.
  private get lastActivityAt(): number {
    return this.lastRecordedAt;
  }

  setAttentionFlag(source: string, reason: string, payload: unknown): void {
    this._setAttentionFlag(source, reason, payload, true);
  }

  private _setAttentionFlag(
    source: string,
    reason: string,
    payload: unknown,
    broadcast: boolean,
  ): void {
    const key = `${source}::${reason}`;
    const existing = this.attentionFlags.get(key);
    if (existing) {
      if (JSON.stringify(existing.payload) === JSON.stringify(payload)) {
        return;
      }
      this.attentionFlags.set(key, { ...existing, payload, raisedAt: existing.raisedAt });
    } else {
      this.attentionFlags.set(key, {
        source,
        reason,
        raisedAt: Date.now(),
        payload,
      });
    }
    if (broadcast) {
      this.broadcastAttentionUpdated();
      this.fireAttentionFlagsChange();
    }
  }

  clearAttentionFlag(source: string, reason: string): void {
    this._clearAttentionFlag(source, reason, true);
  }

  private _clearAttentionFlag(source: string, reason: string, broadcast: boolean): void {
    const key = `${source}::${reason}`;
    if (this.attentionFlags.delete(key)) {
      if (broadcast) {
        this.broadcastAttentionUpdated();
        this.fireAttentionFlagsChange();
      }
    }
  }

  listAttentionFlags(): AttentionFlag[] {
    return Array.from(this.attentionFlags.values()).sort(
      (a, b) => a.raisedAt - b.raisedAt,
    );
  }

  listAttentionFlagsBySource(source: string): AttentionFlag[] {
    return this.listAttentionFlags().filter((f) => f.source === source);
  }

  // Subscribe to attention flag changes. The SessionManager hooks this to
  // persist the updated flag list to disk so a daemon restart restores it.
  onAttentionFlagsChange(handler: (flags: AttentionFlag[]) => void): void {
    this.attentionFlagsChangeHandlers.push(handler);
  }

  private fireAttentionFlagsChange(): void {
    const flags = this.listAttentionFlags();
    for (const handler of this.attentionFlagsChangeHandlers) {
      try {
        handler(flags);
      } catch {
        void 0;
      }
    }
  }

  private broadcastAttentionUpdated(): void {
    for (const client of this.clients.values()) {
      void client.connection
        .notify("hydra-acp/session/attention_updated", {
          sessionId: this.sessionId,
          flags: this.listAttentionFlags(),
        })
        .catch(() => undefined);
    }
  }

  // (Re-)arm the idle timer to fire when the inactivity window
  // elapses past lastActivityAt. Called once at construction and after
  // every recorded broadcast. The previous design gated on
  // clients.size === 0; we drop that gate because extensions
  // (slack/notifier/approver/browser) hold persistent attaches that
  // would otherwise keep a quiet session alive forever.
  private scheduleIdleCheck(): void {
    if (this.closed || this.idleTimeoutMs <= 0) {
      return;
    }
    const dueAt = this.lastActivityAt + this.idleTimeoutMs;
    this.armIdleTimer(Math.max(0, dueAt - Date.now()));
  }

  private armIdleTimer(delay: number): void {
    if (this.idleTimer) {
      clearTimeout(this.idleTimer);
    }
    this.idleTimer = setTimeout(() => {
      this.idleTimer = undefined;
      this.checkIdle();
    }, delay);
    if (typeof this.idleTimer.unref === "function") {
      this.idleTimer.unref();
    }
  }

  private checkIdle(): void {
    if (this.closed || this.idleTimeoutMs <= 0) {
      return;
    }
    // Never abandon active work. An in-flight turn, unresolved
    // permission request, or non-empty prompt queue defers the close
    // by a full idle window — the next broadcast will re-arm us sooner
    // anyway, and this avoids a tight reschedule loop when activity is
    // stale but work is genuinely in flight or queued behind it.
    if (this.hasWorkInFlight) {
      this.armIdleTimer(this.idleTimeoutMs);
      return;
    }
    const idle = Date.now() - this.lastActivityAt;
    if (idle < this.idleTimeoutMs) {
      this.armIdleTimer(this.idleTimeoutMs - idle);
      return;
    }
    // A session that never received a prompt has no conversation to
    // preserve; drop the record entirely instead of leaving an empty
    // cold session cluttering the picker. Otherwise persist as cold —
    // the SessionManager.onClose hook will schedule a background
    // synopsis via the synopsis coordinator.
    const opts: CloseOptions = this.firstPromptSeeded
      ? { deleteRecord: false }
      : { deleteRecord: true };
    const idleSec = Math.round(idle / 1000);
    this.logger?.info(
      `session ${this.sessionId} idle timeout fired after ${idleSec}s (window=${Math.round(this.idleTimeoutMs / 1000)}s) — closing`,
    );
    void this.close(opts).catch(() => undefined);
  }

  private cancelIdleTimer(): void {
    if (this.idleTimer) {
      clearTimeout(this.idleTimer);
      this.idleTimer = undefined;
    }
    this.disposeIdleHandlers();
  }

  // ── Idle dispatch ────────────────────────────────────────────────────────
  //
  // Two consumers off the same "session went quiet" edge:
  //   - Compaction swap wants it RAW: fire immediately when no prompt is
  //     in flight (debounceMs=0, once=true).
  //   - The transformer-chain `session.idle` lifecycle event wants it
  //     DEBOUNCED: fire after a continuous quiet period of
  //     idleEventTimeoutMs (debounceMs>0, persistent — re-fires after
  //     the next activity→quiet cycle).
  //
  // Both ride on the same primitive: handlers are evaluated at every
  // quiesce dispatch (scheduled below). On a non-quiesced dispatch, any
  // pending debounce timers are cancelled — so a partial idle window
  // doesn't "leak" into the next quiesce.
  //
  // Returns a disposer the caller can use to deregister.
  // Hop depth of the turn this session is running right now, or
  // undefined when it isn't running one. A turn the user typed is 0; a
  // turn that arrived from a peer session carries whatever depth the
  // daemon stamped on it. Read when this session originates an outbound
  // message, so the chain can be bounded: an agent messaging a peer
  // while handling a peer's message is one hop deeper, and eventually
  // hits the cap instead of ponging forever.
  get currentPromptDepth(): number | undefined {
    if (this.currentEntry?.kind !== "user") {
      return undefined;
    }
    return this.currentEntry.originator.depth ?? 0;
  }

  // True while the session holds work that must not be abandoned: a
  // turn in flight, an unresolved permission request, or entries still
  // waiting on the queue. Every teardown path has to consult this, not
  // just the idle-close timer: a client that fires a prompt and detaches
  // immediately (hydra cat --no-wait) leaves a queued turn behind with
  // nobody attached, and killing the agent then loses it silently.
  get hasWorkInFlight(): boolean {
    return (
      this.turnStartedAt !== undefined ||
      this.hasPermissionFlag ||
      this.promptQueue.length > 0
    );
  }

  onIdle(
    fn: (s: Session) => void,
    opts?: { once?: boolean; debounceMs?: number },
  ): () => void {
    const entry = {
      fn,
      once: !!opts?.once,
      debounceMs: opts?.debounceMs ?? 0,
    } as { fn: (s: Session) => void; once: boolean; debounceMs: number; timer?: NodeJS.Timeout };
    this.idleHandlers.push(entry);
    return () => {
      const i = this.idleHandlers.indexOf(entry);
      if (i >= 0) {
        this.idleHandlers.splice(i, 1);
      }
      if (entry.timer) {
        clearTimeout(entry.timer);
        entry.timer = undefined;
      }
    };
  }

  // Sugar for onIdle(fn, { once: true }). Common case for "wait until
  // the session is quiet, then do this one thing."
  onceIdle(fn: (s: Session) => void): () => void {
    return this.onIdle(fn, { once: true });
  }

  // Evaluate registered idle handlers against the current quiesce state.
  // Uses the synchronous quiesce check (in-memory only) so debounce
  // timers can be scheduled at activity edges without an async hop —
  // critical for fake-timer-based tests, and cheap in production.
  // Consumers that need the stronger open-tool-call guarantee re-verify
  // via isQuiescedForSwap inside their handler.
  private dispatchIdle(): void {
    if (this.closed) {
      return;
    }
    const quiesced = this.isQuiescedSync();
    if (!quiesced) {
      // Cancel any pending debounce timers — a partial idle window
      // shouldn't carry over once activity resumes.
      for (const h of this.idleHandlers) {
        if (h.timer) {
          clearTimeout(h.timer);
          h.timer = undefined;
        }
      }
      return;
    }
    // Snapshot since once-handlers will splice themselves out.
    const snapshot = [...this.idleHandlers];
    for (const h of snapshot) {
      if (h.debounceMs === 0) {
        if (h.once) {
          const i = this.idleHandlers.indexOf(h);
          if (i >= 0) {
            this.idleHandlers.splice(i, 1);
          }
        }
        try {
          h.fn(this);
        } catch {
          // intentional: handlers own their own error handling
        }
        continue;
      }
      // Reset on every dispatch so a burst of recordable broadcasts
      // (each one calls dispatchIdle) restarts the debounce window —
      // matches the prior scheduleIdleEvent semantics for transformer
      // lifecycle events.
      if (h.timer) {
        clearTimeout(h.timer);
        h.timer = undefined;
      }
      h.timer = setTimeout(() => {
        h.timer = undefined;
        if (this.closed) {
          return;
        }
        if (!this.isQuiescedSync()) {
          return;
        }
        if (h.once) {
          const i = this.idleHandlers.indexOf(h);
          if (i >= 0) {
            this.idleHandlers.splice(i, 1);
          }
        }
        try {
          h.fn(this);
        } catch {
          // intentional
        }
      }, h.debounceMs);
      if (typeof h.timer.unref === "function") {
        h.timer.unref();
      }
    }
  }

  // Tear down every registered idle handler and its pending timer. Called
  // at close so timers don't fire on a dead session.
  private disposeIdleHandlers(): void {
    for (const h of this.idleHandlers) {
      if (h.timer) {
        clearTimeout(h.timer);
        h.timer = undefined;
      }
    }
    this.idleHandlers.length = 0;
  }

  // Inspect a session/update envelope and synthesize lifecycle edge events
  // for transformers that subscribe to them. Called from the agent's
  // session/update handler before the chain runs, so edges reflect what
  // the agent actually emitted (regardless of whether transformers later
  // drop the update via response chain `stop`).
  //
  // Currently synthesized:
  //   lifecycle:tool.completed — fires once per toolCallId when its
  //     tool_call_update first reports status="completed" or "failed".
  //     Payload: { toolCallId, status, kind?, content?, locations? }.
  //   lifecycle:file.edited — fires once per (session, path) for paths
  //     mentioned in an edit-kind tool_call/tool_call_update's
  //     locations[]. Payload: { path, toolCallId, line? }.
  private maybeEmitToolEdges(params: unknown): void {
    if (!params || typeof params !== "object") {
      return;
    }
    const update = (params as { update?: unknown }).update;
    if (!update || typeof update !== "object") {
      return;
    }
    const u = update as {
      sessionUpdate?: unknown;
      toolCallId?: unknown;
      status?: unknown;
      kind?: unknown;
      content?: unknown;
      locations?: unknown;
    };
    const kind = typeof u.sessionUpdate === "string" ? u.sessionUpdate : "";
    if (kind !== "tool_call" && kind !== "tool_call_update") {
      return;
    }
    const toolCallId =
      typeof u.toolCallId === "string" && u.toolCallId.length > 0
        ? u.toolCallId
        : undefined;
    if (!toolCallId) {
      return;
    }
    // Track tool kind from the first tool_call we see for this id, so
    // file.edited can gate on edit-kind even if a later tool_call_update
    // omits the kind field.
    const toolKind = typeof u.kind === "string" ? u.kind : undefined;
    this.toolCallKind.note(toolCallId, toolKind);
    const effectiveKind = this.toolCallKind.effective(toolCallId, toolKind);
    // file.edited: emit once per (session, path) for edit-kind tools.
    //
    // Deliberately the narrow `edit`-only rule, not tool-edit's broader
    // FILE_MUTATING_KINDS: PROTOCOL.md pins this event's contract to
    // `kind: "edit"`, so broadening it would change observable wire
    // behaviour for every attached transformer.
    if (effectiveKind === FILE_EDITED_EVENT_KIND && Array.isArray(u.locations)) {
      for (const loc of u.locations) {
        if (!loc || typeof loc !== "object") {
          continue;
        }
        const path = (loc as { path?: unknown }).path;
        if (typeof path !== "string" || path.length === 0) {
          continue;
        }
        if (this.filesEditedSeen.has(path)) {
          continue;
        }
        this.filesEditedSeen.add(path);
        // `line` is read inline rather than through tool-edit's path
        // helper: consumers disagree about it, legitimately. This event
        // passes through whatever the agent reported, while an editor-jump
        // consumer treats 0 as "no line" and floors the value. Sharing the
        // extraction would force one of those semantics on the other.
        const line = (loc as { line?: unknown }).line;
        const filePayload: Record<string, unknown> = { path, toolCallId };
        if (typeof line === "number") {
          filePayload.line = line;
        }
        this.notifyChain("file.edited", filePayload);
        this.reportIsolationBreach(path, toolCallId);
      }
    }
    // tool.completed: only fires on tool_call_update with terminal status.
    if (kind !== "tool_call_update") {
      return;
    }
    const status = typeof u.status === "string" ? u.status : undefined;
    if (status !== "completed" && status !== "failed") {
      return;
    }
    if (this.toolCompletionSeen.has(toolCallId)) {
      return;
    }
    this.toolCompletionSeen.set(toolCallId, status);
    const toolPayload: Record<string, unknown> = { toolCallId, status };
    if (effectiveKind) {
      toolPayload.kind = effectiveKind;
    }
    if (u.content !== undefined) {
      toolPayload.content = u.content;
    }
    if (Array.isArray(u.locations)) {
      toolPayload.locations = u.locations;
    }
    this.notifyChain("tool.completed", toolPayload);
  }

  // Send a lifecycle notification to every transformer in the chain that
  // declared the matching intercept. Fire-and-forget — no response expected.
  private notifyChain(event: string, payload: Record<string, unknown>): void {
    const intercept = `lifecycle:${event}`;
    for (const t of this.transformChain) {
      if (!t.intercepts.has(intercept)) {
        continue;
      }
      void t.connection
        .notify("hydra-acp/transformer/session_event", {
          event,
          sessionId: this.sessionId,
          payload,
        })
        .catch(() => undefined);
    }
  }

  // The agent's stdio connection is uniquely owned by this hydra session,
  // so any sessionId appearing on a message inbound from the agent
  // corresponds to this hydra session from an attached client's POV —
  // regardless of which internal session the agent considers it.
  //
  // Concretely: agents that multiplex multiple internal sessions over a
  // single stdio connection (opencode's @explore-style subagents, claude's
  // sub-thread tool calls) emit some messages with the *parent* upstream
  // sessionId (session/update notifications) and others with a *child /
  // foreign* sessionId (session/request_permission, see opencode
  // acp/permission.ts:63). The old gate `obj.sessionId === upstreamSessionId`
  // only rewrote the first case. The second was forwarded to attached
  // clients with the foreign id; the planner client couldn't resolve it to
  // a known hydra worker session and abstained (-32601), the daemon then
  // settled the permission as denied, and the subagent's tool call wedged
  // / aborted with no UI prompt ever shown to the user.
  //
  // Rewriting any non-self sessionId to this.sessionId fixes both cases.
  // It's safe because this method only runs on payloads flowing FROM the
  // agent OUT to attached clients — never the other direction — and the
  // agent's connection is 1:1 with this Session.
  private rewriteForClient(params: unknown): unknown {
    if (params && typeof params === "object" && !Array.isArray(params)) {
      const obj = params as Record<string, unknown>;
      if (typeof obj.sessionId === "string" && obj.sessionId !== this.sessionId) {
        return { ...obj, sessionId: this.sessionId };
      }
    }
    return params;
  }

  private recordAndBroadcast(
    method: string,
    params: unknown,
    excludeClientId?: string,
  ): void {
    const rewritten = this.rewriteForClient(params);
    // Snapshot-shaped updates (title, model, mode, available commands)
    // are broadcast live but deliberately not recorded. Their canonical
    // state lives in meta.json and is delivered to fresh clients via
    // the attach response _meta. Replaying historical transitions would
    // just churn client state through stale values en route to the
    // current one.
    const recordable = !isStateUpdate(method, rewritten);
    // Stamp every recordable session/update with a messageId so
    // after_message replay has resync anchors at every event boundary
    // — not just prompt_received / turn_complete. Non-recordable
    // events (state updates) skip this since they're not in history,
    // and explicit messageIds (set by broadcastPromptReceived /
    // broadcastTurnComplete) are preserved.
    const broadcast = recordable
      ? ensureMessageIdOnUpdate(method, rewritten)
      : rewritten;
    // Recorded entries carry their record time to clients under
    // _meta["hydra-acp"].recordedAt so a live listener and a replaying
    // listener date the same event identically. Only the wire payload is
    // stamped; `entry.params` (disk, transformer chain) stays clean, since
    // recordedAt is already a first-class column on CachedNotification and
    // the replay path re-derives the _meta from it.
    const recordedAt = Date.now();
    const wire = recordable ? withRecordedAt(broadcast, recordedAt) : broadcast;
    if (recordable) {
      const entry: CachedNotification = {
        method,
        params: broadcast,
        recordedAt,
      };
      this.lastRecordedAt = entry.recordedAt;
      this.appendCount += 1;
      // Disk is the source of truth for replay. Append is fire-and-forget;
      // failures (full disk, permission problems) shouldn't block the
      // live broadcast. Periodic compaction trims the file in place when
      // it grows past the cap.
      if (this.historyStore) {
        const store = this.historyStore;
        void store.append(this.sessionId, entry).catch(() => undefined);
        if (this.appendCount >= this.compactEvery) {
          this.appendCount = 0;
          void store.compact(this.sessionId, this.historyMaxEntries).catch(
            () => undefined,
          );
        }
      }
      // Fan the recorded entry out to any tail-style subscribers
      // (currently the HTTP /history?follow=1 stream). Synchronous
      // dispatch so a subscriber sees the entry in order; handlers
      // own their own error handling.
      for (const handler of this.broadcastHandlers) {
        try {
          handler(entry);
        } catch {
          void 0;
        }
      }
      this.scheduleIdleCheck();
      this.dispatchIdle();
    }
    this.updatedAt = Date.now();
    for (const client of this.clients.values()) {
      if (excludeClientId && client.clientId === excludeClientId) {
        continue;
      }
      void client.connection.notify(method, wire).catch(() => undefined);
    }
  }

  // Public wrapper for callers (e.g. transformers that need to surface
  // a permission prompt to a session's attached user-facing clients
  // even though the originating agent isn't on this session). Delegates
  // to the same broadcast-and-await logic the agent's own
  // session/request_permission goes through.
  async requestPermissionFromClients(params: unknown): Promise<unknown> {
    return this.handlePermissionRequest(params);
  }

  private async handlePermissionRequest(params: unknown): Promise<unknown> {
    const initialClients = [...this.clients.values()];
    if (initialClients.length === 0) {
      throw withCode(
        new Error("no clients attached to handle permission request"),
        JsonRpcErrorCodes.PermissionDenied,
      );
    }
    const clientParams = this.rewriteForClient(params);
    const toolCallId = extractToolCallId(clientParams);
    const requestId = generateMessageId();
    const { toolCall, options } = (clientParams as Record<string, unknown> | null) ?? {};
    return new Promise<unknown>((resolve, reject) => {
      let settled = false;
      const outbound: Array<{ client: AttachedClient }> = [];
      // Outstanding = clients we've broadcast to and are still awaiting.
      // Reject only when outstanding hits zero with no successful resolve;
      // a single client errored does NOT settle the request. This keeps
      // a misbehaving / transformer-attached client (e.g. the planner
      // self-attached to its own orchestrator session) from poisoning the
      // user TUI's vote with an early MethodNotFound. lastRealErr tracks
      // the most recent non-abstention failure so the eventual reject
      // surfaces something meaningful.
      let outstanding = 0;
      let lastRealErr: unknown;
      const sessionId = this.sessionId;

      const settle = (fn: () => void): void => {
        if (settled) {
          return;
        }
        settled = true;
        this.clearAttentionFlag("daemon", `permission:${requestId}`);
        this.permissionCallbacks.delete(requestId);
        fn();
      };

      const isAbstention = (err: unknown): boolean => {
        const code = (err as { code?: unknown } | null)?.code;
        return code === JsonRpcErrorCodes.MethodNotFound;
      };

      function sendTo(client: AttachedClient): void {
        if (settled) {
          return;
        }
        const response = client.connection.request<unknown>(
          "session/request_permission",
          clientParams,
        );
        outbound.push({ client });
        outstanding++;
        void response
          .then((result) => {
            outstanding--;
            settle(() => {
              const update = buildPermissionResolvedUpdate({
                toolCallId,
                result,
                resolver: client,
              });
              for (const o of outbound) {
                if (o.client.clientId === client.clientId) {
                  continue;
                }
                void o.client.connection
                  .notify("session/update", {
                    sessionId,
                    update,
                  })
                  .catch(() => undefined);
              }
              resolve(result);
            });
          })
          .catch((err) => {
            outstanding--;
            if (!isAbstention(err)) {
              lastRealErr = err;
            }
            if (outstanding === 0 && !settled) {
              const finalErr =
                lastRealErr ??
                withCode(
                  new Error("no client handled permission request"),
                  JsonRpcErrorCodes.PermissionDenied,
                );
              settle(() => reject(finalErr));
            }
          });
      }

      this.setAttentionFlag("daemon", `permission:${requestId}`, {
        kind: "permission",
        toolCall: toolCall ?? null,
        options: options ?? null,
      });
      this.permissionCallbacks.set(requestId, sendTo);

      for (const client of initialClients) {
        sendTo(client);
      }
    });
  }

  // Schedule an internal task (title regen, agent swap transcript
  // injection, import seed). Serializes behind any user prompts already
  // in flight, but doesn't emit prompt_queue_* broadcasts — clients
  // shouldn't see hydra's housekeeping in their chip list.
  private async enqueuePrompt(task: () => Promise<unknown>): Promise<unknown> {
    return new Promise<unknown>((resolve, reject) => {
      const entry: InternalQueueEntry = {
        kind: "internal",
        messageId: generateMessageId(),
        enqueuedAt: Date.now(),
        cancelled: false,
        task,
        resolve,
        reject,
      };
      this.promptQueue.push(entry);
      void this.drainQueue();
    });
  }

  // Schedule a user-originated session/prompt. Emits prompt_queue_added
  // immediately on enqueue (so peer clients can render the queued chip)
  // and prompt_queue_removed when the entry leaves the queue. The
  // returned promise resolves with the upstream agent's session/prompt
  // result, or { stopReason: "cancelled" } if the entry is dropped via
  // cancelQueuedPrompt before reaching the head.
  private async enqueueUserPrompt(
    client: AttachedClient,
    params: unknown,
    messageId: string,
    sentBy?: SentBy,
  ): Promise<unknown> {
    const promptArray = (((params ?? {}) as { prompt?: unknown[] }).prompt ??
      []) as unknown[];
    const originator: PromptOriginator = { clientId: client.clientId };
    if (client.clientInfo?.name) originator.name = client.clientInfo.name;
    if (client.clientInfo?.version)
      originator.version = client.clientInfo.version;
    if (sentBy?.fromSession) {
      originator.fromSession = sentBy.fromSession;
    }
    if (sentBy?.fromSessionTitle) {
      originator.fromSessionTitle = sentBy.fromSessionTitle;
    }
    if (sentBy?.fromLabel) {
      originator.fromLabel = sentBy.fromLabel;
    }
    if (sentBy?.depth !== undefined) {
      originator.depth = sentBy.depth;
    }
    // Read `_meta["hydra-acp"].queuePosition` to let callers select
    // where in the queue this entry lands. Defaults to "tail" (the
    // historical behavior — every prompt was pushed to the end).
    //
    //   "tail"  → push at the end (default).
    //   "head"  → unshift onto the front of the waiting queue (runs
    //             next, right after the in-flight currentEntry).
    //   { afterMessageId } → splice in immediately after a specific
    //             entry's messageId. Useful when an extension wants
    //             to schedule follow-up work tied to a user prompt's
    //             outcome. Falls back to "tail" if the id isn't in
    //             the queue.
    //
    // ACP-extensibility-compliant: lives under the vendor `hydra-acp`
    // key inside the standard `_meta`. Spec-compliant clients that
    // don't set it behave identically to before.
    const queuePosition = this.parseQueuePosition(params);
    return new Promise<unknown>((resolve, reject) => {
      const entry: UserPromptQueueEntry = {
        kind: "user",
        messageId,
        originator,
        clientId: client.clientId,
        prompt: promptArray,
        enqueuedAt: Date.now(),
        cancelled: false,
        resolve,
        reject,
      };
      const insertedAt = this.insertEntryAt(entry, queuePosition);
      this.persistRewrite();
      this.broadcastQueueAdded(entry, { position: insertedAt });
      void this.drainQueue();
    });
  }

  // True when session/prompt params assert `_meta["hydra-acp"].sentBy`.
  // Deliberately a presence check on the raw claim rather than a read of
  // the validated SentBy: the title heuristic runs before validation and
  // only needs to know "a program asserted provenance," not who.
  private promptCarriesSentBy(params: unknown): boolean {
    if (!params || typeof params !== "object") {
      return false;
    }
    const meta = (params as { _meta?: unknown })._meta;
    if (!meta || typeof meta !== "object" || Array.isArray(meta)) {
      return false;
    }
    const hydra = (meta as Record<string, unknown>)[HYDRA_META_KEY];
    if (!hydra || typeof hydra !== "object" || Array.isArray(hydra)) {
      return false;
    }
    const sentBy = (hydra as Record<string, unknown>).sentBy;
    return Boolean(sentBy) && typeof sentBy === "object";
  }

  // Parse the optional `_meta["hydra-acp"].queuePosition` field from
  // session/prompt params. Returns a normalized position descriptor
  // the queue-insertion code can act on. Defaults to "tail" when the
  // field is missing or malformed.
  private parseQueuePosition(
    params: unknown,
  ): "head" | "tail" | { afterMessageId: string } {
    if (!params || typeof params !== "object") return "tail";
    const meta = (params as { _meta?: unknown })._meta;
    if (!meta || typeof meta !== "object" || Array.isArray(meta)) return "tail";
    const hydra = (meta as Record<string, unknown>)["hydra-acp"];
    if (!hydra || typeof hydra !== "object" || Array.isArray(hydra)) return "tail";
    const raw = (hydra as Record<string, unknown>).queuePosition;
    if (raw === "head" || raw === "tail") return raw;
    if (raw && typeof raw === "object" && !Array.isArray(raw)) {
      const id = (raw as Record<string, unknown>).afterMessageId;
      if (typeof id === "string" && id.length > 0) {
        return { afterMessageId: id };
      }
    }
    return "tail";
  }

  // Insert `entry` into promptQueue at the requested position.
  // Returns the VISIBLE position the entry now occupies — that is,
  // counting currentEntry as position 0 if it exists and is user-
  // kind, then waiting entries from position 1 onward. Used for the
  // prompt_queue_added broadcast so peer clients render the chip
  // in the right slot.
  private insertEntryAt(
    entry: UserPromptQueueEntry,
    position: "head" | "tail" | { afterMessageId: string },
  ): number {
    const currentOffset =
      this.currentEntry?.kind === "user" && !this.currentEntry.cancelled
        ? 1
        : 0;
    if (position === "head") {
      this.promptQueue.unshift(entry);
      return currentOffset;
    }
    if (typeof position === "object") {
      const targetId = position.afterMessageId;
      const idx = this.promptQueue.findIndex((e) => e.messageId === targetId);
      if (idx >= 0) {
        this.promptQueue.splice(idx + 1, 0, entry);
        return currentOffset + idx + 1;
      }
      // Fall through to tail if the target wasn't found — better
      // than erroring out, since the target may have just completed.
    }
    this.promptQueue.push(entry);
    return currentOffset + this.promptQueue.length - 1;
  }

  // Rewrite the on-disk queue to reflect the current set of WAITING
  // entries (excluding currentEntry, the in-flight head). Excluding
  // the head is the key idempotency choice: once drainQueue shifts an
  // entry off and calls persistRewrite, a daemon crash mid-generation
  // will NOT re-run it on restart. Partial output (if any streamed
  // before the crash) stays in history; the prompt itself is lost
  // and the user can re-submit if they care.
  //
  // Snapshots in-memory state synchronously (so subsequent mutations
  // can't perturb what we're about to write) and chains the write
  // onto queueWriteChain so all persists are serialized.
  private persistRewrite(): void {
    const entries: PersistedQueueEntry[] = [];
    for (const entry of this.promptQueue) {
      if (entry.kind !== "user" || entry.cancelled) continue;
      entries.push(this.persistedFromEntry(entry));
    }
    const sessionId = this.sessionId;
    this.queueWriteChain = this.queueWriteChain
      .catch(() => undefined)
      .then(() => rewriteQueue(sessionId, entries).catch(() => undefined));
  }

  private persistedFromEntry(
    entry: UserPromptQueueEntry,
  ): PersistedQueueEntry {
    return {
      messageId: entry.messageId,
      originator: {
        clientInfo: {
          ...(entry.originator.name !== undefined
            ? { name: entry.originator.name }
            : {}),
          ...(entry.originator.version !== undefined
            ? { version: entry.originator.version }
            : {}),
        },
      },
      prompt: entry.prompt,
      enqueuedAt: entry.enqueuedAt,
    };
  }

  private async drainQueue(): Promise<void> {
    if (this.promptInFlight) {
      return;
    }
    this.promptInFlight = true;
    // Yield past the I/O phase before processing the first entry so
    // prompt_queue_added is sent in its own TCP write. Without this,
    // an idle session emits both added and removed{started} in the
    // same event loop tick and they can land in the same TCP packet —
    // the client's queue chip never visibly enters the "queued" state.
    await new Promise<void>((r) => setImmediate(r));
    try {
      while (this.promptQueue.length > 0) {
        // Session is tearing down (close() called, agent exited, idle
        // close fired). Bail before promoting the next entry — markClosed
        // will sweep the remaining queue with abandoned/cancelled. Without
        // this, close()'s await on agent.kill() lets drainQueue pick up
        // the head, broadcast prompt_received, and then markClosed (when
        // close() resumes) synthesizes a turn_complete(interrupted) for
        // a turn that was never actually started — the prompt looks alive
        // for one ms and dead the next on any replaying client.
        if (this.closing) {
          break;
        }
        // The agent may be mid-way through a turn it started by itself, in
        // which case promptInFlight says nothing about whether it's busy.
        // Wait for it to settle before handing it another prompt. Peeked
        // rather than shifted so the entry stays cancellable and
        // reorderable while we wait; the shift below re-reads the head,
        // which may be a different entry by then.
        const head = this.promptQueue[0];
        if (head?.kind === "user") {
          await this.holdForUnsolicitedTurn(head);
          if (this.closing) {
            break;
          }
        }
        const next = this.promptQueue.shift();
        if (!next) {
          break;
        }
        // Entry was cancelled while queued. The cancel path already
        // resolved the promise and broadcast prompt_queue_removed; we
        // just need to advance to the next entry. Defensive double-check
        // — the resolve here is harmless since cancelQueuedPrompt
        // already settled with cancelled stopReason.
        if (next.cancelled) {
          continue;
        }
        this.currentEntry = next;
        // Drop this entry from the persisted queue BEFORE invoking
        // the agent. If we crash mid-generation, restart sees no
        // record of it and doesn't re-run.
        if (next.kind === "user") {
          this.persistRewrite();
        }
        // Wire transition fires before task() so a fast task can't race
        // ahead of its own "started" broadcast.
        if (next.kind === "user") {
          this.broadcastQueueRemoved(next.messageId, "started");
        }
        try {
          const result = await this.runQueueEntry(next);
          next.resolve(result);
          // Yield past the I/O phase so the originator's session/prompt
          // response is sent in its own TCP write BEFORE we broadcast
          // prompt_queue_removed{started} for the next entry. A microtask
          // yield (Promise.resolve) is insufficient: both writes happen
          // before Node's I/O phase and can land in the same TCP packet.
          // When the client receives them together, the notification
          // handler (synchronous) runs before runPrompt's promise
          // continuation (microtask), so currentTurnEcho moves to M2
          // before M1's finally fires — the turn-complete guard fails and
          // M1's tools block stays at "thinking · Xs" / "stopped (amended)
          // · Xs". setImmediate waits until after the I/O phase, ensuring
          // the response is delivered before the next started fires.
          await new Promise<void>((r) => setImmediate(r));
        } catch (err) {
          next.reject(err as Error);
        } finally {
          this.currentEntry = undefined;
        }
      }
    } finally {
      this.promptInFlight = false;
      this.dispatchIdle();
    }
  }

  // Execute a queue entry. User-prompt entries forward to the upstream
  // agent and pair with broadcastTurnComplete; internal entries run
  // their captured task closure. Reads entry.prompt at dispatch time
  // so updateQueuedPrompt's mutations are honoured.
  //
  // For user entries, broadcastPromptReceived fires HERE — not in
  // Session.prompt — so peer clients see prompt_received only when the
  // turn actually starts (a deliberate deviation from a naive reading
  // of RFD #533; see the comment on broadcastPromptReceived). Order on
  // the wire: prompt_queue_removed{started} (already emitted by
  // drainQueue) → prompt_received → upstream session/prompt.
  private async runQueueEntry(entry: QueueEntry): Promise<unknown> {
    if (entry.kind === "internal") {
      // Housekeeping drives the agent too, so it likewise takes over from
      // any open unsolicited turn. The user-entry path does this from
      // broadcastPromptReceived, which internal entries deliberately skip.
      this.closeUnsolicitedTurn("superseded");
      return entry.task();
    }
    this.broadcastPromptReceived(entry);
    // Intercept daemon built-in slash commands here — after the prompt
    // has gone through the queue (echo flushed, prompt_received
    // broadcast) but before forwarding to the agent. This includes
    // `/hydra ...` which routes to handleSlashCommand for built-in
    // /hydra verbs and extension-registered commands.
    //
    // Trim trailing whitespace only — a leading space or newline
    // should escape the slash interception so users can send a
    // literal prompt like " /model ..." or a paste that happens to
    // start with a slash on a non-first line.
    const promptText = extractPromptText(entry.prompt).replace(/\s+$/, "");
    const slashFirstWord =
      !promptText.includes("\n") && promptText.startsWith("/")
        ? (promptText.split(/\s+/)[0] ?? "")
        : "";
    // Bare aliases: `/verb ...` transparently rewritten to
    // `/hydra verb ...` when `verb` is a safe non-colliding alias.
    // Reserved top-level names below are checked first so they always
    // win over any accidental alias.
    const bareWord = slashFirstWord.startsWith("/") ? slashFirstWord.slice(1) : "";
    // Bare-alias resolution excludes anything already handled by the
    // dedicated top-level switch below (hydra/model/mode/sessions/help)
    // and anything the underlying agent advertises — same reserved-set
    // logic that gates advertising in aliasableBareVerbs().
    const isBareAlias = bareWord.length > 0 && this.aliasableBareVerbs().has(bareWord);
    if (
      slashFirstWord === "/model" ||
      slashFirstWord === "/mode" ||
      slashFirstWord === "/sessions" ||
      slashFirstWord === "/help" ||
      slashFirstWord === "/hydra" ||
      isBareAlias
    ) {
      let result: unknown;
      if (slashFirstWord === "/sessions") {
        result = await this.handleSessionsCommand();
      } else if (slashFirstWord === "/help") {
        result = await this.handleHelpCommand();
      } else if (slashFirstWord === "/mode") {
        result = await this.handleModeCommand(promptText);
      } else if (slashFirstWord === "/model") {
        result = await this.handleModelCommand(promptText);
      } else if (isBareAlias) {
        const rest = promptText.slice(slashFirstWord.length).trim();
        const rewritten = rest ? `/hydra ${bareWord} ${rest}` : `/hydra ${bareWord}`;
        result = await this.handleSlashCommand(rewritten, entry.messageId);
      } else {
        // /hydra ... — dispatch via the shared handler, passing the
        // queue entry's messageId so extension commands can correlate
        // amends and other queue events back to their in-flight
        // dispatch.
        result = await this.handleSlashCommand(promptText, entry.messageId);
      }
      if (!this.closed) {
        this.broadcastTurnComplete(entry.clientId, result, entry.messageId, entry.wasAmend);
      }
      this.clearAmendIfMatches(entry.messageId);
      return result;
    }
    // A real agent turn closes the rollback window. Fire the hook before
    // the round-trip so the breadcrumb is gone on disk even if the turn
    // later fails or is cancelled.
    if (this.clearRollbackBreadcrumbHook) {
      try {
        this.clearRollbackBreadcrumbHook();
      } catch {
        void 0;
      }
    }
    // Unknown-slash escape. A single-line prompt starting with a slash
    // word the agent never advertised (`/etc/passwd`, `/usr/bin/foo`, a
    // typo'd command) is silently swallowed by agents like opencode,
    // which parse it as an unknown slash command and then no-op the whole
    // turn (opencode: acp/service.ts detectSlashCommand → unknown name →
    // end_turn with no work). Forward a copy prefixed with U+200B so the
    // text no longer starts with a slash. A leading *space* does not work:
    // detectSlashCommand trims first. ZERO WIDTH SPACE is not JS
    // whitespace, so it survives .trim() while staying invisible in the
    // rendered prompt. Only the copy sent upstream is escaped — the echo,
    // transcript and queue entry keep the user's original text. Gated on
    // the agent having advertised at least one command: agents that never
    // send available_commands_update may still implement commands, and we
    // must not escape those.
    let outboundPrompt = entry.prompt;
    if (
      slashFirstWord &&
      this.agentAdvertisedCommands.length > 0 &&
      !this.agentKnowsSlashCommand(slashFirstWord)
    ) {
      outboundPrompt = prefixPromptText(entry.prompt, SLASH_ESCAPE_PREFIX);
    }
    let response: unknown;
    this.agentTurnInFlight = true;
    try {
      // Workspace-isolated sessions: fix up paths and, where needed,
      // remind the agent which tree it is in. Applied here, on the way
      // to the agent, so the user's transcript keeps the words they
      // actually typed.
      outboundPrompt = this.applyWorkspacePromptRewrite(outboundPrompt);
      // Route through the transformer chain so transformers that register
      // a request:session/prompt intercept (e.g. the clarifier's deviation
      // injection) get to see and potentially rewrite the prompt before it
      // reaches the agent. forwardRequest handles rewriteForAgent
      // (sessionId → upstreamSessionId) and tail-forwards to the agent.
      response = await this.forwardRequest(
        "session/prompt",
        { sessionId: this.sessionId, prompt: outboundPrompt },
        entry.emitterName ? new Set([entry.emitterName]) : new Set(),
        entry.chainStartIdx ?? 0,
      );
    } catch (err) {
      // Deliberate force-cancel: the agent was killed on purpose. Resolve
      // the originator's prompt as cancelled (markClosed already broadcast
      // the interrupted turn_complete to peers) rather than surfacing the
      // raw "connection closed" error.
      if (this.forceCancelling) {
        this.clearAmendIfMatches(entry.messageId);
        return { stopReason: "cancelled" };
      }
      // Skip if markClosed already broadcast turn_complete for this entry
      // (session was closed while the request was in-flight).
      if (!this.closed) {
        this.broadcastTurnComplete(
          entry.clientId,
          { stopReason: "error" },
          entry.messageId,
          entry.wasAmend,
        );
      }
      this.clearAmendIfMatches(entry.messageId);
      throw err;
    } finally {
      this.agentTurnInFlight = false;
    }
    if (!this.closed) {
      this.broadcastTurnComplete(
        entry.clientId,
        response,
        entry.messageId,
        entry.wasAmend,
      );
    }
    this.clearAmendIfMatches(entry.messageId);
    return response;
  }

  // Clear amendInProgress once the cancelled turn's task has fully
  // settled. broadcastTurnComplete needs the marker still set when it
  // fires, so the clear must happen *after*. Called from runQueueEntry's
  // settle path for both success and error.
  private clearAmendIfMatches(messageId: string): void {
    if (this.amendInProgress?.cancelledMessageId === messageId) {
      this.amendInProgress = undefined;
    }
  }
}

function withCode(err: Error, code: number): Error & { code: number } {
  (err as Error & { code: number }).code = code;
  return err as Error & { code: number };
}

// session/update kinds that carry "what's currently true" snapshots
// rather than conversation events. Broadcast live but not recorded to
// history — the canonical state lives in meta.json and is delivered to
// fresh attaches via the attach response _meta.
//
// usage_update is included here so per-chunk live updates are NOT recorded
// by recordAndBroadcast (session.ts:5051) — recording every chunk tick would
// bloat history.jsonl with 13–62 entries per turn. Instead,
// recordCurrentUsageSnapshot() fires once at each turn boundary from within
// broadcastTurnComplete (session.ts:1933), writing a single usage_update to
// historyStore that survives on disk. That persisted entry is exposed via the
// GET /v1/sessions/:id/events endpoint (sessions.ts:1096) so analytics
// consumers like hydra-acp-budgeter can query per-turn cost data without
// parsing private on-disk formats.
const STATE_UPDATE_KINDS = new Set([
  "session_info_update",
  "current_model_update",
  "current_mode_update",
  "available_commands_update",
  "available_modes_update",
  "usage_update",
  // opencode's non-spec carrier for model/mode/config state. Its canonical
  // form is harvested into meta.json and re-synthesized on attach, so
  // recording it would just give never-prompted sessions a non-empty
  // history and make them look interactive in the picker.
  "config_option_update",
  // Ephemeral compaction-phase signals — never conversation history.
  "hydra_compaction",
]);

// How long an arming stays counted, given whatever timeout the agent
// reported. Falls back to the default when it reported none, and clamps to
// the ceiling for its kind either way. See all three constants for the
// reasoning; the short version is that a repeating watch has fewer ways to
// leave the set, so cutting it short shows a live job as idle.
export function armedTaskTtlMs(
  reportedTimeoutMs: unknown,
  repeating = false,
): number {
  const reported =
    typeof reportedTimeoutMs === "number" && reportedTimeoutMs > 0
      ? reportedTimeoutMs
      : ARMED_TASK_DEFAULT_TTL_MS;
  const ceiling = repeating
    ? ARMED_TASK_REPEATING_MAX_TTL_MS
    : ARMED_TASK_MAX_TTL_MS;
  return Math.min(reported, ceiling);
}

// Whether an arming is a repeating watch (a Monitor) rather than a one-shot
// (a backgrounded Bash). Decides both which ceiling above applies and
// whether a resumption discharges the entry, so getting it wrong is a
// visible false-idle either way.
//
// run_in_background vetoes first because it is the one unambiguous
// one-shot signal: it is a Bash parameter, Monitor has no such option, and
// a Bash reports its task id only in rawOutput prose, never in
// toolResponse.taskId. Tool identity is the primary positive signal since
// repeating-ness is a property of the tool, with the toolResponse.taskId
// shape as a fallback for the sparse late update that carries neither a
// title nor a toolName.
export function isRepeatingArming(
  title: unknown,
  claudeMeta: { toolName?: unknown; toolResponse?: { taskId?: unknown } } |
    undefined,
  rawInput: Record<string, unknown> | undefined,
): boolean {
  if (rawInput?.run_in_background === true) {
    return false;
  }
  return claudeMeta?.toolName === "Monitor" || title === "Monitor" ||
    typeof claudeMeta?.toolResponse?.taskId === "string";
}

// A backgrounded Bash reports its task id only in the tool call's rawOutput
// prose, never in `_meta.claudeCode.toolResponse.taskId` the way a Monitor
// does. Without digging it out, such an entry is stored with no id at all,
// which makes TaskStop clearing silently unreachable for the commonest kind
// of background task there is.
//
// Text-matching a vendor string, so deliberately narrow and fail-soft: a
// wording change costs the id, not correctness. Verified against 158
// occurrences in real session history, all of this exact shape.
function extractBackgroundBashTaskId(rawOutput: unknown): string | undefined {
  if (typeof rawOutput !== "string") {
    return undefined;
  }
  const m = /Command running in background with ID: ([A-Za-z0-9_-]+)/.exec(
    rawOutput,
  );
  return m?.[1];
}

// Read the `claudeCode` block out of an update's _meta. A vendor namespace,
// not ACP: it is the only place claude-acp reports the taskId of a
// background watch it just armed. Used for labelling an unsolicited turn,
// so every field is optional and a shape mismatch degrades to undefined.
function extractClaudeCodeMeta(
  meta: unknown,
): {
  toolName?: unknown;
  toolResponse?: { taskId?: unknown; timeoutMs?: unknown };
} | undefined {
  if (!meta || typeof meta !== "object" || Array.isArray(meta)) {
    return undefined;
  }
  const block = (meta as Record<string, unknown>).claudeCode;
  if (!block || typeof block !== "object" || Array.isArray(block)) {
    return undefined;
  }
  const obj = block as Record<string, unknown>;
  const out: {
    toolName?: unknown;
    toolResponse?: { taskId?: unknown; timeoutMs?: unknown };
  } = {};
  if (obj.toolName !== undefined) {
    out.toolName = obj.toolName;
  }
  if (obj.toolResponse && typeof obj.toolResponse === "object") {
    out.toolResponse = obj.toolResponse as {
      taskId?: unknown;
      timeoutMs?: unknown;
    };
  }
  return out;
}

function isStateUpdate(method: string, params: unknown): boolean {
  if (method !== "session/update") {
    return false;
  }
  const obj = (params ?? {}) as { update?: { sessionUpdate?: unknown } };
  const kind = obj.update?.sessionUpdate;
  return typeof kind === "string" && STATE_UPDATE_KINDS.has(kind);
}

function sameAdvertisedCommands(
  a: AdvertisedCommand[],
  b: AdvertisedCommand[],
): boolean {
  if (a.length !== b.length) {
    return false;
  }
  for (let i = 0; i < a.length; i++) {
    if (a[i]?.name !== b[i]?.name || a[i]?.description !== b[i]?.description) {
      return false;
    }
  }
  return true;
}

function sameAdvertisedModes(a: AdvertisedMode[], b: AdvertisedMode[]): boolean {
  if (a.length !== b.length) {
    return false;
  }
  for (let i = 0; i < a.length; i++) {
    if (
      a[i]?.id !== b[i]?.id ||
      a[i]?.name !== b[i]?.name ||
      a[i]?.description !== b[i]?.description
    ) {
      return false;
    }
  }
  return true;
}

function sameAdvertisedModels(
  a: AdvertisedModel[],
  b: AdvertisedModel[],
): boolean {
  if (a.length !== b.length) {
    return false;
  }
  for (let i = 0; i < a.length; i++) {
    if (
      a[i]?.modelId !== b[i]?.modelId ||
      a[i]?.name !== b[i]?.name ||
      a[i]?.description !== b[i]?.description
    ) {
      return false;
    }
  }
  return true;
}

// Parse a wire-shape availableModels list. Accepts the ACP-spec form
// (`{ modelId, name?, description? }`) and the opencode config_option
// form (`{ value, name?, description? }`) so a single helper handles
// both notification kinds. Entries missing a usable id are dropped
// silently — better to lose a malformed entry than poison the cache.
export function parseModelsList(list: unknown): AdvertisedModel[] {
  if (!Array.isArray(list)) {
    return [];
  }
  const out: AdvertisedModel[] = [];
  for (const raw of list) {
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
      continue;
    }
    const r = raw as Record<string, unknown>;
    const modelId =
      (typeof r.modelId === "string" && r.modelId.trim()) ||
      (typeof r.value === "string" && r.value.trim()) ||
      (typeof r.id === "string" && r.id.trim()) ||
      undefined;
    if (!modelId) {
      continue;
    }
    const model: AdvertisedModel = { modelId };
    if (typeof r.name === "string" && r.name.length > 0) {
      model.name = r.name;
    }
    if (typeof r.description === "string" && r.description.length > 0) {
      model.description = r.description;
    }
    out.push(model);
  }
  return out;
}

// Parse a config_option_update `mode` entry's `options` list into
// AdvertisedMode[]. Accepts the config-option value shape
// (`{ value, name?, description? }`) as well as the spec mode shape
// (`{ id, ... }`). Mirrors parseModelsList: malformed entries are
// dropped rather than failing the whole list.
export function parseModesList(list: unknown): AdvertisedMode[] {
  if (!Array.isArray(list)) {
    return [];
  }
  const out: AdvertisedMode[] = [];
  for (const raw of list) {
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
      continue;
    }
    const r = raw as Record<string, unknown>;
    const id =
      (typeof r.value === "string" && r.value.trim()) ||
      (typeof r.id === "string" && r.id.trim()) ||
      undefined;
    if (!id) {
      continue;
    }
    const mode: AdvertisedMode = { id };
    if (typeof r.name === "string" && r.name.length > 0) {
      mode.name = r.name;
    }
    if (typeof r.description === "string" && r.description.length > 0) {
      mode.description = r.description;
    }
    out.push(mode);
  }
  return out;
}

function extractAdvertisedModes(params: unknown): AdvertisedMode[] | null {
  const obj = (params ?? {}) as { update?: unknown };
  const update = (obj.update ?? {}) as {
    sessionUpdate?: unknown;
    availableModes?: unknown;
  };
  if (update.sessionUpdate !== "available_modes_update") {
    return null;
  }
  const list = update.availableModes;
  if (!Array.isArray(list)) {
    return [];
  }
  const out: AdvertisedMode[] = [];
  for (const raw of list) {
    if (!raw || typeof raw !== "object") {
      continue;
    }
    const m = raw as { id?: unknown; name?: unknown; description?: unknown };
    if (typeof m.id !== "string" || m.id.length === 0) {
      continue;
    }
    const mode: AdvertisedMode = { id: m.id };
    if (typeof m.name === "string") {
      mode.name = m.name;
    }
    if (typeof m.description === "string") {
      mode.description = m.description;
    }
    out.push(mode);
  }
  return out;
}

// Pull text out of an agent_message_chunk session/update notification
// and append it to a /hydra-slash-command's private capture buffer.
// Other update kinds (thoughts, tool calls, plans, etc.) are swallowed
// — we only need the prose reply.
function captureInternalChunk(
  capture: {
    chunks: string[];
    toolCalls: number;
    thinkingChars: number;
    messageChars: number;
    lastUsed?: number;
    lastSize?: number;
  },
  params: unknown,
): void {
  const obj = (params ?? {}) as { update?: unknown };
  const update = (obj.update ?? {}) as {
    sessionUpdate?: unknown;
    content?: unknown;
    used?: unknown;
    size?: unknown;
  };
  const kind = update.sessionUpdate;
  if (kind === "agent_message_chunk") {
    const content = (update.content ?? {}) as { text?: unknown };
    if (typeof content.text === "string") {
      capture.chunks.push(content.text);
      capture.messageChars += content.text.length;
    }
    return;
  }
  if (kind === "agent_thought_chunk") {
    const content = (update.content ?? {}) as { text?: unknown };
    if (typeof content.text === "string") {
      capture.thinkingChars += content.text.length;
    }
    return;
  }
  if (kind === "tool_call") {
    capture.toolCalls++;
    return;
  }
  if (kind === "usage_update") {
    if (typeof update.used === "number") {
      capture.lastUsed = update.used;
    }
    if (typeof update.size === "number") {
      capture.lastSize = update.size;
    }
    return;
  }
}

// Returns the agent-advertised command list when params is a session/update
// of kind available_commands_update; null otherwise. Used to intercept the
// agent's raw update so we can re-emit a merged (hydra ∪ agent) version
// to clients via broadcastMergedCommands.
function extractAdvertisedCommands(
  params: unknown,
): AdvertisedCommand[] | null {
  const obj = (params ?? {}) as { update?: unknown };
  const update = (obj.update ?? {}) as {
    sessionUpdate?: unknown;
    availableCommands?: unknown;
    commands?: unknown;
  };
  if (update.sessionUpdate !== "available_commands_update") {
    return null;
  }
  const list = update.availableCommands ?? update.commands;
  if (!Array.isArray(list)) {
    return [];
  }
  const out: AdvertisedCommand[] = [];
  for (const raw of list) {
    if (!raw || typeof raw !== "object") {
      continue;
    }
    const c = raw as { name?: unknown; description?: unknown };
    if (typeof c.name !== "string" || c.name.length === 0) {
      continue;
    }
    const cmd: AdvertisedCommand = { name: c.name };
    if (typeof c.description === "string") {
      cmd.description = c.description;
    }
    out.push(cmd);
  }
  return out;
}

// If `params` is a session/update with an `update` object that lacks
// a messageId, return a shallow clone with one stamped. Otherwise
// return `params` unchanged. Keeps the original caller-supplied
// object untouched so we don't surprise anyone holding a reference.
function ensureMessageIdOnUpdate(method: string, params: unknown): unknown {
  if (method !== "session/update" || !params || typeof params !== "object") {
    return params;
  }
  const p = params as { update?: unknown };
  if (!p.update || typeof p.update !== "object" || Array.isArray(p.update)) {
    return params;
  }
  const u = p.update as { messageId?: unknown };
  if (typeof u.messageId === "string") {
    return params;
  }
  return {
    ...(params as Record<string, unknown>),
    update: { ...(p.update as Record<string, unknown>), messageId: generateMessageId() },
  };
}

// Walk a history snapshot and find the index of the entry whose
// session/update.messageId matches `target`. Returns -1 if not found.
// Used by attach() to compute the after_message replay slice, and by
// SessionManager.forkSession to slice history at a turn boundary.
export function findMessageIdIndex(
  history: CachedNotification[],
  target: string,
): number {
  for (let i = 0; i < history.length; i++) {
    const entry = history[i];
    if (!entry || entry.method !== "session/update") {
      continue;
    }
    const params = entry.params as { update?: { messageId?: unknown } } | undefined;
    if (params?.update?.messageId === target) {
      return i;
    }
  }
  return -1;
}

// Pull `toolCallId` out of the `session/request_permission` params we
// forward to clients. The wire shape is `{ sessionId, toolCall: { toolCallId, ... }, options }`.
// Returns undefined if the params don't match (defensive — agents that
// emit a malformed request_permission would already be off-spec).
function extractToolCallId(params: unknown): string | undefined {
  if (!params || typeof params !== "object") {
    return undefined;
  }
  const toolCall = (params as { toolCall?: unknown }).toolCall;
  if (!toolCall || typeof toolCall !== "object") {
    return undefined;
  }
  const id = (toolCall as { toolCallId?: unknown }).toolCallId;
  return typeof id === "string" ? id : undefined;
}

interface PermissionResolvedBuildArgs {
  toolCallId: string | undefined;
  result: unknown;
  resolver: AttachedClient;
}

// Build the `update` body for a `session/update`/`permission_resolved`
// notification per RFD #533 (with our proposed `outcome` extension carried
// alongside the spec-literal `chosenOptionId`).
function buildPermissionResolvedUpdate(
  args: PermissionResolvedBuildArgs,
): Record<string, unknown> {
  const outcome = extractOutcome(args.result);
  const update: Record<string, unknown> = {
    sessionUpdate: "permission_resolved",
  };
  if (args.toolCallId !== undefined) {
    update.toolCallId = args.toolCallId;
  }
  if (outcome) {
    update.outcome = outcome;
    if (outcome.kind === "selected" && typeof outcome.optionId === "string") {
      update.chosenOptionId = outcome.optionId;
    }
  }
  update.resolvedBy = buildResolvedBy(args.resolver);
  return update;
}

interface OutcomeShape {
  kind: string;
  optionId?: string;
  reason?: string;
}

function extractOutcome(result: unknown): OutcomeShape | undefined {
  if (!result || typeof result !== "object") {
    return undefined;
  }
  const raw = (result as { outcome?: unknown }).outcome;
  if (!raw || typeof raw !== "object") {
    return undefined;
  }
  const kind = (raw as { kind?: unknown }).kind;
  if (typeof kind !== "string") {
    return undefined;
  }
  const out: OutcomeShape = { kind };
  const optionId = (raw as { optionId?: unknown }).optionId;
  if (typeof optionId === "string") {
    out.optionId = optionId;
  }
  const reason = (raw as { reason?: unknown }).reason;
  if (typeof reason === "string") {
    out.reason = reason;
  }
  return out;
}

function buildResolvedBy(client: AttachedClient): Record<string, unknown> {
  const out: Record<string, unknown> = { clientId: client.clientId };
  if (client.clientInfo?.name) {
    out.name = client.clientInfo.name;
  }
  if (client.clientInfo?.version) {
    out.version = client.clientInfo.version;
  }
  return out;
}

export function extractPromptText(prompt: unknown): string {
  if (typeof prompt === "string") {
    return prompt;
  }
  if (!Array.isArray(prompt)) {
    return "";
  }
  return prompt
    .map((b) => {
      if (b && typeof b === "object" && typeof (b as { text?: unknown }).text === "string") {
        return (b as { text: string }).text;
      }
      return "";
    })
    .join("");
}

// ZERO WIDTH SPACE. Prefixed to a prompt that would otherwise be parsed
// as an unknown slash command by the agent. Invisible when rendered and,
// unlike a space or newline, not stripped by String.prototype.trim().
export const SLASH_ESCAPE_PREFIX = "\u200B";

// Return a copy of a prompt with `prefix` prepended to its first text
// block. Non-text blocks (resource links, images) and the rest of the
// blocks are left untouched. Returns the input unchanged when there is no
// text block to prefix.
/**
 * Apply a text transform to every text block of a prompt.
 *
 * Every block, not just the first: a path can appear in any of them, and
 * missing one would hand the agent an absolute source-tree path that
 * survives the rewrite.
 */
export function mapPromptText(
  prompt: unknown[],
  fn: (text: string) => string,
): unknown[] {
  return prompt.map((b) => {
    if (b && typeof b === "object" && typeof (b as { text?: unknown }).text === "string") {
      const block = b as { text: string };
      return { ...block, text: fn(block.text) };
    }
    return b;
  });
}

export function prefixPromptText(prompt: unknown[], prefix: string): unknown[] {
  const idx = prompt.findIndex(
    (b) => b && typeof b === "object" && typeof (b as { text?: unknown }).text === "string",
  );
  if (idx < 0) {
    return prompt;
  }
  const block = prompt[idx] as { text: string };
  const copy: unknown[] = [...prompt];
  copy[idx] = { ...block, text: `${prefix}${block.text}` };
  return copy;
}

// Default response when a transformer returns { action: "stop" } on a
// request without providing a payload. session/prompt uses stopReason so
// a queueing caller unblocks cleanly; everything else gets an empty object.
function defaultStopPayload(method: string): Record<string, unknown> {
  if (method === "session/prompt") {
    return { stopReason: "stopped" };
  }
  return {};
}

// Default response when a transformer returns { action: "stop" } on an
// agent→client request without providing a payload. For
// session/request_permission the ACP-canonical "user declined" shape is
// { outcome: { outcome: "cancelled" } }; the agent treats this as a
// normal denial. Other agent→client methods get an empty object.
function defaultAgentRequestDeny(method: string): Record<string, unknown> {
  if (method === "session/request_permission") {
    return { outcome: { outcome: "cancelled" } };
  }
  return {};
}

// First non-empty line of `text`, truncated to `max` chars with a
// trailing ellipsis if needed. Used to seed a session title from the
// first user prompt's leading line.
// Render one configOption as a header line (`id  (Name) — ▶ currentValue`)
// followed by an indented choice list where the current value is marked
// with ▶ and others with ·, and the human-readable `name` is right-padded
// against the longest `value` for vertical alignment. Used by both the
// no-arg listing and the single-id show path in /hydra config.
function renderConfigOptionBlock(o: ConfigOption): string {
  const header =
    o.name && o.name !== o.id
      ? `${o.id}  (${o.name}) — \u25b6 ${o.currentValue}`
      : `${o.id} — \u25b6 ${o.currentValue}`;
  if (o.options.length === 0) {
    return header;
  }
  const valueWidth = Math.max(...o.options.map((c) => c.value.length));
  const rows = o.options.map((c) => {
    const marker = c.value === o.currentValue ? "\u25b6" : "\u00b7";
    const showName = c.name && c.name !== c.value;
    const valueCell = showName ? c.value.padEnd(valueWidth) : c.value;
    return showName ? `  ${marker} ${valueCell}  ${c.name}` : `  ${marker} ${valueCell}`;
  });
  return `${header}\n${rows.join("\n")}`;
}

export function firstLine(text: string, max: number): string | undefined {
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line) {
      continue;
    }
    return line.length > max ? `${line.slice(0, max)}…` : line;
  }
  return undefined;
}
